                        memcpy(structIn + 16, &marker, 8);
                        for (int i = 24; i < 64; i++) structIn[i] = (uint8_t)(i & 0xFF);

                        memset(scalarOut, 0, sizeof(scalarOut));
                        scalarOutCnt = 16;
